/* 平成22年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h22.committeeSessions.push(...[{"id":"h22-20100510-6","meetingId":"h22-cm05","date":"2010年5月10日","dateIso":"2010-05-10","committee":"区民委員会","time":"午後１時０２分～午後 ２時１２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"三上委員","kind":"質問・要望","question":"ですから、１調査区というのは、何名くらいとかというのを１つの基準くらいに考えていらっしゃるんでしょうか。とにかくそういうお手伝いいただいたことについては、どういうふうに考えていらっしゃるのか、そこのところをちょっとお教えいただきたい。","respondent":"中山地域活動課長","answer":"２調査区をお受けいただく調査員の方については、７万４,０００円という形です。もう既に説明会の中で、もちろんそれは構いませんということを説明しているわけでございまして、今申し上げたような若干の報酬の違いが出てくるです。","id":"exchange-001"},{"speaker":"三上委員","kind":"意見","question":"どうしてもマンションによっては、１人で３００世帯ぐらい持たざるを得ないとかという、かなり無理な部分が出てくる可能性もあるわけです。ただし、別の棟を軒並み歩き回って用は足りるという部分もあるのかわからないけれども…","respondent":"中山地域活動課長","answer":"ここは調査が難しいということであれば、やれるというところについて、今申し上げたようなおおむね均等するような形での割り振りをしています。やれないというところについては、冒頭の説明で申し上げたとおり、区で登録調査員…","id":"exchange-002"},{"speaker":"三上委員","kind":"質問・要望","question":"依頼の件については、もう既にそういう話題、町会としてはなっていますので、やはりなるべく早く、今回についてはこういうふうにお願いしていきたいというのは、少しでも早く地元にお願いしていっていただきたいなと、それがまたうまくいく方法でもあるのかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"南副委員長","kind":"質問","question":"総合相談窓口だとか、その辺を伺いたいと思っているんですけれども、八潮南小学校跡地に地域活動の交流施設ができますよね。あんまりよく見えてこないところなので、もし違ったらいいんですけれども、教えてほしいと求めました。","respondent":"秋山協働・国際担当課長","answer":"最初の１年目の検討会、協働の考え方とか、なかなかまとまらなかったと聞いてあります。検討中ですけれども、ＮＰＯ、区民の活動団体の１つの活動拠点の支援という形の場所と考えています。","id":"exchange-004"},{"speaker":"南副委員長","kind":"質問","question":"そういう窓口というのは本庁に近い、そのあたりの考え方、今のところ区が持っておられる考え方みたいなものをちょっと教えてほしいと求めました。一人一人の持っているイメージがそれこそ違う部分ですから、漠然としているんですけれども、教えてほしいと求めました。","respondent":"秋山協働・国際担当課長","answer":"これにつきましても、当然場所ですとか、その他も含めて、これから検討をしていく必要もあるかなと考えているところです。こういった協力、１つの共通の理解ができるのではないかということで、品川らしい協働が見えてくるとしたと伺わせていただいたところです。","id":"exchange-005"},{"speaker":"三上委員","kind":"質問","question":"だから、もっと丁寧にずっと広げて、自由にどうぞという部分というのをお互い呼びかけしてもいいんじゃないかと感じがしてならないんです。だから、そこらあたりの幅を少しずつ広げていくということについての取り組みについてはどういうふうに考えていかれるんですか、今後の部分で。","respondent":"秋山協働・国際担当課長","answer":"区民の方５００名、そこはキャパシティーが５００名なので、４００人近く参加されました。今後なるべく外国人と日本人が気軽に参加できるようなイベント、ないしは場をつくっていきたい、そういう方向で進めていきたいと考えております。","id":"exchange-006"},{"speaker":"南副委員長","kind":"質問","question":"ですから、１カ所でやるのではなくて、説明を聞きながら思ったんです。女性ですから、対応言語ということでこれら４つを出しているけれども、その辺はどういうふうに考えておられるか伺いたいなと思います。","respondent":"秋山協働・国際担当課長","answer":"去年は１カ所、荏原地区の区内３カ所を今計画しておりまして、それぞれで日本人の方と外国人の方が交流するというのを予定しています。多言語の対応ですけれども、いろいろな研修会等でも情報がなかなか入ってこないというのが、話として外国人からも出ております。","id":"exchange-007"},{"speaker":"渡部委員","kind":"確認","question":"これはもう機械が壊れているわけですから、１回リセットをかけても、毎回暫定対応をしていくのかどうか。そういう方がまた名乗り出てもらえるような対策がとられているのかどうかなのかちょっと説明を求めました。","respondent":"矢部生活安全担当課長","answer":"現在までのリセットの状態ですけれども、数字的に言いますと、３００を超えるぐらいのリセットを現在実施しています。学校への周知ですけれども、この４月２２日に各学校、現在設置中の問い合わせ窓口に問い合わせをするようにということでお知らせをしたところです。","id":"exchange-008"},{"speaker":"南副委員長","kind":"質問","question":"紹介していただいて、ありがとうあります。これは前回平成１８年の調査をもとに行ったと、製造業の工場だけという理解でいいんですか、その辺。","respondent":"福島ものづくり・経営支援課長","answer":"３,６２３、工業統計調査を行っていますので、それからの抜粋です。その前の事業所統計調査につきましては、工場を持たなくてもカウントされているというものです。","id":"exchange-009"}]},{"id":"topic-02","title":"番、その他を行います。 その他","agenda":"番、その他を行います。 その他","exchanges":[{"speaker":"南副委員長","kind":"質問","question":"これは９月に解体なんですけれども、住民説明会だとか、そういう日程はどういうふうになっているのか、その点だけちょっと説明を求めました。","respondent":"堀越文化スポーツ振興課長","answer":"これから地域に周知する予定ですが、７月に入りましたら、説明会をするという予定です。","id":"exchange-010"},{"speaker":"三上委員","kind":"質問","question":"３つの学校が、今までやっているスポーツ団体の人たちというのが、さらにまた活動が縮小させられるという現状になりかねないと非常に心配しています。ですから、現荏原平塚中学校ももちろんやってほしいんですけれども、体育館を残すわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"三上委員","kind":"質問・要望","question":"どういう状況だったのかという説明をしていただいてもいいんじゃないかと思うものですから、この場で決めるというのもあれでしょうから、簡単でいいですから。","respondent":"福島ものづくり・経営支援課長","answer":"この場で報告するのはなかなか難しいかと思いますけれども、機会があればと思います。","id":"exchange-012"},{"speaker":"南副委員長","kind":"質問・要望","question":"いろいろなご要望とか、ご意見なんかも申し上げたいと考えていますし、また次回の委員会に引き継いでいければいいかなとも思っております。１年間本当にありがとうございました。","respondent":"川西委員長","answer":"以上をもちまして、本日の予定はすべて終わりました。○午後 ２時１２分閉会","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/397696?Template=document&Id=2578#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":21557,"voices":53}},{"id":"h22-20100510-7","meetingId":"h22-cm05","date":"2010年5月10日","dateIso":"2010-05-10","committee":"厚生委員会","time":"午後１時０２分～午後２時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"１ゆたかシルバーセンターの改修","agenda":"１ゆたかシルバーセンターの改修","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それから、だれでもトイレが新設ということで、歓迎したいんですが、前は、ここに何があったのか知りたいです。主に出された意見、質問でもいいんですが、どんな内容だったのかお伺いします。","respondent":"間部高齢者いきがい課長","answer":"説明会での周知ですが、１月２５日の説明会につきましては、説明会のご案内をさせていただいたところです。先ほどもご説明いたしましたが、３月以降、リニューアルオープンしたときの優先予約の状況についてのご質問があったです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"改めて教えていただきたいんですが、どういうグループで、説明してほしいと求めました。２階なんですが、いすやテーブルなども用意されるかなと思うんですが、それは何人分ぐらい用意される予定なのか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"当然、平成２２年度に使用している団体につきましては、あいていたらまた新規の団体について入ってきていただくということを考えているところです。主に５０人規模で使われることが多いということと、２階の洋室については…","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"２階に限らないんですが、もう少し広く使いたい、大きな人数が集まれる会場がないでしょうかという声や要望も聞いているんです。例えば、この２階をパーテーションか何にして、横断的にぶち抜いて使えるような状況はつくれないかなと思うんですけれども、いかがか尋ねました。","respondent":"間部高齢者いきがい課長","answer":"１階にあります健康室と和室がほとんど個人の利用ということでございまして、一つ、和室は残したところです。２階は、委員がおっしゃられた案については、ちょっと難しいかなと考えています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった要望も聞いておりますので、そういった要望も聞いておりますので、何とか少しご検討してほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"石田委員","kind":"質問","question":"お考えにあると思うんですが、ほかのシルバーセンターで、段差がいまだに残っているところはあるんでしょうか。その２点、説明を求めました。","respondent":"間部高齢者いきがい課長","answer":"多くのシルバーセンターが昭和４０年から５０年にかけて建設されているということで、徐々に、バリアフリー対応ということで進めているものです。２階の洋室のカーペート敷きで筋肉トレーニングがなぜかということなんですが、このような対応をとるものです。","id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"２階が、その辺が、どういうお部屋の使い方になるのか。１０から２０のサークルの団体があると聞いたんですが、どういうふうにすみ分けをされるのかという点を、説明を求めました。","respondent":"間部高齢者いきがい課長","answer":"なぜ設置されないのかという理由なんですけれども、基本的には設置するものだと、必要性があると認識をしているところではあります。特に予防器具を常時設置しておいて使うという関係がございまして…","id":"exchange-006"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"もしどうしてもだめだったら、ぜひエレベーターを再検討していただきたいと、もう１回お願いしたい。段差があるのかどうか、そこをもう１回、説明を求めました。","respondent":"間部高齢者いきがい課長","answer":"今後の工事に際しましては、いろいろな要素を検討いたしまして、できる限り設置をするような努力はしていきたいと考えています。そのように認識をしています。","id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"軽く出し入れしやすいものを、ぜひ、選んでいただきたいとお願いして終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問","question":"平成２３年１月から、どこかほかを使っていることもわかるでしょうから、ぜひ漏れのないようにお願いしたいと思います。１団体の登録人数は、把握できていたら、教えてもらいたいと思います。","respondent":"間部高齢者いきがい課長","answer":"昨年度、工事をいたしました旗の台でも、同じような取扱いをしていますので、この辺については、きちんと周知をしてまいりたいと考えています。利用については、上から２番目ぐらいに多い利用率が出ておりますので、かなり活発に使われている施設だと言えると思います。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"忘れてしまいまして、やっぱり高齢者向けの施設ですから、何としても努力をしていかなくちゃいけないところなのではないかと思って聞いていたんです。１基つけるのに、どれぐらい費用がかかるものなのか、ちょっと教えていただきたい。","respondent":"間部高齢者いきがい課長","answer":"そういった点では、何が何でもつかないということではありませんで、条件が合致すれば、私どもとしては、設置をすると考えています。エレベーター１基つけると幾らかというお話ですが、中付けか外付けかでも異なりますが、おおむね数千万円はかかると認識をしています。","id":"exchange-010"}]},{"id":"topic-02","title":"２番目の日本脳炎ワクチン予防接種の勧奨再開","agenda":"２番目の日本脳炎ワクチン予防接種の勧奨再開","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"平成１７年に厚生労働省から、平成２２年４月１日付で、勧告と通知の違いというのは何なんでしょうか。満４歳と９歳のときは、そういった接種票の郵送などは行わないのでしょうか、お伺いします。","respondent":"吉田保健予防課長","answer":"３歳児ということの解釈が、国に問い合わせたところ、３歳の年齢に相当する者という回答しかいただいておりません。４歳の方への通知というのは、３歳、それからこれから３歳になる方のみの通知です。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと初歩的なことで恐縮なんですが、３歳、４歳、９歳のときに予防接種を受けないと効果が出ないものなのでしょうか。ほかの定期予防接種がどういうふうに通知されているのかも、ちょっとご説明いただきたいんですが、いかがか尋ねました。","respondent":"吉田保健予防課長","answer":"ただ、今回、５年間接種を控えてきたということで、ワクチンの製造が追いつかないといったことから、３歳のみ、勧奨を行うといった内容での通知です。対象の年齢の方、お誕生日を迎えた月の大体上旬になりますが…","id":"exchange-012"},{"speaker":"金野委員","kind":"質問・要望","question":"平成１７年から今日に至るまでの子どもへの対応は、どのようにお考えなのか、それが１点。国としてはどうなっているのか、どうなっていくのか、教えてほしいと求めました。","respondent":"吉田保健予防課長","answer":"特に接種が行われていない子どもへの対応についてですが、厚生科学審議会等で検討し、国としても対応を図ると聞いております。２期につきましても、今後、知見を集積して対応を図ると、国は申しておりますので、その対応を見守っていきたいと考えています。","id":"exchange-013"},{"speaker":"金野委員","kind":"質問","question":"そうすると、１期目の薬と２期目の薬と違うということなんでしょうか。同じ日本脳炎を予防するのに、ワクチンが違うというのが、そこら辺がわからないので、ちょっと説明を求めました。","respondent":"吉田保健予防課長","answer":"１期につきましては接種ができるという状況ですので、積極的な勧奨は行いませんが、自主的にお受けいただくということは可能な状況です。効果といったものについても、厚生科学審議会等で検討すると聞いておりますので、そちらも注意深く見守ってまいりたいと考えています。","id":"exchange-014"},{"speaker":"金野委員","kind":"意見","question":"平成１７年から２１年の間、自分たちがどうなのかと、ちょっと不安になる方もあるやに思います。今の段階では３歳児、あるいは３歳になる子どもだけですので、どのようにされていくのかとの意見を述べました。","respondent":"吉田保健予防課長","answer":"実際、近いうちに、品川区内の医師会とは、方法については検討していく予定です。郵送するということができない関係で、ご希望の方について、私どものほうでご連絡いただいた段階で発行するというような形になると思います。","id":"exchange-015"},{"speaker":"金野委員","kind":"意見","question":"きめ細かな対応でお考えだと思いますが、ぜひ、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"５年間だからどうとは言い切れないところがあるんですけれども、その辺がどうなっているのか、ちょっと教えていただきたい。もう１点、ワクチン接種の費用は、今、お幾らぐらいになっているんか尋ねました。","respondent":"吉田保健予防課長","answer":"ただ、６カ月から９０カ月を外れた方につきましては、自己負担が生じるということになります。その際には、１回、約８,５００円程度かかるということになります。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問・要望","question":"対象が外れたところの８,５００円というのは、対象外の方になるべく影響が及ぼさないような形で、希望があればできるようにやってほしいと思います。だから、区でやりなさいということは、今、求めていませんけれども、その辺、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問","question":"かかってしまった場合、どのぐらいの率で亡くなるのか、その辺がわかったら。３０歳から６０歳後半ぐらいの人がすごく下がっているとか、わかっていたら、説明を求めました。","respondent":"吉田保健予防課長","answer":"ですから、１％から０.１％の方が発病すると言われております。この年代がどうかということは申し上げられない状況ですが、やはりワクチンを打っていない年代については、かなり低いということが言えます。","id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問","question":"５年間受けないでいて、受けないとどうなんだろうかと、きちんとお知らせをしてほしいと思うんです。勧奨が始まったということは、とにかく受けたほうがいいという受けとめ方でよろしいんか尋ねました。","respondent":"吉田保健予防課長","answer":"かなり多くの患者が報告されているということで、流行地域に当たる日本におきましても、やはり積極的に打ったほうよろしいだろうと考えられています。ということで、今回、ワクチンの勧奨再開という運びになったと認識しております。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"確認","question":"広域連合のほうの処理なので、品川区は直接ではないと思うんですけれども、郵送が届いた中で、品川区に対しての質問はなかったのかということが１点。その２点、確認だけ。","respondent":"本城国保医療年金課長","answer":"二重に振り込まれた方から約２０件ほどお問い合わせがあり、１０件ほどのお問い合わせが、直後の１週間ぐらいの間にありました。それから、回収の方法についてですが、広域連合が主体となって、広域連合の職員で回収の徹底を図るです、そのように伺っております。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ただ、品川区にやっぱり問い合わせがあるという中では、これからもまた大変かと思うんですが、よく説明をお願いしたいと思います。これは要望にします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"そういった今回のケースで、対応は可能なのかどうか、お伺いします。ミスにそぐう対策にしないと再発防止にならないのではないかと思うんですけれども、その辺は、どのように聞いておられるのか尋ねました。","respondent":"本城国保医療年金課長","answer":"ご説明させていただいたことと重なりますが、納入通知書をご本人あてに送付して、それでお金を返していただくということで対応するです。誤ったのが、消えてしまった分が３,５２７件おくれて…","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区としても情報収集などしていただきたいんですが、ないように、ぜひ働きかけてほしいと求めました。その辺がちょっとわからないので、そこをちょっと聞きたかったのです、すみません。","respondent":"本城国保医療年金課長","answer":"広域連合のほうからお電話等、連絡を取って、ご協力をお願いしていくです。２３区の部長会の代表のほうから、今回の件の適切な対応等、それから再発防止策の徹底等について申入れを行うと確認しています。","id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"件数は伺ったんですが、総額で幾らぐらいになったのか、教えていただきたい。それから、決算のところで響かないのか、ちょっとそこを説明を求めました。","respondent":"本城国保医療年金課長","answer":"保険給付の一環としての給付ということで、返還してもらうことによって、基本的に年度中に解決していくと考えていると認識しています。今回、５月末をめどにご返還いただくというスケジュールで進んでいると伺っているところです。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/360687?Template=document&Id=3266#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":18992,"voices":67}},{"id":"h22-20100510-8","meetingId":"h22-cm05","date":"2010年5月10日","dateIso":"2010-05-10","committee":"建設委員会","time":"午後１時０２分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件整理しています。","topics":[{"id":"topic-01","title":"でございます。初めに、１のしながわＥＣＯフェスティバル２０１０の開催","agenda":"でございます。初めに、１のしながわＥＣＯフェスティバル２０１０の開催","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"今回でＥＣＯフェスティバルは何回目になるのかということが１点と、目的について書いてないんですけれども、もう何回もやっているからわかっているでしょということで目的を書かないのかと思うんですけれども、改めてこのフェスティバルの目的についてお伺いします。","respondent":"工藤環境課長","answer":"こちらを含めますと、中央公園での６回を含めて全部で２０回目ということで、もう２０年続いているイベントです。目的といたしましては、そして最終的にはエコについて理解していただいて行動まで移していただく、そのようなイベントを目指しています。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"その目的がどのように実現されているのか、区民に対してどういう効果があったのかというのは、何で調べているのか。調査しているとか、どこで判断をしているのかちょっとわからないので、その辺について説明を求めました。","respondent":"工藤環境課長","answer":"次年度にやるときにはその一覧の中で検討をして、レベルアップをしていくという仕組みになっております。考えさせるイベントとしていきたいという部分を指導しておりますし、そういった意味で出店者からご意見を聞きながら、効果を見ているところです。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"来てくれる区民のほうの効果はどうなんでしょうかということと、エコで何かできることなどが出てくるのではないか。この２点を伺います。","respondent":"工藤環境課長","answer":"ご質問がありました住宅課との連携も、事業の施策で必要になってきます。その部分に関しましては、その中でブースを出していきながら、区役所一体となってＰＲをしていくという方針で考えております。","id":"exchange-003"},{"speaker":"武内委員","kind":"質問","question":"今年は連携ということで、去年より小規模になっちゃうことについて何か工夫とかがあるのかどうか教えてください。一応これで終わりということになるのか、今後のこともあるのでわからないとは思うけれど、その辺をちょっと説明を求めました。","respondent":"工藤環境課長","answer":"今年は２０団体ぐらいということで規模自体は少し小さくなりますけれど、内容が重ならないような形で工夫することを考えているところです。２点目の来年度以降の見通しですけれど、今回ＥＣＯフェスティバルと同時開催した中で…","id":"exchange-004"},{"speaker":"武内委員","kind":"質問・要望","question":"できればもうちょっと、いろいろなところと連携して、１回にとどまらずできればいろいろなところでアピールしてもらいたいと思います。これは要望です。","respondent":"工藤環境課長","answer":"そういった新しい企画も行ってまいりますので、太陽エネルギー、太陽熱のメリット等は訴えていきたいと考えています。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"教えてもらいたいんですけれど、さっき藤原委員の質問に対する答弁でアンケートの話がありましたけれども、そのアンケートというのは、いわゆるその年にやったＥＣＯフェスティバルに対するアンケートという意味なんか尋ねました。","respondent":"工藤環境課長","answer":"アンケートに関しましては、よかったという部分ではなくて、どんなイベントを望んでいるのか、時期的にどうなのかとか、いわゆるＥＣＯフェスティバルについての感想を書いていただくような簡単な形式のものです。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、この取り組みを通じて生活スタイルを見直してもらう契機にするんだと事務事業概要の中で書かれていますけれども、そういうものを積み重ねる調査というのはないんか尋ねました。","respondent":"工藤環境課長","answer":"今から１カ月間やります、１年間実践しますということを盛り込んだような宣言文なんですけれど、そういった新しい試みもあります。そういったところから、今はそのような取り組みを始めたばかりですので、取り組みの一歩を始めたということでご了承いただきたいと考えています。","id":"exchange-007"}]},{"id":"topic-02","title":"２の放置禁止区域の拡大","agenda":"２の放置禁止区域の拡大","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"警視庁から来ていただいて１カ月ということですけれども、基本的に押さえておかないといけない点が１点あると思います。その辺は事業部長とか警視庁に戻られた前任の課長とかから、品川区の考え方について伺っていますか。","respondent":"藤木交通安全担当課長","answer":"歩行者、自転車の通行量が非常に多い地域で、私も実際に見てみましてそのように感じているところです。そこで、できる限り不要不急の自転車のご利用は自粛をしていただくという観点であると聞いております。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"ここだけは押さえていただきたいと思うのは、今日はお休みですけれども岩田事業部長がいろいろな答弁の中でお話しされています。そこをしっかりと押さえて、これからもいろいろな施策がある中の放置自転車対策をしてほしいと求めました。","respondent":"藤木交通安全担当課長","answer":"今、委員のご指摘にございましたとおり、条例等にもそのように明記されておりますので、その点を踏まえまして今後のいろいろな施策、事業に生かしていきたいと考えているところです。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"理由のところでちょっとお聞きしたいんだけれども、放置禁止区域外のところで放置自転車が発生していると考える理由と、３点目の有料駐輪場の新設・増設に伴うものというのはどういう意味合いなのか、ちょっとよくわからないので教えてもらえますか。","respondent":"藤木交通安全担当課長","answer":"２点目の有料駐輪場の新設・増設に伴うものですけれど、平成１９年ぐらいから、その直近の道路上に自転車が何台かとめられている。マナーの向上の点ですとか、放置禁止区域として指定していないから整合性がとれないということで、このたび新たに指定させていただいたところです。","id":"exchange-010"},{"speaker":"菊地委員","kind":"意見","question":"区はこれまで駐輪場を有料化して整備して、それぞれ置くところを決めて、放置自転車は実質上少なくなったと言ってきているんですよね。では、今まで言っていたのは一体何なのという感じがするんですけれども、もう少しその辺を出していただけますかとの意見を述べました。","respondent":"藤木交通安全担当課長","answer":"警察の係から、今回指定したエリアには要望が多数来てございまして、今回指定していない区域にもそういうご要望は来ているところです。実際に車の通行に支障が出るのではないかというところにつきまして指定させていただいたところです。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"そのために今回の措置をしなければならないというのもわかります。今のお話だとこれだけ拡大をして区域外にも放置自転車が生まれているわけですから、では、もう少しはっきりと出していただきたいんですよね。","respondent":"藤木交通安全担当課長","answer":"私どもの指導、そういうふうに駐輪場ではないところにとめている人も中には何人かいるというのも確かなところです。完全にクリアするのは非常に難しいところだとは思いますけれど、少しでも台数を減らそうと、今回新たに区域を設定したです。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"駐輪場が有料化されてきて、１００％になっていない駐輪場もあるというのももちろん聞いています。もしそのことで答弁があればお願いします。","respondent":"藤木交通安全担当課長","answer":"昨年１２月にも利用者の方に、あなたにとって安いか高いかとか、いろいろと調査を進めているところです。あるいはバイク枠ですとか、いろいろと問題があろうかと思いますので、それぞれの地域によってもそういう協議は今後も続けていきたいと思います。","id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"今ちょっと料金の話が出ましたが、去年ですか、時間貸しのところの料金設定を管理会社が検討しているというような答弁をいただいたことがありました。その辺のルールみたいな原則があったら説明を求めました。","respondent":"藤田水とみどりの課長、藤木交通安全担当課長","answer":"私から、１点目の店等にかかわる料金の設定の関係ですが、前交通安全担当課長からそのような答弁を差し上げているのは間違いのないところです。指定管理者がいろいろ検討する中で、区の意見の調整等も今後十分に行いながら… ２点目の原則的なルールですけれど、まず放置禁止区域内につきましては指導、警告をしまして撤去することは可能です。放置禁止区域外につきましても、７日程度たったら撤去する…","id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"そうするとやはり、おそらく札をつけていただいてある程度の期間は様子を見て、それでもという場合は撤去ということになるんでしょうか。その辺はケース・バイ・ケースということでいいんか尋ねました。","respondent":"藤木交通安全担当課長","answer":"ケース・バイ・ケースですけれども、もちろんごみのような自転車であれば即時に撤去していることもありますが、原則としてはまず警告をして、撤去するというのが現状です。","id":"exchange-015"},{"speaker":"武内委員","kind":"質問・要望","question":"要望ですけれど、あまり長引かせずに撤去することも必要なのかなという状況もありますので、それは要望でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"市川委員","kind":"質問","question":"ここが禁止エリアになりましたということは、区民の方たちにどのように周知するのか尋ねました。","respondent":"藤木交通安全担当課長","answer":"自治体によっては駅から半径２００ｍとか３００ｍとかという決まりがあるところもあるんですが、現場におきまして看板や告知板を設置いたしましたり、周知を図っていきたいと考えています。","id":"exchange-017"},{"speaker":"市川委員","kind":"質問","question":"最近国もＣＯ２削減ということで、性能がアップしている自転車とかも出て、自転車が減っていくことはこれからないだろうと思うんです。そうなったとき、違法駐輪については品川区はどういう考え方を持っているのか、質問したいと思います。","respondent":"藤田水とみどりの課長","answer":"区内の自転車利用というのは、歩いていける方については歩いていっていただくという大きな考え方の中で進めていきたいと考えております。これまでと継続する形で駐輪場の整備、それから撤去活動という３本柱を、これからも充実して進めていくべきと考えています。","id":"exchange-018"},{"speaker":"市川委員","kind":"質問・要望","question":"歩くのが原則だということよりも、自転車を使ってまちの中を移動するということに方針の転換をされたらどうかなと思います。ぜひ将来的なことを考えて、品川区でもそういう駐輪場の整備についても検討していただきたいと思うんですけれど、その辺はどんなお考えか尋ねました。","respondent":"藤田水とみどりの課長","answer":"順番待ちをしながら入れなければいけないような形で、地下の駐輪場についてはまだまだその辺の改善がなかなかできていないと考えております。指導啓発、撤去というやはり３本柱をあわせ持って進めていくことが、その３本をセットでこれからも進めていきたいと考えております。","id":"exchange-019"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"それから自転車の使い方、品川区の場合は比較的近距離で使われているというお話がありましたが、それはいつごろの調査なんでしょうか。自転車がどういった使われ方をしているのか、もう一度調べ直す必要があるのではないかと思うんですがいかがか尋ねました。","respondent":"藤田水とみどりの課長","answer":"都営地下鉄、近辺で若干土地の余裕があるところを駐輪場にできないかといった要望もＪＲにしてきておりますが、実現には至っていないです。調査する方法があるのか、調査する場面があるのか、いろいろな形の中で今後も検討していかなければいけないと考えています。","id":"exchange-020"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"要望です。これも要望です。","respondent":"齋藤道路公園課長","answer":"駐輪場を設置しなければいけないというのは本当にそのとおりでございまして、エリア拡大もする必要がない。長い、重いテーマでありますので、引き続き検討させていただきたいと思います。","id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"ですからＪＲだったり東京都だったりすると思うんです。ですから隣接区および組合関係、当然敷地の関係があるので大手企業とか中堅企業との連携、その辺についてお教えほしいと求めました。","respondent":"藤木交通安全担当課長、片田防災まちづくり事業部長","answer":"隣接区につきましては、目黒区ですとかいろいろと討議の場を設けまして、よりよい方向に進めているところです。再開発等につきましても、こちらのほうでも駐輪場の設置義務などもありますし… いずれにしても駐輪場は企業者が設置することが原則だと考えております。どういう利用があるのか、その中での対応はどのような方向が望ましいのか、それをあわせて精査していかなければいけないという考えを持っております。","id":"exchange-022"}]},{"id":"topic-03","title":"３の陶器・ガラス・金属ごみの収集回数変更に伴うモデル収集","agenda":"３の陶器・ガラス・金属ごみの収集回数変更に伴うモデル収集","exchanges":[{"speaker":"武内委員","kind":"質問","question":"平成２０年１０月に分別変更をした当初、もっとそちらを増やしてほしいというような、当初はそういう話をちらほら聞いたんですね。燃やすほうが逆に増えたということについては、あるいは収集を増やしたほうがいいのかどうかという検討はされているんか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"俗に言う廃プラスチックについては燃やすごみとさせていただいていますが、この量は大体当初の想定ぐらい、１５％程度の量の増加がございました。は、燃やすごみの収集回数をどうするかということについては、現在のところではそこまでの量にはなっていないだろうと認識していま…","id":"exchange-023"},{"speaker":"原委員","kind":"質問・要望","question":"そこで聞かせていただきたいのはまず１点、モデル地区の２カ所はなぜここに設定したかということ。始めたあとの問題ですが、その辺のことを説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"私どもは基本的に月２回の収集で十分対応ができると思ってありますが、いきなり全区展開を実施するのではなくて、７月から実施をしていきたいです。それでここの地区については７月以降もずっと、よほどの事情の変更がない限り実施していくということで考えております。","id":"exchange-024"},{"speaker":"原委員","kind":"確認","question":"確認と質問ですが、理解しました。品川区はそれこそ住商工がまざっているものですから、地域的に回収方法が難しいのもよくわかるんですね。","respondent":"太田品川区清掃事務所長","answer":"事業活動から出ている物なのか、いわゆる生活ごみなのかというところも見ながら、事業系については有料という形でお願いをしています。一律にどうこうということではなく、出ているごみの内容といいますか、それに応じて協力をお願いしています。","id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"これは最後に要望ですけれども、非常に現場が苦労されているということはしみじみ感じますので、その辺を特に加味して、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"藤原委員","kind":"確認","question":"確認ですが、４分の１程度に減ったというのは、平成２０年１０月からそれまで分別していたごみも分別しないで可燃ごみと一緒でいいですよという形にしたから、必然的にこの陶器・ガラス・金属ごみという物が４分の１になりましたよということでいいんか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"３０年と言われていたことから、旧不燃ごみで出ていたプラスチック類は燃やすごみにしましょうというところから出てあります。旧不燃ごみで出ていた物が資源あるいは燃やすごみへ当然行くわけですから、その結果として減ったです。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"ということは、先ほど武内委員からもお話が出ていましたけれど残りの４分の３は、４分の３はどこかで増えているわけですよね。この４分の３がどこに行ったのかというのを改めて教えていただけますか。","respondent":"太田品川区清掃事務所長","answer":"資源の部分でいいますと、平成２１年度でプラスチック製容器包装は約１,０７０ｔほど収集しています。燃やすごみについては、平成２０年度が約６万６,６００ｔだったのが、約７万１,７００ｔということで５，０００ｔほど増えているです。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"毎週収集していたのを月２回モデル地区でやって、月２回にするということは、やらなくなった週は何をするんですか。それとも休ませるんか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"これが週１回から月２回になりますと当然稼働状況は減りますが、通常８月ぐらいから翌年度の作業計画をつくってまいります。こういう流れになります。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"単純に考えると、全体の仕事量としてはいろいろなことを精査してバランスをとっていくということですから。回数は減るけれども、仕事量で言えば変わらないということなんですね。","respondent":"太田品川区清掃事務所長","answer":"量は減っていますから、その分車の台数は減ってくることになろうかと思います。そのことに伴って台数が減れば１台の収集エリアが当然広がるわけですから、状況は変わらなくなるということでご理解いただければと思います。","id":"exchange-030"},{"speaker":"市川委員","kind":"質問","question":"現状のことをお聞きしたいんですけれど、陶器・ガラス・金属ごみの収集を行っていて、指導に当たるような例というのはあるかどうか、お聞きいたします。","respondent":"太田品川区清掃事務所長","answer":"ただ一部実際の区分けで、陶器・ガラス・金属ごみの中でもガスコンロなど危険物は別枠で袋に入れてお出しくださいという指導をしています。量というよりは分け方の部分でお願いをしているんですが、中には一部…","id":"exchange-031"},{"speaker":"市川委員","kind":"質問","question":"そういうときは出されたごみに何か、「これは回収できません」とか何か貼っていくような対策をとっておられるんか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"排出場所がわかるところについては訪ねて、いらっしゃれば状況を説明して、分別の仕方をお話しして協力を求めます。１回ぐらいはということで持っていくケースもありますが、当然警告の注意文のシールを貼らせていただくようなことをやっております。","id":"exchange-032"},{"speaker":"市川委員","kind":"質問","question":"もう１点お聞きしたいんですけれども、この職員は訪問をして何をするのか。収集日が変わりましたというお知らせをするために訪問されるのか、この訪問の内容というか、どういうことを実際にするのか説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"先ほど申し上げましたように収集回数が変更になるということで、あるいは第１・第３月曜日になります、それ以外の週は収集することはできませんというお話をさせていただきたいと考えております。","id":"exchange-033"},{"speaker":"市川委員","kind":"質問・要望","question":"まだプラスチック製容器包装が燃やすごみに入っていたり、この機会にそういう品川区の分別収集の考え方をきちんとお知らせできればと思います。これは要望でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"阿部副委員長","kind":"質問","question":"広い家であればいいんでしょうけれど、年間で何度もあることではないので、第１・第３・第５とかにはならないものなんですか。３週間同じごみを置いておくのはちょっと勘弁してくれという気持ちもないではない、そういうご検討はされたのか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"月２回がいいのか、あるいは月１回でもどうかなという検討もありましたけれど、その分も加味して月２回がいいだろうという結論に達したところです。いろいろ検討した結果、特定の第１・第３週、第２・第４週ということで考えたところです。","id":"exchange-035"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"今はモデル実施ですからこの後もいろいろな声が出てくると思いますし、収集される側の家庭の立場から再度考えていただけるとありがたいなと思います。国道沿いとかちょっと入ったようなところで、どうも遠隔地から車で通勤されている方が、区には特にないか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"そういう部分も私どもでも当然認識はしていますけれども、モデル実施等を通してみて、そういった声も参考にしていきたいとは思っています。それから２点目の問題ですけれども、私は特にその辺のところは把握してございません。","id":"exchange-036"}]},{"id":"topic-04","title":"４の区民住宅（あき家）入居予定者登録募集","agenda":"４の区民住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"この募集のパンフレットはどのぐらい印刷するのか。区で印刷する部数、それとできたらその金額と、どのぐらい配られないで余るのか尋ねました。","respondent":"柏原住宅担当課長","answer":"細かい数字はまた後ほどご報告いたしますけれど、大体８割以上ははける状況になってあります。〔「何部ぐらい残るかと」と呼ぶ者あり〕","id":"exchange-037"},{"speaker":"武内委員","kind":"意見","question":"ちょっと関連しますが、今回２０団地で４２６戸分の募集で５００冊ということですけれど、４２６戸を募集するならもうちょっと多く印刷するのかなと思ったんですけれど、その辺はどうなのかとの意見を述べました。","respondent":"柏原住宅担当課長","answer":"募集の正式な数が今手元にないのですが、４２６戸というのは管理戸数でございまして、実際はこの戸数分ということではございません。実際はその団地ごとに応募されるんですけれども、それがどのぐらいいらっしゃるかというのを見ながら募集の冊子数を印刷するです。","id":"exchange-038"}]},{"id":"topic-05","title":"５の平成２２年度水防訓練参加組織および実施内容の報告","agenda":"５の平成２２年度水防訓練参加組織および実施内容の報告","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"２枚目の地図ですが、西大井一丁目の２ですか。どこからこの地図を持ってきて、また区のこういう資料というのはどうなっているんか尋ねました。","respondent":"佐藤防災安全担当課長","answer":"この地図については例年の資料をそのままつけさせていただいたので、今後につきましては最新の地図をつけるように注意をしてまいりたいと思います。大変申しわけありませんでした。","id":"exchange-039"},{"speaker":"藤原委員","kind":"意見","question":"部長、どう思いますか。Ｊタワーができて何年たちますかとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"所管のほうでは新しい地図がなかったところもあろうかと考えていますが、使用していきたいと思いますので、よろしくお願いしたいと思います。申しわけございませんでした。","id":"exchange-040"}]},{"id":"topic-06","title":"６の橋梁長寿命化修繕計画","agenda":"６の橋梁長寿命化修繕計画","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"今ご説明いただいた最後の部分の財源確保ですけれども、国土交通省からの財源ということで補助のお金は、今の時点で何か決まっているものがあるのか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"平成２１年度は国の補助事業がございまして、点検あるいは修繕も含めてすべての事業費の２分の１が国の補助対象になるという形になりました。社会資本整備総合交付金に変わっても、この２分の１の仕組みは変わらない予定になっておりまして…","id":"exchange-041"},{"speaker":"藤原委員","kind":"確認","question":"確認ですけれども、２分の１は国の補助でこの事業ができると考えて間違いはないということですね。","respondent":"藤橋都市整備下水道課長","answer":"私どもはそういう気持ちなんですけれども、最終的に国で認めてもらえるかどうかは国土交通省の判断になります。","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"だから、これはもらうしかないじゃないですか。課長の答弁だと気持ちをどのように伝えていくか、そこに重要性があると思うんですけれども、この辺についてはどう考えていらっしゃるのか。","respondent":"藤橋都市整備下水道課長","answer":"説明がちょっと至らないところがあったんですけれども、昨年度まで区が橋梁の点検をしたり補修をする場合は、すべて区の持ち出しでやっておりました。いずれにしても国がこういう制度をつくって、何とか東京都を通じてあらゆる機会をいただいて…","id":"exchange-043"},{"speaker":"藤原委員","kind":"質問・要望","question":"２分の１って大きいですからね。その辺をどうにか、課長がいてくださる期間に決めていっていただきたいと思うんですが、その辺についてはいかがか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"２３区の中でもこの計画は早くつくっている状況です。来年度以降この計画をつくって事業化しますよという話をしておりますので、財源確保は強力に推し進めていくということで考えてあります。","id":"exchange-044"},{"speaker":"武内委員","kind":"質問","question":"それと国や都では今回品川区が考えているような対処療法型でない予防保全型のほうに、考え方として同じような方向で計画を立てられているのかどうか。それを説明を求めました。","respondent":"藤橋都市整備下水道課長","answer":"国道につきましては長寿命化修繕計画についてはまだ作成していないものの、定期的に点検を実施して修繕等をしていくとの回答をいただいております。都道につきましては既に東京都が修繕計画を策定済みですので、この計画に基づいて個別に対応していくというふうに聞いております。","id":"exchange-045"},{"speaker":"武内委員","kind":"質問","question":"長期的に見ればコストもかからないということであれば、ぜひ国に対しても、そういうお話をしていく場があればしていってもらいたいと思います。それと、区の７０橋梁については定期点検はこれからやるということなんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"点検につきましては平成２０年度に一度全部の橋梁を点検しています。今後は５年ごとに、平成２５年を目途にもう１回、７０橋梁すべてを点検をしていく、それを５年ごとに同じことを繰り返すというスタンスです。","id":"exchange-046"},{"speaker":"武内委員","kind":"質問","question":"そうすると、橋梁の場合は専門的な角度で点検をしなければいけないのかなと思うんですけれど、区のスタッフだけで対応するのか、どこかに委託してやっているということなんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"１１ページの上に損傷程度の評価ということで、品川区では国土技術政策総合研究所が策定した要領に基づいた点検を行っています。橋梁点検の専門的なノウハウを持っている民間のコンサルタント業者に委託して実施いたしまして、今後についても専門業者に委託して実施するものです。","id":"exchange-047"},{"speaker":"菊地委員","kind":"質問","question":"最終的にどうかは別として、途中でコストをかけましょうと。そうすると、それによって平均５０年、６０年と言われる寿命を実際にどこまで延ばそうという話なんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"東京都が今やっているやり方ですと、既に何十年もたった橋梁があるんですけれど、今からさらに１００年もたせましょうという考え方です。当面、５０年以上たっている橋梁もあるんですけれども、そういう考え方で実施してまいります。","id":"exchange-048"},{"speaker":"菊地委員","kind":"意見","question":"そこまで出るのかどうかよくわかりませんけれども、何かそういうものがないと、本当に安く上がるのかというのがよく見えてこないんですよね。そこがちょっとよくわからないとの意見を述べました。","respondent":"藤橋都市整備下水道課長","answer":"１７ページの先ほどご説明しました図－９です。これは平成２０年度の点検結果に基づいて、今日、このように修繕計画をお示ししたものです。","id":"exchange-049"},{"speaker":"菊地委員","kind":"意見","question":"そうすると、この橋梁はＣからＥ１、Ｅ２に行くまでにこれだけ延びますよというのは当然あるんだと思うんですね。そこがちょっと、ここまでの経過は持ち合わせていませんと言われても、それじゃあコストはどうなるのという話が出てくると思うんですがとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"それをやったからあと何年延びるんだということは、ここで説明できるようなものではありません。その状況、状況を踏まえながら適切な処置を施し、対応していくということでご理解いただければと思います。","id":"exchange-050"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、藤原委員からもあったようにしっかり２分の１は確保しろと、私もそう思います。その辺をお伺いいたします。","respondent":"藤橋都市整備下水道課長","answer":"一番規模が大きいのは勝島橋です。ＪＲの西大井駅の南側にある原跨線橋ですとか、いわゆる健全度からしても重要性からしても早く修繕したほうがいいかなというのがあります。","id":"exchange-051"},{"speaker":"原委員","kind":"質問","question":"そうすると、先ほどの１１ページですけれども、このデータをとるのは民間の専門のところというお話ですけれども、それを今度はデータとして実際につくっていく、入れ込んでいく、この作業もやはり民間なんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"この点検結果を１回業者に入れていただいて、あるいは（２）補修工法・費用の算定ということで、費用が何パターンか出てくるような形になります。それをもとに今度は区の職員がそれを見て、あるいはいつ補修したほうがいいかという総合的な判断をするのは…","id":"exchange-052"},{"speaker":"原委員","kind":"質問・要望","question":"ですから今のご答弁にあったように民間の専門家に、１行間違えて全部ずれてしまったら、総合的な判断でしょうから大変なことになってしまう。特に特殊ですから民間企業を使うのは結構ですが、そういう意味での注意点等ありましたらお伺いしたいと思います。","respondent":"藤橋都市整備下水道課長","answer":"いわゆる職員の技術力をきちんと確保して、それを次の世代に継承していくことがすごく大事だと考えております。向上に向けて、それによる人材育成の取り組みを実施しておりますけれども、区の職員の技術力向上と育成を行ってまいりたいと考えております。","id":"exchange-053"},{"speaker":"阿部副委員長","kind":"質問","question":"橋梁担当の職員の方がいらっしゃると思うんですが、その方は、業者の方が現場で点検されるのにある程度立ち会ったりということもあるんでしょうか。それとも出てきた数字や書面だけで総合的判断ということになるんか尋ねました。","respondent":"藤橋都市整備下水道課長","answer":"すべての橋梁の点検に立ち会うことは平成２０年度の点検のときもしておりませんでしたが、代表的な橋につきましては立ち会うことをいたしました。特徴的な損傷があったりする場合ももちろん立ち会って、実際に見ることはしています。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483234?Template=document&Id=3974#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":37462,"voices":142}},{"id":"h22-20100510-9","meetingId":"h22-cm05","date":"2010年5月10日","dateIso":"2010-05-10","committee":"文教委員会","time":"午後１時０２分～午後４時４９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"順番も含めて、現場の学校の先生が直接手にするものですから、その先生たちが使いやすいものがいいのかなというふうには思うんですけれども。伺いたいのは、この仕組み上からのこともあるでしょうけれども、そこをご説明いただけますか。","respondent":"冠木指導課長","answer":"教科書の採択につきましては、教育委員会で採択をしていただく。その基準については、採択の基準等の要綱を定めまして、その要綱に基づいて決定をしていただくという流れになってあります。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう中身なのか教えていただきたいのと、検討委員会や研究会を開催するわけですけれども、これを立ち上げる目的は何なのか教えていただきたい。そういう広い参加を保証していく、そういう仕組みが必要だと思うんですけれども、いかがか尋ねました。","respondent":"冠木指導課長","answer":"先ほど説明をしました教科書展示会のほうに足を運んでいただいて、教科書の内容について見ていただければありがたいなと思ってあります。考え方としては、内容…","id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"教えていただきたいのですが、それはどういう形で決められていくのかという、そういう組織みたいなものがあるのかどうか。このアンケートの利用方法というんですか、意見をいただいて、今後どういうふうに利用しようとされているのかを説明を求めました。","respondent":"冠木指導課長","answer":"特別支援学級に通うお子さんの教科用図書ですけれども、先ほどもちょっと説明させていただきましたが、まず第一には。それが品川区の特別支援学級で使えるかどうかというような検討もしていくというような流れで特別支援学級の教科書については決めていくという形にな…","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"アンケートを先ほど教育委員会に報告すると言いましたが、それは次の採択のときの参考という形にするということですか。どういう形で、せっかくご意見をいただくものですから、それをある程度有効的に活用していただくことが必要かと思うんですが、いかがか尋ねました。","respondent":"冠木指導課長","answer":"それから設置学級の担任の先生からなる委員会で検討いたしまして、決定をして、そこで最終的に決定するという流れになってあります。今回については６月に展示会がありますので、８月までに決定のための教育委員会が開かれますので…","id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"親御さんが教科書をすべて自分で点字に直してというお子さんもいたというお話を伺っているんですけれども、そういうような区の教育委員会としてそういう対応についていろいろその子に合ったふうなことを広げていってほしいと思うんですけれども、その辺を説明を求めました。","respondent":"冠木指導課長","answer":"都立の特別支援学校の視覚障害の部分と、弱視の特別支援学級のある区がありますので、そういうところの情報をいただきながら対応していくことになろうというふうに思います。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"今の対応というのは、前向きに品川区として対応してくださるというふうに伺ってよろしいのか尋ねました。","respondent":"冠木指導課長","answer":"特別支援学級にお通いになるのか、それとも特別支援学校が適切なのかというようなところの就学相談というようなところにまずは私どもの相談の機会がありますので、ふさわしい教材についてもそこで検討していくことになるのかなというふうに思ってあります。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"今回は中学校はそのまま平成２２年度、平成２３年度まで同じ教科書を使うということで、中学校が入っていないと思うんですね。この原則４年というのが崩れる場合、そういうようなことは発生するものなのかどうかというところを教えてほしいと求めました。","respondent":"冠木指導課長","answer":"教科書採択については、今、委員のお話の４年というのは、これは法の定めでございまして、原則は４年ごとにということになってまいります。今のところ、それ以外のケースというのは、私どものほうで把握してございません。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"今回の場合ですと、中学校はそのままということで、今回、記載はないということで、そういう理解でよろしいんですか。そのときはやはり来年度使う教科書をどうするかということについての報告はされる、ちょっとそこの流れをもう一度教えてほしいと求めました。","respondent":"冠木指導課長","answer":"原則で行けば４年間その教科書を毎年採択するということになるんですが、中学校の教科書については、来年採択になります。その次の年から新しい教科書になるという流れになってあります。","id":"exchange-008"},{"speaker":"林副委員長","kind":"確認","question":"確認をしたいんだけれども、２番の表の中の４月２７日、よその自治体の教育委員会が採択していくのと違う点があったら説明を求めました。","respondent":"冠木指導課長","answer":"今回、他の自治体とは違って、小中一貫教育を推進していくにふさわしい教科書というようなところでの採択になってまいります。その点がほかの区と一番違うところかというふうに思ってあります。","id":"exchange-009"},{"speaker":"林副委員長","kind":"質問","question":"そうすると、日本の文部科学省というところが品川区のそういう他の自治体と違うんだということを、いわゆるこれは法定で決められているものなので、そうすると、品川の小中一貫教育というのをはっきりともう文部科学省でも認めているというふうにとっていいんか尋ねました。","respondent":"冠木指導課長","answer":"この制度につきましては、ここ３年間と思ってあります。文部科学省の教育課程特例校ということで私ども申請いたしまして、それを認めていただいているです。","id":"exchange-010"},{"speaker":"林副委員長","kind":"質問","question":"そうすると、ちょっとへそが曲がっているもので聞き方がいけなかったら注意をしてください。１番の（１）の教科書の区別というか、それからもう１つは英語、それが入っていないというのは何か意味があるんか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"さらに、英語科についてはそのまま使う、算数についてもそのまま使うということで、継続して使うということで検討しています。小中一貫教育を推進するのに一番都合のいいものをぜひ選択していただきたいとは考えてありますが、区独自でそういう教科書を用意しているです。","id":"exchange-011"},{"speaker":"林副委員長","kind":"質問","question":"ちょっと回転が鈍くなっているのであれなんだけれども、そうすると、ここに書いてあるのは品川区用の、区用のと言ったらちょっと語弊があるのかな、品川区としての教科書を選定していくのに、今言われたように、市民科とか英語とかということについて、なぜ載せないんか尋ねました。","respondent":"若月教育長","answer":"したがって、品川区は英語の副教材という言い方で呼んでいる、こういう違いがあるわけです。しかし、この教科書採択の俎上には乗ってこない、こういうことです。","id":"exchange-012"},{"speaker":"林副委員長","kind":"確認","question":"最後に確認します。先ほどの前半で確認をすると、特例としますよということを、我々はそういう形で認識をしておくということか尋ねました。","respondent":"若月教育長","answer":"だから、一貫教育をうちはやりますから、場合によっては中学校の勉強の内容を小学校６年生に持ってきているものもあるんです。これについての特例ということで、品川区はそれに基づいた教材は独自で用意している、こういうことになります。","id":"exchange-013"},{"speaker":"中塚委員","kind":"確認","question":"２、３だったり、そういう形になるのか確認をしたい。いや、そこはだめだという縛りなのか、そこもあわせてお伺いします。","respondent":"若月教育長","answer":"これは教科にはできません。学校教育法施行規則そのものを今度は変えていかなければならないということで、その権限はうちにはない、こういうことです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"在園率とおっしゃったんですか、そこを教えていただきたいのと、そこの中身を教えていただきたい。","respondent":"吉岡保育課長、伊崎待機児童対策担当課長","answer":"在園率ですけれども、在籍児童数を定員で除したものです。 転園希望者につきましては６６名、認証保育所在籍者につきましては１１２名となっております。例えば１園だけしか希望していらっしゃらない方とか…","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"昨年が１２３人だったのが６６人だったというお話がありましたけれども、要するに、それをどう評価しているのかというところを伺いたいと思います。そしてこの４月の結果を受けてどう評価していらっしゃるのか、今後の課題を何か考えていればそれは何なのか、評価を教えていただけますか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"６６名となった評価ということですけれども、先ほど保育課長からも説明がございましたように、かなりの受け入れ枠の拡大を図ったところです。２園の認証保育所の誘致は確定をしておりまして、今、検討しています。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"それがこの４月を受けてどうだったのかという、そこの評価を伺いたいと思います。それと、とりわけ五反田や大崎の地域が保育園の入園が厳しいというお話を伺いますけれども、その地域にはどんな特徴があるのか教えていただけますか。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"あらゆるできるだけの手段を使って対応を図るということで今回やってまいりましたところで、５７名の減という効果が出たということで考えております。ただし… 大崎、やはり他に比べましてもご希望の数が多くて、なかなかご希望どおりに入園がかなわなかった部分があるかなと思ってあります。若干の、できるだけあきの状況につきましても今後もご案内をしながら…","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと何が言いたかったのかよくわからなかったのでもう１回伺いたいんですけれども、まあまあ、よく意味がわからなかったので教えてください。全部の保育園を伺うわけにもいかないので１つだけ伺いたいんですけれども、西五反田保育園についてです。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"品川区の考え方といたしましては、保育に欠けるお子さんすべてを保育園で受け入れるという方針ではございません。保育園はもちろんのことですが、認証保育所やほかの施策を使いまして… それから、内定を出しましたのは、０歳児が８名、１歳児が３名、２歳児が２名、合計１３名です。在園児も同じです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"あなたはどうなんですかと、そこはちょっと違うんじゃないかなと思うんですけれども、そこはどう考えているのか伺いたいと思います。この状況をどう考えているんだということなんですけれども、ご説明ほしいと求めました。","respondent":"吉岡保育課長","answer":"ただいま保育を求めていらっしゃる方に対する区の考え方ということで、待機児童対策担当課長のほうからるるご説明いたしたところですけれども。１つには、または幼稚園でも実施しておりますけれども、そのような保育園と同等の扱いをする。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"いや、その人は認証に入っているからいいんだと、どう考えているのか伺いたいと思います。認可保育園の増設を柱に据えるべきだと思うんですけれども、いかがか尋ねました。","respondent":"古川子ども未来事業部長、吉岡保育課長","answer":"保育の実施基準は区市町村が持ってありますし、一義的には保育園を重視すべきであろうという考え方は当然持ってあります。あるいは認証保育所の動向等を見ながら、来年度に向けての体制はこれから検討していきたい… 各園の詳細な入園の申込状況については、今、資料を持っておりません。お許しいただきたいと思います。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"今年についてはこれからというお話が最後にありましたけれども、一体じゃあ何が必要なのか、そこをもう１つ伺いたいと思います。認可保育園の増設で、認可保育園の増設でなければ対応ができないということはいよいよ明らかだと思うんですけれども、そこはいかがか尋ねました。","respondent":"古川子ども未来事業部長","answer":"そういう方々には、少なくとも何らかの形で対応策をとっていきたい、こういうことです。個別の問題をここで１つ１つご審議いただくわけにはいかない、このように考えております。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"それから２つ目は、要は、どのクラスがどういう形で増員をすることができたんですかということの割り振りを知りたいです。６６名の待機児がいますけれども、それとも５歳児だけではなくて、４歳児というところも含めて拡大をしていく考えはあるのかどうかお聞きします。","respondent":"吉岡保育課長、伊崎待機児童対策担当課長","answer":"それぞれ５歳児を小学校の施設を利用して分園を設置したことによりまして、２歳が５名、合わせて１２名の在籍の増が昨年度に比べて実現しています。１歳が７名、２歳が５名ということで… 学校を利用しての分園設置の話ですが、今、２園２校で実施しています。実施するに当たりまして、さまざまな事情がありますので、そういったところも含めて、今後また検討をしていくということは考えております。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう意味では、どういう保育の方法をされているんですかと。その人数を増やしていけたというのは、どういうところで増やすことかできたのかというところを教えていただきたい。","respondent":"古川子ども未来事業部長","answer":"あるいは正規職員ではなくても、非常勤あるいは有資格の者で対応すること、さらには一部派遣職員の活用もあるかもしれません。６月を最初から想定できませんので、さまざまな手段によって１年間の保育環境を整えていく、こう考えています。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"済みません、先ほどの質問の最後、中延保育園と西品川保育園の増やせた理由、保育の内容から考えたときに、どういう工夫をすることでこういう増員ができたのでしょうかということ、それは保育園によって違うとは思うんですけれども、考え方を説明を求めました。","respondent":"吉岡保育課長","answer":"それからもう１つは、その中で一定余裕のある面積について活用する中で、新たな定員の増をまかなえるだけのスペースをつくり出しているです。その中でそれぞれ例えば９人のクラスが１２人になれば、あるいは活動場所の選択も含めまして…","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"先ほどの弾力化の件についてなんですが、この弾力化した４月１日の在籍、これがマキシマムと考えていいんですか。再度いろいろなことを考えた中で増えていくということもあり得るのか、そこの将来性の検討度合いも含めて、どういう感じなんか尋ねました。","respondent":"古川子ども未来事業部長","answer":"年度途中におきましても一定の対応を迫られていくわけですから、年度途中においても、この部分についてはもう少し広げていく必要があるかと思います。しかしながら、全体のキャパシティの問題もありますから、制限なくというわけにはいかない、このように考えております。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど待機児の中で、その中で認証で１１２名の方が認証のほうに入っていらっしゃるということで、この年齢別の構成を伺いたいということ。どういう内訳になったのか、この中でどのぐらいの方が６６人の待機児の中に入ってしまっているのか、このところの数を説明を求めました。","respondent":"吉岡保育課長、伊崎待機児童対策担当課長","answer":"有効数として審査をした方が１,７７１名、それに対しまして入園した方が１,２８４名ということで、入園承諾がされなかった方が４８７名です。 認証保育所の１１２人の内訳ですが、０歳が３０人、１歳が５１人、２歳が２８人となっております。認証保育所につきましては… 西五反田保育園の入園に至らなかった方がどういうふうになったかということについては、今現在、把握してございません。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"もう１つ、そういう方がそこに入れているのかどうなのか、この施策についての評価はどうなんか尋ねました。","respondent":"吉岡保育課長、伊崎待機児童対策担当課長","answer":"短時間就労の対応の保育室につきましては、どうしても就労時間が短い方については、やはりなかなか入園は難しいという状況が一方です。区としては、今申し上げたようなことがこの短時間保育を施策として実施しているゆえんですので… 通常、８時間の保育時間では送り迎えが間に合わないということがありますので、パートの方や自営業の方が申し込めるような仕組みをつくっております。お申し込みいただいた方の中から特に家庭における収入ということを…","id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"どういうふうな規制をかけながら考え方をきちっと押さえる中で進めていこうとするのか、どういうふうに考えて進められるのか、考え方を説明を求めました。","respondent":"吉岡保育課長","answer":"先ほど部長のほうからお答えをしたとおりですけれども、基本的には定員として決定した場合につきましては、正規の職員を配置して保育をしています。大前提になりますのが保育所の設置基準がございまして…","id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"この先どういうふうな見通しを持っていらっしゃるのか、そこのところは、これでもう様子を見ていくんですよということで考えてよろしいのか尋ねました。","respondent":"吉岡保育課長","answer":"既存の保育園全部がめいっぱいまで定員の拡大が可能なところまで１００％やっているかということで言えば、それはそこまではやっておりません。今現在、１００％、もうこれ以上１人たりとも定員の拡大は無理だということではないというふうに考えてあります。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問","question":"保護者の方に伺うと、１カ月たって、何か課題であると考えていることはありますか尋ねました。","respondent":"吉岡保育課長","answer":"今のところでは私どもはそのようなことを情報としては把握してございません。今後につきましても、事故のないように、一層注意を払ってやってまいる所存です。","id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"どこのだれがどうだという、区はどういうふうにそこのところを感じているのか、そこの辺のお話をお願いします。","respondent":"吉岡保育課長","answer":"先ほど視察したときに園長が申し上げましたように、十分なスペースがあればそういう面が緩和されるということは確かにあろうかと思います。そのようなことは十分に踏まえながら、これからも指導し、保育園運営をしてまいりたいというふうに考えているところです。","id":"exchange-031"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"確認","question":"確認だけさせてください。認証保育所、これはＢ型ですか、Ａ型ですかということが１点。","respondent":"吉岡保育課長","answer":"両方どちらもあり得るかなというふうに考えてありますけれども、まだ開設までに２年間ありますので、しばらく検討したいと考えています。これはちょっと区民施設になりまして私どもの所管ではございませんのでよろしくお願いいたします。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"それともう１つ、ちょっと今日は地図を持ってきていないのでわからないんですけれども、再開発ビルのところですか。武蔵小山も小学館もそうなのかどうなのかよくわからなかったので、入るビルが何なのか教えていただきたい。","respondent":"吉岡保育課長","answer":"１歳児が１１名、２歳児が６名、３歳児が３名の合計３０名という現在の予定です。それから、武蔵小山の小学館アカデミー武蔵小山保育園のほうは、武蔵小山創業支援施設の２階と３階に入ります。","id":"exchange-033"},{"speaker":"中塚委員","kind":"提案","question":"区として何か提案といいますか、要望といいますか、その中身は何なのか教えてください。もちろん準備段階ですからどこにどうという話までは行かないですけれども、どういう今後の動きがあるのかないのか、状況だけ教えていただけますかとの意見を述べました。","respondent":"吉岡保育課長","answer":"それぞれ実施をする場所がございまして、運営者、事業者のほうの事情も配慮しつつお話をさせていただいているです。既に何件かお問い合わせをいただいているところがありますけれども、今現在、この委員会の場で詳細に報告をするまでには至っていないです。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"その中で区が規模が大きいものを要望したのかどうかちょっと、区としてはどういうものを要望したのか、そのスタンスを伺いたいと思うんです。税金が補助金として入っているものですから、区が何を要望したのか、そこを再度ご説明いただけますか。","respondent":"吉岡保育課長","answer":"当然、施設ができる場合につきましては、いろいろな人口圏のあり方があろうかと思います。その中でこの東五反田の件につきましては、認証保育所ということでお願いしたところです。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局はお願いする姿勢すらないのかなと思うんですけれども、それでは区民要望の高い認可保育園の年齢、ここはカバーできないわけですよね。このことを柱にしない限り、保育園不足は解消しないと重ねて言いたいと思います。","respondent":"吉岡保育課長","answer":"ちょっと説明が漏れました。面積的に認可保育園を設置するには、１８０m2前後の面積ということで聞いてありますので、妥当な選択であろうかなというふうに考えております。","id":"exchange-036"},{"speaker":"林副委員長","kind":"質問・要望","question":"本来、この次世代育成をこれから品川区はどういうふうに進めたいと思っている意気込みがあるのかを聞かせていただきたいのと、概要のところで。教育委員会というのはどういうふうにこれとかかわっていくのか、せめて最後に次世代育成という文教委員会らしい話を少し説明をしていただけますか。","respondent":"小林青少年育成課長","answer":"特に２つ目の柱の子育て環境の主力は、むしろ教育委員会が担ってきてくれているという形で、この計画全体をつくってまいりました。今後も庁内の検討機関には、ひいては実施計画のローリング等にも新しい施策として反映していくような連携をとってまいりたいと思いますので。","id":"exchange-037"},{"speaker":"林副委員長","kind":"質問","question":"後期の次世代育成が始まるわけですから、文教委員会に報告をし、あるいは意見を聞いていくということも忘れずにお願いしておきます。よろしくどうぞお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/746735?Template=document&Id=4698#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":36318,"voices":103}},{"id":"h22-20100510-5","meetingId":"h22-cm05","date":"2010年5月10日","dateIso":"2010-05-10","committee":"総務委員会","time":"午後１時０２分～午後１時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"１の地上デジタル放送への切り替えの周知","agenda":"１の地上デジタル放送への切り替えの周知","exchanges":[{"speaker":"土井委員","kind":"質問","question":"ケーブルテレビがこれだけ普及している、そういう状況で品川区は金も出しているんですよというのと無関係にお話をされる可能性があるようにも思うんだけど、我々の施策的にはいかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"説明会に至る前にはデジサポの担当の方と何回か打ち合わせをやります。現に昨年行いました個別の説明会等では、前年度防災センターにおきまして、この考え方は平成２２年度も続けていきたいと考えています。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"特に受信障害のエリアに対する周知ですか、一番重要なのが、現在受信障害になっているところへの周知ということだと思います。国の方が本来やるべきことなんですけれども、もし何かあれば教えていただければ。","respondent":"久保田行財政改革担当課長","answer":"それぞれ原因者である方と、私どもとしましては、広報に特集を載せて「こういう助成がある」ということを広く全般的に周知していく。そういった方を対象とした説明会を開催していきたいと考えておりまして、広く周知を図る中で重点的に進めていきたいなと考えているところです。","id":"exchange-002"},{"speaker":"山元委員","kind":"質問","question":"例えば、「今何某集会所で説明をやっています」という案内の車を出していただくというか、そのようなことはしていただけますでしょうか。いかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"今の予定では、車で回るというところまでは予定してございませんで、そういった中で広く周知を図っていきたいなと思っているところです。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"そういう分析等はされているんでしょうか。どこら辺の認知度が弱いとか、どういう部分を強化する必要があるかとか、そういう分析はされているんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"そういう世帯の方につきましてはアンテナ等の設置工事は必要ないということでございまして、対応しているテレビをご購入いただければ。何とおりかの視聴方法がありますけれども、そういったところも含めて周知を図っていきたいなと考えています。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"こういう切り替えというのは行政の都合でやるわけですから、取り残されることがあってはいけないと思うわけです。私は国だけではなくて、地方自治体もあわせて対応しなきゃいけないんじゃないかと思うんですけど、そこら辺は何か考え方はあるんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"私ども、先ほど冒頭にご説明させていただきましたように、基本的には個人の責任で対応していただきたいと考えているところであります。平成２３年７月に向けて引き続き継続していきたいと考えているところです。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問・要望","question":"くどいようですけれども、「言ってたつもり」という対応にならないようにしていただきたい。行政を挙げて取り組んでいってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"役割が大きく転換するわけですから、町会の方は地元にどういう方が住まわれているかそれぞれわかるし、きちっと個別にそういう方たちを救済する。実際、平成２３年ということですから、そういう弱者に対して個別にやっていくということは全く考えられていないんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"確かにこういった切り替えに対しての対応がなかなか難しいのかなという問題意識は持ってありますので、個別の説明会をやりますということで。そういう認識というものはそこで認知度がかなり高まるのかなと考えていますけれども…","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"何しろ、本当に日々使っているものですから、最後は区の方に対応を求められちゃうと思うんですね。現実論、介護支援を受けている動けないような方に対しては、行けなければ全く受けられないという状況と今の段階では見なきゃいけないんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"こちらの助成につきましては、郵送等でも申請の受付ができると伺っておりますので、出向かなくてもそういった申請等は可能であると聞いております。そういった申請書をそろえて、ご自分なり、どなたかに手伝っていただいて郵送でやればそういったことは可能になると考えておりま…","id":"exchange-008"}]},{"id":"topic-02","title":"２の平成２２年度区政モニターの委嘱","agenda":"２の平成２２年度区政モニターの委嘱","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"それはかなりの区民がそのアンケートに答えるわけですから、そういう手法というのも別途にあるんですか。実際、その方がより多くの人の意見を集約できるような気がするんですが、ちょっとずれていますが説明を求めました。","respondent":"中川原広報広聴課長","answer":"これはあくまで区政モニターに限ったことでして、講演会とか講座とかをやりますと、必ず参加者アンケートというのを所管の方でとりまして、それを参考にさせていただきまして事業運営をやっているところです。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"モニターは人数的に定員５０名ということなんですが、実際モニターとしての適正な数ですか、これはどういうものを基準にして決めたんですか。予算の問題なんか尋ねました。","respondent":"中川原広報広聴課長","answer":"これはなぜいいかと言いますと、区の説明だけですと、区民同士が違う考えを持っているんだということがなかなかわからないんですね。タウンミーティングとか説明会とかいろいろなものがありますので、区政全般にわたって理解を深めていただく一つの手法ということでご理解くださ…","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"質問ではないんですが、グループワークとしてとらえているのかもしれませんが、趣旨はわかりました。これから改善等いろいろしていくと思いますが、よりよい区政モニターの意見を集約できるように工夫してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]},{"id":"topic-03","title":"３の平成２２年７月１１日執行想定参議院議員選挙執行要領","agenda":"３の平成２２年７月１１日執行想定参議院議員選挙執行要領","exchanges":[{"speaker":"土井委員","kind":"質問","question":"選挙執行そのものですからそういうことなんでしょうけれども、一般的には投票してくださいという宣伝、ＰＲ等の車を出したり、いろいろやりますよね。そういうものに対しては、これはそのものじゃないからここにはないんでしょうけれども、当然またお考えを出していただけるんか尋ねました。","respondent":"早津選挙管理委員会事務局長","answer":"総務委員会に何をするというようなことまでは報告していなかったのが今までということで、この選挙執行要領の報告をもって、選挙計画についての説明とさせていただいているところです。","id":"exchange-012"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"若林副委員長","kind":"質問","question":"質問もしっかりと、ある意味では力をあわせて、区政の発展に、個人的にはまた取り組みたいと思いますので、まずは１年間大変ありがとうございました。各委員の皆さん、お疲れ様でございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212618?Template=document&Id=1852#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":16965,"voices":39}},{"id":"h22-20100511-14","meetingId":"h22-cm05","date":"2010年5月11日","dateIso":"2010-05-11","committee":"行財政改革特別委員会","time":"午後１時０３分～午後２時４９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"１の区施設の活用に関することとしまして、区施設中長期改修計画","agenda":"１の区施設の活用に関することとしまして、区施設中長期改修計画","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"対象建物の考え方についてお伺いしたいんですが、１ページのところで、そこら辺を改めてご説明していただきたいなと思います。正確じゃなくなっちゃうところもあるんじゃないかなと思うので、そこの、どういうことなのかというのをもう一度詳しくお伺いしたいなと思います。","respondent":"日下部企画部長","answer":"いろいろそういう意味では多角的な検討をしっかりやって、それで整備を進めていくということが必要だろう。施設によっても大分違いますし、一概には比較できるものではありませんので、これはあくまでもそういう形で算出をしております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"といいますのは、そこら辺に関してもう一度これを除外してしまっているということについてのお考えを説明してほしいと求めました。この観点からの検討というのはどれだけされるのかなというのはちょっと疑問に思わざるを得ない点があったもので、そこら辺はどうなんか尋ねました。","respondent":"日下部企画部長","answer":"どういう形で修繕なり改修を進めていくのかと、それはまた別の角度から、それとこれはまたちょっと別次元の話ではないかというふうに思っています。基本的に段差解消も含めて、この間取り組みを進めてきておりますし、その辺の基本的な考え方は変わってございません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"個々の施設で、ぜひここに書いているような観点で一層の推進を図るというところをこれからもぜひ貫いていってほしいなと。最後まで執念を持ってこの観点を貫ける方策はないのかというところでぜひこれからも努力していただきたいなというふうに私は要望したいと思います。","respondent":"日下部企画部長","answer":"これは私どもある意味で指導する立場からもこの辺はしっかりと今後とも対応していきたいというふうに考えておりますし。そういう説明はしたくないんですが、１４ページのほうにもそのリストの中にも入っておりますし、このように考えております。","id":"exchange-003"},{"speaker":"阿部委員","kind":"質問・要望","question":"２点ほど教えていただきたいんですが、考えてみれば当たり前かもしれませんけれども、画期的なことであろうと考えております。ソフトというか、用途の面での中長期的な配置の考え方というのもあるかと思うので、その辺についてはどうお考えか尋ねました。","respondent":"日下部企画部長","answer":"これをやることによって、先ほどご説明させていただきましたようなコストの縮減効果を何とか図っていきたい、それが１点です。ソフト面、いろんな変化への対応ということでいくと、表裏一体のものとして私どもは考えているというものです。","id":"exchange-004"},{"speaker":"阿部委員","kind":"質問・要望","question":"もうどこでもやっていることなら私がよく知らないということだと思うんですが、発信していけるものなら発信していただきたいなと思います。そのときそのときに、じゃあこれは何をしましょうかというような議論になっていくのか、お考えを説明を求めました。","respondent":"日下部企画部長","answer":"それからそれに基づいて実施計画も導入してきましたけれども、しっかりと計画として体系化を図ったというのが１点目です。これは実施計画なり、予算の計上の中で具体的な実現を図る、そういう手順になろうかというふうに思います。","id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"全体を見据えた中で、改修のとき、あるいは建て替えのときにそれに対応したことを事前にできるんじゃないかと思うんですね。なかなか難しいとは思いますけれども、そういう発想で進められていく方向であるのかということを説明を求めました。","respondent":"日下部企画部長","answer":"１０年先のいろんな状況変化にも対応できるように、１０年先をやっぱりしっかり見据えたような、このように考えております。","id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"今の質問は１ページ目の計画の性格というところでうたってあることが、「施設運営上の理由等により、それでいいのかどうか。今質問があったように、ソフトの面については、どの辺ぐらいまで考え方がまとまっているんですかね。","respondent":"日下部企画部長","answer":"ソフトとの対応ですけれども、あり方の検討ということで、ソフトの連携をどうやって図っていくかということで検討を進めていきたい。まだこれから少し具体的な計画の骨格とか、これはまたさらに先へ進んだ段階で適宜議会のほうにもご報告をさせていただきたいというふうに思いま…","id":"exchange-007"},{"speaker":"川西委員","kind":"質問","question":"一つ伺っておきたいんですが、そういうことなので、あそこが開設されるまでは荏原保育園は手がつけられないだろうという判断もあります。例えばここに所管課が書いてありますが、こういう部署で具体的に決められるのかどうか、そこだけ聞いておきたいと思います。","respondent":"日下部企画部長","answer":"当然所管を抜きにはできませんが、先々を見据えてどういうふうに各施設の機能を生かしていくのかという形で一つの軸をつくるわけですね。やはり実施計画、これはお金の問題もしっかりちゃんと見据えなければいけませんから実施計画…","id":"exchange-008"}]},{"id":"topic-02","title":"２の跡地活用に関すること","agenda":"２の跡地活用に関すること","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"校舎の全部を使うわけではなく、体育館などは開放する方向なんだろうと思うんですけれども、その他にも幾つかスペースは２年間ほどあると思います。地域の状況等もかんがみながら、できるだけ柔軟に活用できるような方向で考えていただければと思うんですが、いかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"基本的に平成２３年の５月から地域センターとして活用するということを予定しておりまして、一貫校開校後も含めまして。集会所を設けますので、基本的に各教室のほうの貸し出しを行っていくという考え方は今のところ、施設の管理上も含めまして考えていないです。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"２点目が、これはどうするのか、どうなるのかというのが知りたいのでお伺いします。改めて平成２２年度のいつぐらいから、どういう形で検討するのか、今の区の考え方をお伺いします。","respondent":"久保田行財政改革担当課長","answer":"第一日野小学校のほうの関係ですけども、ＴＯＣの貸し付けにつきましては、平成２２年の９月からというふうな予定で考えております。まずは区としまして、そうした活用のことについて、全庁的に検討を進めていきたいなというふうに考えております。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/438675?Template=document&Id=5882#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":20948,"voices":38}},{"id":"h22-20100513-15","meetingId":"h22-cm05","date":"2010年5月13日","dateIso":"2010-05-13","committee":"環境対策特別委員会","time":"午後１時０３分～午後２時３８分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"水辺とみどりの整備に関することとして、「緑確保の総合的な方針（案）」に対するパブリックコメントの結果","agenda":"水辺とみどりの整備に関することとして、「緑確保の総合的な方針（案）」に対するパブリックコメントの結果","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"民地の緑が抱える課題というのは具体的にどういうものなのかを改めて教えていただきたいのと、どういうことなのかなというのを教えていただきたい。この２つです。","respondent":"藤田水とみどりの課長","answer":"後段の部分のほうを先に説明しますが、東京都と５３市区町村で取りまとめたという意味でございまして、その中に島は入っていないという意味です。この間、品川区というよりか東京都全体で考えますと…","id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"そういうことなのかどうか確認したくて質問したんですけれども、改めて伺いたいなと思ったんですけれども、公共じゃなくてね。今、改めて緑の保全とか、そういうところの共通認識というのがどこまで醸成されているのかなというのもあわせて伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"まちづくりの中での共通認識等の関係ですが、緑確保の総合的な方針のほうの大前提は、生活をこれまで同様に継続することを前提にしつつも。手をたずさえながら進めていく緑の施策だと考えています。","id":"exchange-002"},{"speaker":"南委員","kind":"確認","question":"共通認識をしっかりお互いに確認しながらと思うんですけれども、それから、そういうところの機構というのはどこなんですか。それぞれの自治体なんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"しかしながら、今回の緑確保の総合的な方針、そういった部分で各区だけを見ていては、東京の全体の緑を守っていけないでしょうと。２３区も含めて、全体としての動きとして、東京都の情報も十分にとりながら進めなければいけないと考えています。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"後でここの箇所をどこなのか教えていただきたいと思っているんですけれども、さまざまな施策というんですかね、民有地がなくなっていかないような。候補地だからまだ確定していないのかどうか、その辺も含めて、教えていただける範囲でいいですから、説明を求めました。","respondent":"藤田水とみどりの課長","answer":"今回、こちらの既存の緑を守る方針ということで、水準１から水準３、それから、確保候補地ということで挙げてあります。担保をもう少しステップアップするといいますか、そういった形のものができないかどうか検討を進めたいということで、確保候補地に挙げてあります。","id":"exchange-004"},{"speaker":"石田委員","kind":"意見","question":"公有地だったら、民有地となると、どのように守っていくのに施策を打っていくかというところが一番重要なところだと思うんですよ。例えば品川区としてはどのような優遇制度というか、そういうのを行っていかなければいけないと思うんですが、その辺のお考えを説明を求めました。","respondent":"藤田水とみどりの課長","answer":"現在、品川区では、先般行いました緑の実態調査では、公有地と民有地の緑の割合はほぼ同じぐらいです。民間基金との連携を図った緑の保全のための策を講じていく等の策、それから、その辺を複合的に進めることで守っていきたいという考えを示しています。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"国も今やっているもろもろの土木といいますか、こういう部分に関する事業の仕分けによって影響を受けることって当然出てくると思いますけれども、そういうのってあり得るんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"これまで事業仕分けという形でさまざま進められてきている中で、そういうことも当然あろうかなと考えます。ただ先ほど申したのはあくまでも東京都の制度で、今年度新たに立ち上げた制度ですので、今年度については間違いなく実施されるものと考えています。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"品川区は２５カ所目標を持っているという話を聞いたんだけれども、それだけじゃなかなか現実は進んでいかない気がするんですよ。例えば来年度はこうしていくとか、品川区としてこうしていくとか、より具体的な品川区の方向性というのは聞けないんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"先ほど申し上げたのは緑確保の総合的な方針を進める上で、全般的なお話ということで考えているところです。事業のあり方についての検討、それから実施計画等の策定も控えておりますので、新規にできることについてはまた考えていきたいと考えています。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうなると、やっぱり権利関係が生じてくる話であって、それは２５カ所が進めないということは私は思っていないんです。その計画をどれぐらい胸に品川区としては考えていって、その具体的な展開をしていくのかという見通しについてお聞かせほしいと求めました。","respondent":"藤田水とみどりの課長","answer":"そういった中で、私どもとしては１日も早く具体的な取り組みが進められるよう進めていきたいと考えています。今回の緑確保の総合的な方針で２５カ所と挙げているものにつきましては、現在そのうちの半分以上は既に品川区の保存樹林に指定されているところです。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"東京都と区市町村と連携をして全体を見直していくという視点がものすごくこれから求められていくなと考えていますけれども、品川区に求められる部分というのをどう受けとめていらっしゃるのか、その辺をちょっとお聞かせいただきたい。","respondent":"藤田水とみどりの課長","answer":"既存の緑を守る方針のところが先ほどからお話のある２５カ所をとりあえず区として今、品川区で申し上げますと、それから開発等ででき上がる公園。当然既存の緑を守るということで、あわせてこの緑のまちづくり指針のほうも進めていくことが区として重要であると考えています。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"一体となってやることがあるのかどうか、ちょっとその辺も伺いたかったのと、区民との協働のところがかなりうたわれていますよね。関心も高いものでもあるなと思うので、ちょっとその辺を今後どのように進められるのかということを聞かせてください。","respondent":"藤田水とみどりの課長","answer":"区内でいろいろ考えてみますと、そういったものも１０年後の東京の中で策の中に示されてございまして、校庭の芝生化等も進められているところです。それから、区民との協働の部分なんですが、ちょっと説明が不足して申しわけございませんでした。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すごくいろいろな助成の制度を充実してほしいとか、区民がいろいろ参加できる部分を増やしてほしいという意見もアンケートの中にかなりいろいろ載っていたので、ぜひ区民との協働が進むような取り組みを進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"５月の下旬、２７日に都が公表するということで、多分その結果ですね。もし区としてのコメントというか、そういう考え方が出るのであれば、今どのような内容を考えられているのか教えていただけますか。","respondent":"藤田水とみどりの課長","answer":"そういった部分については、当該する自治体のほうがお答えをするということで、こちらの都区市町村の考え方という形になってあります。おおむねそういう考え方で進めていいんじゃないかというご意見ですので、これについて進めていきたいという考え方を述べることになるものです。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"そうしますと、この都区市町村の考え方というのは全体で１つということのイメージで、これは確認をお願いします。そのレベルを教えていただきたいのと、都が直接、広報の中身とそのパブリックコメントのもうちょっと細かいところを教えていただけますか。","respondent":"藤田水とみどりの課長","answer":"今回そういったものの取りまとめができましたという程度の、大変申しわけないんですが、広報の記事になる予定です。当然東京都のホームページ、それから、品川区のホームページのほうにも全文を掲載するということで考えてあります。","id":"exchange-013"},{"speaker":"浅野委員","kind":"質問","question":"品川区が受け付けたのが２件で１通ということだったんですけれども、ちょっとどういうシステムかというのをはっきり認識していなかったんですけれども、そういうのもある程度載せられる予定なのかということを。","respondent":"藤田水とみどりの課長","answer":"その中で、区のほうにお寄せいただいた意見だけで、品川区民の方が東京都のほうに直接ご意見を出したといったケースはなかったです。今回できませんで、それぞれの意見に対するご回答等については、本文のほうをごらんいただくという形になります。","id":"exchange-014"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも機会を見て区民の方にもお知らせしていただきたいということと、ぜひとも実りある今回の緑確保の総合的な方針に、品川区としても大きな実績が出せるように進めていただければと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"}]},{"id":"topic-02","title":"を行います。 初めに１太陽エネルギー見本市の開催","agenda":"を行います。 初めに１太陽エネルギー見本市の開催","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"１点だけなんですけれども、見本市を開催するのはもちろんいいんですが、品川区の地球温暖化対策地域推進計画がありますよね。そのことについて、例えば区民に対するＰＲとか、そういうことをここですると非常に効果が上がると思うんですが、いかがか尋ねました。","respondent":"工藤環境課長","answer":"昨年つくった地球温暖化対策の推進会議のＰＲの件につきましては、私どもいわゆる区の専用のブースというのをこの会場の中につくる予定です。新たな省エネルギー機器のＰＲ、合わせまして当然地球温暖化対策推進計画の概要版をお配りしながら…","id":"exchange-016"},{"speaker":"浅野委員","kind":"意見","question":"前回たしか７月の見本市のときに１,０００kwｈだったと思うんですけれども、これは両方とも含めてということなのかなと。見本市だけで２,０００kwｈという数字なのかどうかというところについて、今回の取り組みについてお願いできればと思いますとの意見を述べました。","respondent":"工藤環境課長","answer":"ＥＣＯフェスティバルとあわせてですので、ＥＣＯフェスティバルで１,０００kwｈ使うということで、合わせた数字を記載しています。少しわかりにくいかと思いますけれども、このイベント２つで２,０００kwｈということで、よろしくお願いいたします。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問・要望","question":"倍増は２つのイベントが一緒だということですけれども、それをあわせた何らかの方針というんでしょうかね。それともレベルとしては１回あたりこの程度の利用というんでしょうか、その方針でいくのかというところの考え方を教えてほしいと求めました。","respondent":"工藤環境課長","answer":"私ども今現在ですけれども、アピール度という部分でもなかなか難しいということで、区における大きなイベントを対象としております。考え方としては今お示しした大きな事業で対応していくことは変わらないんですけれども、今年度につきましては、考えているところです。","id":"exchange-018"}]},{"id":"topic-03","title":"２次世代自動車導入促進助成","agenda":"２次世代自動車導入促進助成","exchanges":[{"speaker":"石田委員","kind":"質問","question":"２点ほどお伺いしたいんですが、そこら辺のお考えを１つと、残り２台になるわけですね。その２台を７月３１日以降に申し込んだ人が優先的にというか、順番に助成されていくのか、その辺の随時受け付けの内容を説明を求めました。","respondent":"工藤環境課長","answer":"例えば４００万円の車のモデルだと、検討しているところでございまして、そういったわかるような形で周知してまいりたいと考えています。それにつきましては、７月の決定以降、随時受け付けをするということですので、それ以降は先着順という考え方になります。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認したいのが、ガソリンの車両価格というのは、利用者の方が欲しい電気自動車のタイプとガソリンの車両価格は随分差があるわけじゃないですか。ガソリン車両価格は、この申請の方が求められた電気自動車について、ガソリン車の価格をどういうふうにして判断していくんか尋ねました。","respondent":"工藤環境課長","answer":"説明が詳しくなかったもので、このようなことになったかと思いますけれども、電気自動車の型というのは、今、大体４２０万円ぐらいです。ですから、４３８万円から１４０万円を引いた数字の８分の１が助成されるということで、そのような形になってあります。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"今、ｉ－ＭｉＥＶでしたっけ。これから電気自動車が多分出てくるでしょうから、もう少し工夫が必要だと思いますが、ご答弁をお願いいたします。","respondent":"工藤環境課長","answer":"私どももその部分で導入を進めるということで、数字を入れてご説明するようなパンフレットをつくっていきたいと考えています。それを並行して周知してまいるということでご理解いただきたいと思っています。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"もう１点だけ。先にこの計画を決めているわけだから、この中でおそらく記述があると思うんだけれども、どうなんか尋ねました。","respondent":"工藤環境課長","answer":"その中でも特に車、運輸部門であれば自動車と鉄道部門ということなんですけれども、車からの排出という部分が８割方を占めている。そういった意味では計画の中の１つのメニューという形で新しく考えておりまして、今後も展開していきたいと考えています。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"どう考えても４台だけでこの計画を達成できるとだれも思っていないわけで、これからいろいろな施策を具体的に展開していくことを品川区がやっていく。ですから、最後に伺いますが、それからいろいろな方々がこのことについては取り組んでいかなければならないだろうと。","respondent":"工藤環境課長","answer":"区が直接、補助するだけではなくて、こういったものを扱っているということをＰＲすることで効果という部分は上がると考えています。東京都の動向等も見据えて、今回、この事業を新たに打ち出したです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その点を１つお伺いしたいのと、どの程度地球にやさしいのかという、ちょっとその辺をわかるように教えていただきたいのが１つです。ちょっとここのところも説明を、よくわからないので説明をしてください。","respondent":"工藤環境課長","answer":"従来、私ども低公害車の融資あっ旋事業というのを継続して実施しておりまして、プレスのときにはそのようなタイトルをつけさせていただいたです。プラグインハイブリッド自動車の助成事業に関しましては次世代自動車ということで、よりわかりやすくしているということで…","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"片一方とこれが一緒という受けとめ方でいいんですか。そこの違いがあるのかないのか、ちょっとそこを説明を求めました。","respondent":"工藤環境課長","answer":"申しわけございません。新たに購入することではなく、新規事業であるということで新規とうたっております。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"予算が次世代自動車購入助成で１６０万円になっているんですが、区の独自のを書いているということなんでしょうか。４台じゃなくて、もうちょっと気構えを見せていただきたいなという思いがあるので、ぜひ力を入れてやってほしいと求めました。","respondent":"工藤環境課長","answer":"この４０万円ですけれども、ご質問のとおり、区からのすべての財源になります。４台につきましては、今後状況等、メーカーの導入状況、あと消費者の動向等を踏まえまして、今後も検討していきたいと思います。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"特別運輸部門は８割が占めているというところを伺ったりすると、促進させていくということが同時に必要になってくるんじゃないかと思ったんですね。そのほかの事業のところでの関係はどうなっているのかを改めて知りたいし、促進させていくべきだと考えていますので、その辺について伺います。","respondent":"工藤環境課長","answer":"今、市場に軽自動車が出てきたというのが現状です。まだまだ先ではないかと考えていますけれども、今後、そういった動きも出てくることにはなろうかとは思っているところであります。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"私も率直に４台じゃ、できるだけ増やしていくという方向をぜひ打ち出していただきたいという思いの中で、そういうふうに質問させていただいたんです。思いつくままでも、もっとウィングを広げて、見回して対策をとっていただきたいということを意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"浅野委員","kind":"質問・要望","question":"何点か質問させていただきたいんですけれども、それ以外に例えばクリーンディーゼルですとか、充電器の設置事業にも補助制度が出ている。こちらのほうのほかの部分をやらないのか、それとも今後検討されるのか、それについてまず教えてほしいと求めました。","respondent":"工藤環境課長","answer":"当然次世代自動車を普及させるためには、それを拡充しなければいけないという考えの中で行われているというのは、私どもも認識しております。大手のホテルチェーンの中でも、個別に充電スタンドを設置しようという動きも出ておりまして…","id":"exchange-029"},{"speaker":"浅野委員","kind":"質問・要望","question":"そこら辺のただし書きというんでしょうか、そういうところも気をつけなければいけないのかなと思います。プラグインハイブリッド自動車への要望も多い中で、どのように考えていかれるのかなと思いますので、どのようなお考えなのか。","respondent":"工藤環境課長","answer":"そういった意味では、多分東京都もそのような動向を見て５台にしているという部分だと私どもも認識しておりますので。それがすべて電気自動車の中でいくのではないかなという想定の中で考えているところです。","id":"exchange-030"},{"speaker":"浅野委員","kind":"質問・要望","question":"リスクがある場合には、また区として独自に何らかの方策をとるなりしていってほしいと求めましたので、その点は要望でお願いします。区民の皆様にさまざまな場面で紹介していただき、地域推進計画達成を目指して取り組んでいただければと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270609?Template=document&Id=6186#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":28175,"voices":84}},{"id":"h22-20100520-8","meetingId":"h22-cm05","date":"2010年5月20日","dateIso":"2010-05-20","committee":"建設委員会","time":"午前１１時０２分～午後３時３０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483234?Template=document&Id=3976#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":2123,"voices":10}},{"id":"h22-20100601-6","meetingId":"h22-cm06","date":"2010年6月1日","dateIso":"2010-06-01","committee":"区民委員会","time":"午後１時０３分～午後２時４１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"の２番目、事務事業概要","agenda":"の２番目、事務事業概要","exchanges":[{"speaker":"菊地副委員長","kind":"意見","question":"今年度事業部として、これをとにかく最大限力を入れていくんだというような、その辺の考え方みたいなところがあればお聞かせ願いたいんですけれどもとの意見を述べました。","respondent":"宮地地域振興事業部長","answer":"平成２２年度も継続、秋３億円ということで６億円にしまして、非常に力を入れているところです。全部言いますと全てが大事なんですけれども、どの課の事業もおそろかにできない事業で、それぞれ大切にしていかなければいけないと。","id":"exchange-001"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"ぜひこれからの委員会の中で、いろいろな形で報告を出していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"山内委員","kind":"意見","question":"その辺は正副委員長でお考えいただいて、テーマも含めてなんですが、これもやはり正副委員長と理事者の方との相談でよろしいのかなと思います。基本的にはそういう形でとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"先ほどの部長のご答弁にもあったように、中小企業問題というのは、商業にしても工業にしても相変わらず大変な状況にあるということで、ぜひこの経営支援を含めて、中小企業問題というのを年間を通した調査事項に乗せていっていただきたいと、お願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/397696?Template=document&Id=2580#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":31091,"voices":58}},{"id":"h22-20100601-7","meetingId":"h22-cm06","date":"2010年6月1日","dateIso":"2010-06-01","committee":"厚生委員会","time":"午後１時０２分～午後４時０２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"山元委員","kind":"意見","question":"同じく公明党の山元です。どうぞ、との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要を行います。 これにつきましては、改選後の初めての委員会で、各所管の各事業概要","agenda":"事務事業概要を行います。 これにつきましては、改選後の初めての委員会で、各所管の各事業概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"すべて完備しているとかということが、どういうふうになっているのか、ちょっとこの辺も伺いたいと思います。５点目でしょうか、施設基盤整備ですから８１ページですが、その辺も伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"区民の方の部分でも、在宅介護支援センターを中心に、もちろん私どもの各支援係がすぐに対応できるような仕組みを持っております。この７０戸と２０戸で、９０戸を予定しています。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"１年間のトータルですから、どうしても思えないんです、今までの経過を聞くと。ですから、もっと予定した以上にお金がかかるということではあれですから、説明をしてほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"９月につきましては、入所開始と取り下げと契約終了を全部足しますと、もうちょっと工夫をさせていただきたいと考えております。それぞれの認定について変更があったもので、これはちょっと変だという話があるわけでございまして、そういうもの対して対応していったです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"負担が半減したわけですから、私は、ぜひそういう方向でやるべきだなと思っています。したがって、そういう誤解をされないような公表をするべきだということを、強く求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"中塚副委員長","kind":"質問","question":"こういう区民の実態をどう分析しているのか、今年１年、それぞれお考えを伺いたいと思います。それからもう１点、去年と今年で変更となった事業はどういったものがあるのか、変更点をご説明いただけますか尋ねました。","respondent":"木下健康福祉事業部長、本保品川区保健所長","answer":"国のほうもさまざまな角度から検討しているということでありますので、多分もたないだろうという認識に立つべきだろうということだと思います。言ってみれば、全国でかなりばらばらな認定審査を… 問題点もなかったわけではありませんけれども、それからタミフルの備蓄なども含めて、対応がよかったということです。それは危機管理対応のところですけれども、今後も健康づくりが担えるかなと、期待するところでもあります。","id":"exchange-005"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"これが１０年経ちますと１０歳年を取るわけですから、７５歳、先ほどのお話では見えてきませんでした。しっかり具体化すべきだと思いますけれども、どうお考えなのか、伺いたいと思います。","respondent":"木下健康福祉事業部長、永尾障害者福祉課長","answer":"具体的には、特に高齢者福祉の部分について、今、現実に困っている方への早急な対応ということだと思うんです。特に在宅の方々で要介護３以上のかなり厳しい方々について言うと、１回か２回を経る中で… 先日、請願がございました点字ディスプレイに対しての要望が強いということで、急遽、障害者福祉課のほうで、日常生活用具検討会を招集しております。６月７日にやる予定になっておりますので、身体障害者…","id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今後の対応策、どう考えているのか、ちょっと伺いたいと思います。区としてのこの事業を進めていく主体性がどこにあるのか、先ほどの説明でもよくわからなかったので、そこはもう少しご説明いただけますか尋ねました。","respondent":"平澤生活福祉課長、木下健康福祉事業部長","answer":"こちらに、先ほど、ご説明した年間の平均の保護者数が載っているところですが、2)をご覧いただきたいと思います。それからもう一つが、見守りを中心としたケースワークをしていくというような考え方に立って… 実施設計の中で生かしていきませんと、過去にはいろいろ出てきたわけでありますので、そういうことは避けていきたいということであります。これから実施設計を詰めるわけでありますので、サービス提供の内容から…","id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"つまり、障害者、高齢者のほうとの連携といいますか、利用者へのＰＲといいますか、その辺は、今、どういうふうに組まれていらっしゃるのか。この高齢福祉部からのＰＲについて、始まったばかりの制度ですけれども、現状をご説明いただけますか。","respondent":"冨岡高齢者福祉課長","answer":"この制度については、当然、連携をしてご説明をしていくところです。それは在宅介護支援センターとも連携を取りながら、連絡を取りながら、この事業をうまくいくように進めているところです。","id":"exchange-008"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"何点かあろうかと思いますが、その何点かのうちの１点は、それを主題にして場所を選定していく。テーマまずありきで、私はテーマだけ投げかけさせていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"南委員","kind":"意見","question":"どういうものだとか、どういうふうな考え方で、その辺をちょっといろいろ聴取おきたいと思うんです。長期基本計画にも載っている高齢者施設、そういう方向でも、入れてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"区民の方々の切実な要望でもあるので、今非常に更生施設が不足していて大変だと、そういう部分も含めて調査を行っていきたいと思っているんです。ですから、そこら辺もちょっと見て、視察を検討していってもいいかなと思うので、リンクしているので、発言しました。","respondent":"鈴木委員長","answer":"所管事務調査につきましては、後ほどその他で振らせていただこうと思っていたのですが、委員会視察としても、当然、所管事務とあわせた上で考えていきたいと考えています。","id":"exchange-011"},{"speaker":"三上委員","kind":"質問・要望","question":"行政視察ですから、所管事務調査という視点もあるかもわからないけれども、先進的な取り組みということを眼目にした行政視察にしていただきたい。のちに、委員長に、そういった点で、何点かあったら、至急提出したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/360687?Template=document&Id=3268#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":51954,"voices":81}},{"id":"h22-20100601-8","meetingId":"h22-cm06","date":"2010年6月1日","dateIso":"2010-06-01","committee":"建設委員会","time":"午後１時０３分～午後３時０４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"の１、幹部職員紹介","agenda":"の１、幹部職員紹介","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区のほうで現在のまちづくりの基本としている計画の対応というんですか、現在のお考えとあわせて、ちょっとお伺いしたいと思います。これから進めようというのであれば、防災、地震に対しての対応というのはどう考えていくのかというのをあわせてお伺いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"現行ではどういうふうな方向でまちづくりをしようとしているんですか、現行の計画というのはどういうようなものですかというのを聞いたので、どういうお考えがあるんですかというのを聞いたので。","respondent":"片田防災まちづくり事業部長","answer":"その中の１つだと私は再開発を考えております。それをきちっと誘導した中で望ましいまちづくりのほうに進めていくということで考えているので、ぜひともご理解いただくことをよろしくお願いします。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"今日全体の概要ということなのでお伺いしたいんですけれども、区としては通行の需要についてどのように考えているのかということをお伺いしたいのと。利用しやすいまちづくりという点ではどのようにお考えになっているのかというのを、全体的な質問なので、お伺いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"２件ほど伺いたい。９７ページ、これ大井プレイス、こういう書き方で載せていいんですかね。","respondent":"三宅都市開発課長、中山防災課長","answer":"９７ページの広町地区の開発構想ですが、それが動き出すときに急に考えるのでは間に合わないということで、この構想はずっと持ち続けておるという状況です。 危機管理室だとか、ほかの区を当たってみますと危機管理室が中心になっていると。総務部と危機管理室と協議の上、多分防災課になると思いますけれども、調整はしてまいります。","id":"exchange-004"},{"speaker":"阿部副委員長","kind":"意見","question":"こういう形で置くと事務事業概要に載っているということ自体がどうなんだろう、これ、みたいなことになるかなと。私のほうはちょっと違和感がありましたとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"その資料の１つだと、このようにご理解いただければと思います。一応まだ進めている事業では、一応危機管理のほうと十分調整しながら精査をして明確にしていきたいと、このように考えてあります。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"いろいろ昨年やってきた中で、所管が変わってきたりしたというのは、具体的に何か大きなものがあれば教えてください。なければもうなしでも結構なんですが、１年やった中で今年どういうふうに区としてやっていくというのがあればお願いいたします。","respondent":"中山防災課長、松代都市計画課長","answer":"そういうの今年になって１７件目ですから。これは正直申し上げまして、事務上も大変な作業だということは申し上げられる。 ご説明したように、さまざまな事業を今展開していますが、その中で、これまでの旧土木・建築等の事業母体は、ハードが中心でございました。そういった面では、ハードにあわせてソフト的な対応を兼ね合わせてやっていこう…","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"その概要を聞いて全体的な質問しましたので、１年に１回の最初の委員会ですから、ここでしか聞けないところもあるわけです。やっぱり私は、大事だと思いますので、ぜひとも今後の委員会運営に活かしてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"景観行政団体になること","agenda":"景観行政団体になること","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"２番目のところの景観審議会ですが、ちょっとわからなかったので、今回の条例策定のためにつくられるものなのか、それともこれからずっと続いていって、景観についていろいろ継続的に議論していく場なのか、ちょっとそこだけわからなかったのでとの意見を述べました。","respondent":"藤田水とみどりの課長","answer":"皆さんにご理解いただけるように進めていくかという観点で、景観審議会を設置するというふうに考えてありますので、継続し区内の景観を見守っていくために設ける審議会です。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"あわせて伺います。ちょっとこれは端的にお伺いしたいんですが、メリットというんですかね、お伺いします。","respondent":"藤田水とみどりの課長","answer":"審議会のほうの構成メンバーですが、今上限を１１名ということで考えてあります。これに取り組んでいくことが地域のまちづくりを進めていく中で重要な位置づけになる、区民のメリットにつながっているということで考えてあります。","id":"exchange-009"},{"speaker":"市川委員","kind":"質問","question":"２名の区民委員を募集するということで、今詳しいお話を伺ったんですけれども、募集して、もし非常にたくさんの応募があったという場合は、区民委員を増やすとか、そういうような形になるんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"今回は、一応区民委員については２名ということで考えてあります。その中でもより深く考えていただいている方を選出をして、その中の２名になっていただくということで進めていきたいというふうに考えてあります。","id":"exchange-010"},{"speaker":"市川委員","kind":"質問・要望","question":"希望としては、区民の方の意見も大きいのではないかと思いますので、希望としては増やしていただきたいなということを思います。この辺は何か、そうではないところと検討されたのかどうか、その辺を伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"そのほかにもパブリックコメントを実施しながら進めるとか、意見をお聞きしながら進めていく、そういうような方向で考えているものです。曜日の関係も含めて検討はしたのですが、皆さんが参加しやすいというようなパターンで考えると、こうした形で進めたいと考えているものです。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"お互いのバランスというんですか、学識経験者は専門家ということで、いわゆる景観そのものを見られるわけです。どういう構成、専門分野で７名ですか、どういうバランスを保ってやられるんか尋ねました。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"学識７名という、大きな枠として７名ということで考えておりまして、当初は６名でスタートしたいというふうに考えてあります。さまざまな場所に知識にたけた方も多いんですが… 法律は予定しておりません。これは作成するまでに意見は聞く予定ですが、実際これが動き始めますと、個々の物件ごとの審査になります。","id":"exchange-012"},{"speaker":"阿部副委員長","kind":"質問","question":"それが、じゃあ具体的にどういったものがあるかということを検討して、次回もう一度お話をするというような流れでどうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"水族館の今後の運営方法なんていいのではないですかね。北海道はあまりないんだよな。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"阿部副委員長","kind":"質問","question":"今回の行政視察になるのかどうか、景観にかかわる、あるいは景観行政団体になっているところを見に行くということも１つ。やはり品川ですから、都市の防災、そういったところでいい事例があれば見に行きたいなとは思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"意見","question":"先ほど８区２市でやっているということがありましたので、既に景観団体になっているところで、実際になった後にどうだったのかということを含めて。そうしたら非常に有意義になるのではないかと思いましたとの意見を述べました。","respondent":"原委員長","answer":"６月４日までに委員長あて、または事務局までいただければと思います。〔「はい」と呼ぶ者あり〕","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"何か人気がないようなところが、同じような事例が以前あったんですけれども、年内に入ってすごく増えて１７件ですか。これからどういう対策というのをお考えになっているのか、そこら辺の現状分析というか、お伺いしたいと思います。","respondent":"中山防災課長","answer":"広報紙に、一応消防署と共同で火災予防の訴えを掲載する予定があります。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"多分いろいろな原因とかも、前あった火災も、今日のやつも今、捜索中なのかもしれないんですけれども、区としては何か現時点で、こういうところが主な出火の原因というか、要因につながっているというのは分析などは、発表できるものがあれば教えていただきたいなと思うんですけれども。","respondent":"佐藤防災安全担当課長","answer":"本日の火災も含めて、火災原因調査については東京消防庁が所管しております。その対応については先ほど防災課長もお話ししたとおり、火災予防の徹底について消防署と連携して徹底してまいりたいというふうに考えております。","id":"exchange-018"},{"speaker":"原委員長","kind":"提案","question":"委員会の皆様のご意見、ご要望をお聞きして、今後の委員会運営の参考にさせてほしいと求めました。つきましては、委員の皆様から建設委員会に係る所管事務での調査したいテーマがありましたらばご提案していただき、委員の方々いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483234?Template=document&Id=3978#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":37013,"voices":97}},{"id":"h22-20100601-9","meetingId":"h22-cm06","date":"2010年6月1日","dateIso":"2010-06-01","committee":"文教委員会","time":"午後１時０２分～午後３時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"どういうものについては子ども未来事業部に伺うのか、その区分けだけ教えていただきたいことが１つと、３０ページの移動教室の中で。その意味合いがちょっとわからなかったので、５年生と８年生が一緒に行くのはどこに入るのかというところ、そこを説明を求めました。","respondent":"市川教育次長、富田学務課長","answer":"この時点で、こういう項目については教育委員会から、こういう項目については子ども未来事業部からという取り決めはしてございません。今度は小学校のほうにウエイトをかけた検討を進めて、モデル実施をしているわけでございまして… ８年生については、特に教育委員会で予算計上して事業実施をしているものではなく、学校の独自事業ということで行っています。団体行動をするということで実施しているものでございまして、小学校は５年生のときに実施しており…","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"これからケースに応じてということでしたので、質問を終わりにします。独自でいろいろされるのはいいんですけれども、多分、移動教室という名前だと補助が出るんですよね。","respondent":"冠木指導課長","answer":"５年生のほうですけれども、学校独自が取り組んでいる行事につきましては、学校が計画して取り組んでおります。私どもの２つの課から対応があるですけれども、基本的には学校独自で予算等も編成をしていただいてやっていただいているという考え方が基本です。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"生活保護を受けている方、支援という考え方が、おそらく教育課程外になってしまうと、それが入らないということになるんですか。それだけ説明を求めました。","respondent":"富田学務課長、冠木指導課長","answer":"６年生、７年生の移動教室も対象としています。それ以外のものは支給しておりません。 もう一度整理いたしますと、移動教室については教育課程内ということでやらせていただいておりますので、区からの対応があります。夏季施設については、基本的には教育課程の外側ですので、対応は基本的にはございません。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"久しぶりの文教委員会なので幾つかお伺いします。ページを追っていきますのでどんどん伺います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この次の９ページのところで、そういった中で選ばれるための学校の特色というのをどうとらえたらいいのか、その辺を改めてお伺いしたいと思います。１６ページの健康、特段の今後の対策が求められると思うので、ちょっとこの辺をお伺いしたいと思います。","respondent":"田村庶務課長、冠木指導課長、和氣小中一貫教育担当課長","answer":"私から、何点かご質問があった中の１つ目の教育目標の検討状況ということと、最後の４点目の教職員の健康管理について、ご説明します。… 私からは特色づくりのところですけれども、要は、システムとしては多くの学校で取り組んでいただける状況は完備されてきたです。同じ教科担任制… 私からは、専門外部評価についてご説明を差し上げます。目標は立てたけれども、学校経営を進めていくという形での学校の体質改善を図っていくというのがこ…","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もうちょっと前段のところに格調高く入れてほしいなと、２点目のところに「人権」という言葉があるんですけれども、ちょっとお伺いをしてみました。５館が職員ゼロになっているので、専門性が保たれているのかどうか、その辺をお伺いしたいと思います。","respondent":"田村庶務課長、和氣小中一貫教育担当課長、富田学務課長、小川品川図書館長","answer":"それと、利用率なんですが、記載しても構わないんですが、ちょっと難しいのは、平日の利用率と、あと、土曜日は利用率が若干低いんですね。例えば年… 成果基盤型学校経営は、「プラン２１」発足当初から、平成１２年度からずっと使ってご説明させていただいているところです。 給食調理代行を受託している企業の数ということですが、９社でございまして、一番多いところで７校を担当しております。 その委託業務の拡大をしている状況の中で、平成１９年４月より職員の常駐の館が６館…","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ブロック体制の中でバックアップをしているから大丈夫ということなんですが、委託ですか、そういった窓口ではなくて中のほうもそうですよね。バックアップ体制で十分できるのかどうかというところが、発展させていくために今の体制でいいのかどうか、その辺のお考えを聞かせてください。","respondent":"小川品川図書館長","answer":"特に一般図書に関しては、品川図書館で集中して点検をして、品川全体を見渡して満遍なく資料が収集できるような体制をとっております。そうした面で、根幹業務については職員がしっかりと体制を整えて執行しておりますので、その辺はご心配ございません。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"変わったところの理由、そういう思いとかは教育委員会での決定ですので、その辺の議論のところをちょっと紹介してほしいと求めました。","respondent":"田村庶務課長","answer":"変更点は（２）の「指導者の合同研修」というのを入れたのと、幼稚園・保育園との協同実践を展開する」という新たな記載を設けてあります。（４）のところで、ＩＴ化の対応で…","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"そういうところでもうちょっとあったのかなというふうに思いながらお伺いしていたんですが、今、すごく具体的に盛り込まれている。そういったところの外に向けての品川区の教育委員会としてこういう教育方針を持っているんだというのは、外にどこかで出されるものなんか尋ねました。","respondent":"市川教育次長、古川子ども未来事業部長、安井子育て支援課長、吉岡保育課長、伊崎待機児童対策担当課長、小林青少年育成課長","answer":"特別支援教育、これまで９年間を通しての特別支援教育の展開ということを考えて、大綱は変わらないということでご理解をいただければと思います。… ７ページが子どもに関する施策の現状と考え方ですが、細かい点につきましては、これから各課長がそれぞれご説明申し上げます。詳細につきましては… 次に９番目、品川区のシルバー人材センターで実施しますこちらの自転車のレンタル事業について支援していくものでございまして。… 認可保育園の基本保育時間につきましては、保育ニーズの多様化に対応いたしまし…","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この入れなかったお子さんとの数字の差異は何なのかというのを改めてお伺いしたいのが１点目です。３３ページの（４）の認証保育所保育料助成制度の中身を教えていただきたいのと、制度が変更して、その辺を説明を求めました。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"私から、待機児童に関するご質問に対してお答えを申し上げます。あるいは近くに入れる園があるにもかからず、特定の園しか希望されない方、また認証保育所に在園していらっしゃる方などが含まれております。 一応、区の０歳児の保育所の平均的な金額です６万６,０００円を上限にいたしまして、支払うべき保育料との差額の部分を助成する。それによって認可保育園へ入った場合とほぼ同等の経済的なご負担で認証保育所へ通えるようにする…","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"要件の中に月１６０時間、本当に８時間で５日間がっちり働いていないと受けられないということにおいては、新しいものは受けられない。前に受けていたけれども、今度の基準でだめになるような方がいるのかどうかというあたりをもう１回聞かせてください。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"待機児の基準につきましては、国から待機児童の定義が出ておりまして、それに基づいて現在報告をしております。こちらの数字で東京都を通じて国のほうに報告を上げておりますので… 今年度の条件の中に月１６０時間以上の月極め契約というようになってありますけれども、この部分は昨年も変わらず１６０時間以上となっています。それで去年受けられたけれども今年受けられないということはございません。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"新定義の基準の中身を知りたくてお伺いしたので、どういう基準なのかというのを改めてお願いします。中身がどうなのか全くわからないので、４・５歳のところの内容を含めて、もうちょっとここを教えていただきたいと思っています。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"それと、引き続き、４月以降の入園を希望していない方というところで、こちらも除いております。先ほども申し上げましたような判断でおりますので、報告している数字がございましたら、また確認してまいりたいと思います。 ４歳、５歳の区立幼稚園という形で、区立の幼稚園をベースに認可の区立保育園を合体させた形で幼保一体施設という形でやってきました。保育園部門を当初の予定では０歳から３歳までという予定だったんですけれども、５歳が保育園…","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほどの待機児の新基準のところで改めてお伺いしたら、４月以降の申し込みをした人のみが新基準の中でカウントされるわけですね。受けられるんだけれども申請をまだしていない人がいるというようなことも伺ったので、その辺を現状を教えていただきたいのと、今回。","respondent":"安井子育て支援課長、吉岡保育課長、小林青少年育成課長","answer":"これは制度的に自動的には移行できませんので、こちらについては、戻ってきていない部分も幾つかあるというところはあると思います。… 保育園の独自性と連携のあり方というご質問ですけれども、保育園は保育に欠ける子どもの養育施設ということで、成り立ちも違います。この間… それぞれの実施については、実施計画を数値も含めて示しておりますので、そちらと連携をとりながら。きちっとした対応をしていくという意味では…","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"ごめんなさい、最後になります。待機児に限ってお伺いしますが、保育の需要をどうとらえているのかというところでさっき質問させていただいたので、それもお聞きします。","respondent":"小林青少年育成課長","answer":"１つの仮説として、まず３４％達成を前提として進めていくという形での話はありますが、それぞれ主要な項目について施策の実施状況を代表する指数。この基本的な後期の考え方を庁内関係課の連絡会をもとにして、そして施策に対応していくということで…","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"中身ですが、特に認証保育所の基本的な部分について、どこまで私たちは言える権限があるのかなと思うんです。それぞれの認証保育所にフィードバックするというような形ができるのかどうか、その辺についてお伺いします。","respondent":"吉岡保育課長","answer":"あるいは施設の状況、人員配置等々を伺った上で、区を経由して都へ書類が出されている状況があります。今回ご説明した保護者への補助金ですとか、こちらの意向はお伝えすることは考えておりますが、内容によるかなということがあります。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"品川区の保育の内容というものは非常に高いものですから、それに合わせて認証だからやらなくていいよというわけではなくて。そこら辺の責任のとり方というか、やっぱりちゃんと伝えるべきところのルートがあればいいのかなと思うんですけれども、その辺について伺います。","respondent":"吉岡保育課長","answer":"委員おっしゃるとおりと考えてございまして、アレルギー食の対応ですとか、そういう区民の方々の要望があれば個別にお話をしていきたいと思います。","id":"exchange-016"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"日程的には月末は外していただきたいなと思うのと、これから内容にかかわってきますけれども、２泊３日にこだわらずして、１泊とかで。どうしてもここへ行きたいという内容だったら、１泊でもいいとか、やっぱりあそことあそことあそこというふうな感じでなくできたらいいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"そういうことだと６日の週になるのか、そこは第３回定例会の通告期限とか関連……。〔「まだでしょう」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"井桁委員","kind":"意見","question":"ぜひ文教委員会としてもこのような放課後の対策、もしくはまた学習の支援ということで、地域から発信していくことで見に行くのも１つの勉強になるかなと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"金野委員","kind":"提案","question":"私どもがこれまで議会の中でも提案してきたスクールソーシャルワーカー、この点も１つ調査をしていきたいなと、このように希望しております。１つ、この辺のところを少し見てこられたらなと、このように希望しておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"意見","question":"不登校とか虐待問題で取り組んで前に進んでいるところがあったら知りたいなと思っていたのが１つと、まだそんなところなんですが、内容としていいかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"井上委員","kind":"提案","question":"子どもたちの生きる力というところで、食育なんかを取り込んだ教育ということで、香川県だと思ったんですが、お弁当の日を取り組んでいる。５年生で自分たちのお弁当をつくっていくというお話は聞いたことがあるんですが、取り組みとして実際にそういった…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"武内委員長","kind":"提案","question":"ないようですので、今後の委員会運営について、私からご提案させてほしいと求めました。できる限り審査・調査し、委員会の活性化を図っていきたいと考えておりますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/746735?Template=document&Id=4700#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":47803,"voices":105}},{"id":"h22-20100601-5","meetingId":"h22-cm06","date":"2010年6月1日","dateIso":"2010-06-01","committee":"総務委員会","time":"午後１時０２分～午後２時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"そういうときにはこの調査会というのはどういう動きをするのか、あとそういうところの調査会でいろいろ金融機関の経営状況等を調査・研究したということになると伺ったと思うんですけれども、どういう評価をされたのかというのを伺いたいと思います。","respondent":"福田会計管理者","answer":"そういうときに個々の金融機関等の状況につきまして、経済環境の分析を含めて、具体的な動きをしているです。不良債権の処理が順調にいっているかどうか、そういうところを評価の基準として、それぞれ評価をしています。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"平成２１年度は３回となっているんですけれども、あるいは対外的なやつでやっているかどうかとか、そういうものはあるのか。実際に委員会としてはどういう動きをするのかというのが、あともう１つ、お話ができるのであればと思ったんですけれどもとの意見を述べました。","respondent":"福田会計管理者","answer":"それでどうするかということをこの機関は任務としておりませんので、あくまでも分析にとどまるというものとご理解いただきたいと思います。個々の金融機関につきましては、それぞれ評価をいたしますので、全般的に金融機関はこういう状況だという評価はしておりません。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"全く同じなのかどうかということが１つと、全部やるのかどうか、また年度ごとに分けてやっていくのかも含めて伺いたいと思います。前に説明があった行革の２つのエンジンといいますか、途中で１個エンジンがなくなって、そこら辺のところをお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"行革の２つのエンジンと説明していたんですけれども、ＰＤＣＡサイクルのほうに移行したんだというお話なんですけれども、前回の仕組みがどうして切り替わったのかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"１回だけとなっているんですけれども、これは何かどういう考え方なのか、そういう考え方というのはないんだろうか。そこら辺の考え方を伺いたいということと、その意見というのはどういうふうに反映しているのかというのは、どうか尋ねました。","respondent":"中川原広報広聴課長、榎本人事課長","answer":"ほかの区の状況も調べましたが、やはり年４０回これをきちんとやれる事業者というのが、品川区内にはまだありませんでした。どういったことが課題なのか… よく新聞で２０歳代、平均年齢が４７歳ということで、年齢的にわりと高いほうの世代がちょっと入っているというところが特徴になっております。６時間の勤務とかをして、勤務軽減をかけるということで…","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"私はこんなところはまずやめるべきだと思うんですけれども、そこら辺の動きはどうなのかということと、委嘱する経過というのはどうなのか。１日大体１人じゃないかということなんですけれども、なぜこういうところがそのまま残っているのかということも含めて、ちょっと伺いたいと思います。","respondent":"中山人権啓発課長","answer":"人権相談に積極的に取り組むとともに、相談に当たっては、関係機関と密接な連携協力を図ることとなっています。品川区と一緒に足並みをそろえて対応していける団体であるということと、それから、組織的に品川区と一緒に対応できるということでお願いしています。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"意見","question":"だから、あえてこれを１人置いておく必要がないということと、今、私、推薦、委嘱、この仕組みは毎年ちゃんとやっているのかどうなのか。１日大体１人です、そういうところにあえて１人置くということとあわせて、どういうふうにやっているのかとの意見を述べました。","respondent":"中山人権啓発課長","answer":"引きずってしまいがちなところがありますので、そういった精神的なこともしっかりと対応できる相談員というのは必要かと私は考えているところです。そういう方たちが今現に相談を受けて使っていらっしゃるということですので、私としては必要な事業ということで考えております。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"意見","question":"それともう１つちょっと聞きたいんですけれども、しっかりした依頼、これをやったのかどうなのか。大体１人当たり３２０万円の給料が出ているわけですとの意見を述べました。","respondent":"榎本人事課長","answer":"その関係につきましては、各所管に人事課のほうから一斉に非常勤についての承諾書というのを取り交わします。人事課に依頼が来て、各所管でだれを任命して、どういうふうにするかというのをきちんと手続きをとっているところです。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"部落解放同盟品川支部に依頼ということではなくて、その個人ということで依頼して、オーケーをとるという形だということですか。この団体との話はどうなんでしょうかということと、もう１つは、何で事務所を議員にも見せないのか。","respondent":"中山人権啓発課長","answer":"同和問題に理解と認識を持ち、人権感覚を有しているということで、うちのほうでしっかりと部落解放同盟東京都連品川支部に推薦を依頼しています。あそこはあくまで相談室ということになっておりますので、見せてほしいということに対しては、お断りさせていただいているところで…","id":"exchange-009"},{"speaker":"宮崎委員","kind":"意見","question":"今、部落解放同盟品川支部に依頼しているとおっしゃいましたけれども、私、どうもこの事務所が、部落解放同盟品川支部というのはないんじゃないかと。利権あさりしている、そういう団体なんだということをしっかり把握して…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"林委員","kind":"質問","question":"「行財政改革担当（１人）」となっていて、２ページの組織図には載っているんだけれども、３ページ以降には載っていないんですか。行財政改革担当という、組織図にはあるんだけれども、説明文には削られているという、その意味を説明してくれますか。","respondent":"久保田行財政改革担当課長","answer":"私の関係ですので、私のほうから説明します。私のほうでも企画財政課長と連携しながら、事務事業評価の実施という欄もありますし、そういう形でこちらをつくらせていただいております。","id":"exchange-011"},{"speaker":"林委員","kind":"質問","question":"ですから、組織図に、ここに突出して１つだけ担当というものがあるのが不思議なんです。２ページの図でいうと、４つの課と同格に担当という組織が入ってきているんだけれども、この意味を聞きたいんです。","respondent":"久保田行財政改革担当課長","answer":"先ほどスタッフという説明をさせていただいたんですけれども、７番、スタッフとしての位置づけで仕事をさせていただいているものです。私もスタッフということで、企画財政課の中に入っておりますので、こういう形で表記をさせていただいたです。","id":"exchange-012"},{"speaker":"林委員","kind":"質問","question":"企画部長に聞きます。これだけ重要なことだったならば、行財政改革課というのをつくる意味が出てくるんじゃないのかと思うんですけれども、いかがか尋ねました。","respondent":"日下部企画部長","answer":"行財政改革の視点をその中にどうやって生かしていくかということも１つの重要なポイントとして考えておりますし、それから、事務改善もそうです。企画財政課の１つのスタッフ、そういう形で位置づけをしているですので、ご理解をいただければと考えています。","id":"exchange-013"},{"speaker":"林委員","kind":"質問","question":"去年も１００人を超えていたと思うんだけれども、品川区の中の組織を検討しなければいけないことというのは起きてこないんですか。どちらか、企画で言うのか、人事課長からなのか。","respondent":"榎本人事課長","answer":"経験者の方で大体３０代の方を採用して、ある程度年齢バランスをとるという形で埋めてきているところです。今５０代が一番多いんですけれども、あと１０年たつと５０代の方がいなくなるということで、さまざまな手を打っていこうと考えているところです。","id":"exchange-014"},{"speaker":"林委員","kind":"質問・要望","question":"会話力、新しい若い人たちに力をつけてもらうということに総務で何か課題を見つけてやっていくということはもうでき上がっているんですか。もう、そういう人たちが職員になって、３カ月ぐらいたつんだけれども、そういうことについて説明をしていただきたい。","respondent":"榎本人事課長","answer":"２年目、３年目でメンタルヘルスの研修ということでとらえるものもありますけれども、そういうものに力を入れてやってきているところです。研修の中では、その辺は、そういう認識を持って今後も頑張っていきたいと考えています。","id":"exchange-015"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"本多委員","kind":"意見","question":"平成２１年度の総務委員会の所管事務調査で挙げられた項目なんですけれども、可能であれば、そういった部分が取り上げられればと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/212618?Template=document&Id=1854#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":35079,"voices":96}},{"id":"h22-20100602-14","meetingId":"h22-cm06","date":"2010年6月2日","dateIso":"2010-06-02","committee":"行財政改革特別委員会","time":"午後１時０２分～午後２時５１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"同じく共産党の安藤泰作です。どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"デメリットなども含めて説明いただいたんですが、そこはちょっと単純にそうは言えないのではないかなということで一言言いたいと思います。ここは２００億円ですか、なぜ事務事業評価を、ご説明をほしいと求めました。","respondent":"金子企画財政課長","answer":"ご説明させていただければ、世界の同時経済危機というのが始まりまして、今に至るもそこから脱却できていないというのが現状だろうと思います。厳しい財政事情というのは現在もそうですし、今後も引き続いてこういう状況がしばらく続くだろうと考えているところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"今回の事務事業評価でそういった観点というのはちゃんと保障されるどうか、そこら辺、その２点をお伺いします。考えていくべきだと思うんですが、公有地、跡地活用の観点から見てどういうふうにお考えなのかということをお伺いします。","respondent":"久保田行財政改革担当課長","answer":"１点目、資料でもご説明いたしましたように、来年度予算に反映させていきたいと考えているところです。費用対効果の検証というものも不可欠であると考えておりますけれども、こうした視点のもとで事務事業評価を実施していきたいと考えているところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"この住民福祉の増進という担保というんですか、どういうふうに拘束力かという質問をしたんですが、そこについてはいかがか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"ですから、当然、住民の福祉増進という視点はこの評価の中で持っていると認識しています。そうした予算編成の作業の中で、あわせて事務事業評価を行ってまいりますので、そうした中で予算には十分反映できると認識しています。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"当然、あえてそういっているのであれば、ちゃんと文として明記したほうがいいんじゃないかなと思うんです。それは当然、今の精神を踏まえてやっていくということの宣言ということで受けとめてよろしいのかどうかをお伺いします。","respondent":"久保田行財政改革担当課長","answer":"私どもとしましては、そうしたものは当然、自治体としての考え方としてあるべきものだと考えております。そういう意味では、そういったところを明記しているものだと考えておりますし、そういった考え方をもとに事務事業評価を行っていくというものです。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"委員長にお伺いしたいんですけれども、この１年間これをどういうふうにするのかなということが少し理解ができないので、どういうふうにここで議論をしていったらいいのかということだけ先にご説明をほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"ですからほかの方が、正副委員長でこうですということがないのであれば、皆さんで意見をいただいて進めていただきたいなというのが１点です。今この流れでとにかくお聞きしたいことがあって、先ほどから、ちょっと意見交換をしていただいたらいいなと思うんですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"ですから、これが我々の１つですけれども、議員の中で事務事業評価をすべてつくっていけということになってくると思うんです。行政で評価したものをどう判断するかというのは、それは我々の仕事ですけれども、そういう流れでいったと各会派に行っていると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"３番目の予算、そういうふうにしていただきたいということは同じ思いなので、ぜひ正副委員長に行政側にそういう要請をしていただきたい。でなければ難しくないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"議会からの要望は理事者の方が受けとめて、ですから、そのまま出てきて私はおかしくないと思う。我々も１つ１つ、その６３５の事業をすべて我々が本当ならチェックしていって、最初のスタートが違うんじゃないかなと思うんですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"最後の最後、１回あるかないかという時期に出されて、何をするんですかということを言いたいんです。だから、そういうふうに仕切ってください、一次でも出してくださいよということを議会としてちゃんと言えるかどうかということだと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"須藤委員","kind":"質問","question":"今、この運営の仕方は鈴木委員が議会運営委員会の中を皆さんに説明したとり方でいいと思うんです。そういうことを質問していいのかどうかということを、そのあたりはいいかどうか、ご判断をお願いします。","respondent":"堺委員長","answer":"さっき(4)の今後の作業手順に従って進められていく過程において、基本線は、これは私は尊重したいなと考えています。その上で、その前段階で、さっき申し上げたような可能かどうか等についてはちょっとまた検討させていただきたいと思います。","id":"exchange-012"},{"speaker":"菊地委員","kind":"意見","question":"今も委員長から発言があった一次評価が６月といいますから、もちろん当委員会は毎月１回ぐらいずつのペースで進んでいくわけですけれども、区としての見解をお聞かせ願えますかとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"作業的なものですが、現在は６月になっておりますけれども、この時点、６月中いっぱいをかけまして、事業部長による一次評価を予定しています。一定の整理をしまして区としての方向性なり方針を出した上で…","id":"exchange-013"},{"speaker":"菊地委員","kind":"意見","question":"行革の１つの調査項目として出したのはいいけれども、いわゆる一番最後の委員会あたりでやるしかないという流れになっていくのかなと思います。どうしてもこれは調査項目として成り立たないというふうになっていくんじゃないのかなと思いますけれども…","respondent":"久保田行財政改革担当課長","answer":"私ども本日は調査事項概要ですので、まず制度の仕組みについての概要についてご説明しています。評価を実施していく上で、概要についてご説明いたしまして、また制度の仕組みについてご説明させていただける機会があればご説明しますし。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問・要望","question":"それは今、この中にどういうふうに盛り込んでほしいという要望をするとすれば、ここではなくて総務委員会で十分できるのではないかと思うんです。だから、仕組みを聞いて、私たちはどうしたらいいのかなと思うんですけれども、どなたか説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"ですからその評価をするのは、この中でも、その基準はどうなんだという聞き方はまたできると思うんです。少しこの中で、それもどこまで今日は聞いていいのか、その辺に移っていったほうが進むのではないかなと思うんですけれども。","respondent":"堺委員長","answer":"ただ、あるいはその評価を実施していく上において必要と思われる皆様方の、その事務事業評価実施に当たって必要と思われる皆様方のご意見があれば。その前段階で、いわゆる進捗状況に応じて提出可能なことかどうかも含めて、それはまた検討させていただければと…","id":"exchange-016"},{"speaker":"井上委員","kind":"提案","question":"これはもう提案でご検討いただければいいかと思うんですが、２本できれば、１２回の行財政改革特別委員会の中でご検討ほしいと求めました。そこに行政が評価したことに対して区民がそれをどう感じているか…","respondent":"久保田行財政改革担当課長","answer":"今回実施する事務事業評価につきましては、私ども行政内部の中で、区自身が主体となって行政、事務事業評価を行っていきたいというものです。事務事業評価の結果につきましては議会に報告した後に区民に公表していく予定ですので…","id":"exchange-017"},{"speaker":"井上委員","kind":"質問・要望","question":"外部の意見は必ず聴取していただきたいと意見をここで申し述べますが、きちんと区民の意見を反映して見直していくという姿勢で取り組まれていこうとしているのか、２点伺います。","respondent":"久保田行財政改革担当課長","answer":"見直した中で、そういったご意見等も取り入れられるような仕組みを検討して、その後に次の段階として発展させていきたいと考えているところです。そうしたものも真摯に受けとめまして、各事業部において一次評価の中からそういった形で取り組んでいきたいと考えているところです。","id":"exchange-018"},{"speaker":"井上委員","kind":"質問","question":"さっき３つ説明いただいたので、３番目のところなんですけれども、なぜこの項目に絞られたのかをお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"私どもは、こちらにつきましては区民の貸出施設を中心に、保育園、幼稚園等の施設配置という視点も取り入れた形で載せてあります。今、施設の状況がどうなっているかということを知りたいということでございましたので、こういった形で保育園と幼稚園を載せたです。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"どういう施設がここにあって、その辺のデータをぜひ行政に出してほしいと求めましたので、検討して働きかけてほしいと求めました。品川第一地区の北品川だと１２％とか、そこがちょっと理解できないので、そこを説明いただけますか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"私の説明が漏れてございました。日曜日とか、そこの部分については貸し出しをしておりますので、そこの利用率を載せさせていただいているです。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"どういうふうにシルバーセンターも含めて活用していくかということが、そういったところの２つに分けられて、これも要望です。お願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"確認","question":"その上で幾つか確認事項なんですけれども、私が聞き損なったのかどうか、今度の全事務事業というのは数はおっしゃいましたか。そこの確認を、ですから、そこら辺を確認で説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"そうした中で数は若干８００から９００の間から変わると思うんですけれども、おおむねそれぐらいの数になるのではないかなと考えているところです。平成１６年度、平成１７年度の場合も、こうした中で少しずつ増をしながら推移しているのかなと考えています。","id":"exchange-022"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから行政がやる事務事業評価に対して、その事業１つ１つを私たちがどうこう見直すとかという必要は私はないと思います。要望です。","respondent":"久保田行財政改革担当課長","answer":"先ほどもご説明しましたように、煩雑になってしまったということが１点、効率性という３段階の評価の視点をそれぞれ取り入れさせていただいたです。４年ぶりに事務事業評価という形になりましたが、いつまでということはありますけれども…","id":"exchange-023"},{"speaker":"渡部委員","kind":"質問","question":"やってみて、本当にこれが有効であれば、それは継続していくことが必要だと思います。１つ、これは各事業に対して１つの書式なり、それに対してみんなで事業部内会議とかで評価していくんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"本日こちらはつけてございませんけれども、１つの様式を定めまして、その中でそれぞれの項目について記入していただきまして、そうした数字的なものもありますけれども、そうしたものも記入した上で事業部長のほうで一次評価をしてもらうという形になってあります。","id":"exchange-024"},{"speaker":"菊地委員","kind":"質問・要望","question":"１つだけお聞きしたいんですけれども、前回、私なんかはいわゆるコストをどれだけ削減していくかということが基本だったんだろうなと思うんです。実際にこの５年間の事務事業評価の中で、いわゆる職員ではないですけれども、その辺を教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"ちょっと今、持ち合わせがございませんので、また正副委員長にご相談をさせていただいてという形をとらせていただきたいと思います。それと目標ですけれども、それぞれの事業を見直している中で、より適正な形で事務事業の見直しを図っていきたいと考えているところです。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"今、課長からありましたように、その辺の数字のことについては後ほど出してくださるということなんでしょうか。ぜひその辺の資料をお願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"渡辺委員","kind":"質問","question":"公有地活用のところで１点、伺います。そういう報告ができるケースがあるかどうかと、取得に対する行政の今のスタンス、考え方を教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"やはり今ある区有地の跡地活用だけでなく、例えば都有地とか、国有地といったものも必要になる場合もあるかと考えております。それら費用対効果も図りながら、これまでも検討してまいりましたし、そういう考え方を持って取り組んでいきたいと考えているところです。","id":"exchange-027"},{"speaker":"渡辺委員","kind":"確認","question":"今のお話だと、通り一遍に何か受け身なのかななんていう感じもしてしまったので、その辺の確認を再度お願いします。","respondent":"日下部企画部長","answer":"そういう１つの軸はありますので、できるだけ適切な対応、そういう形での働きかけ等も行っているケースもあります。進めてきている、できる限りこれは区民のニーズにはしっかりこたえていきたい、このような考えで臨んでいるところです。","id":"exchange-028"},{"speaker":"須藤委員","kind":"質問・要望","question":"そのあたりを教えていただきたいのと、それから評価基準が基本評価で３点あるんだけれども、そのあたりはどういうふうにやっているのか。そのあたりとの整合性とかというものをどういうふうに考えていらっしゃるかを説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"先ほどもご説明いたしましたが、今回は行政の内部評価として実施していきますが、次の段階として。そうしたものも含めまして、事務事業評価の中に取り入れまして、整合性を図っていきたいと考えているところです。","id":"exchange-029"},{"speaker":"金野委員","kind":"質問・要望","question":"必要性というところを教えていただきたいんですが、必要じゃないかという判断基準というんですか、そこら辺を説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"やはり私どもが事業をやるに当たっては、すべての事業について必要があるということでそれぞれの事業はスタートしています。年数がたった段階で、まずはそういう観点から、第一段階として必要性という評価の基準を設けまして評価をしていきたいと考えているところです。","id":"exchange-030"},{"speaker":"金野委員","kind":"質問","question":"そのときに応じて必要なもの、必ずそこに区民の皆さんが多からず少なからず必要とする事業であるということはあると思うんです。どう説明していいんでしょうか、これは意見ですけれども、お願いしたいなというところであります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"稲川委員","kind":"質問・要望","question":"確認でお願いしたいんですが、最大限に用地をうまく利用していくということはこれから求められるところなんですが、例えば公園１つ例にとってみても。全く物が建っていないわけですから、どういう視点での考え方なのか、それを１点。","respondent":"久保田行財政改革担当課長","answer":"私ども活用といった意味では２つの考え方を持っているところです。場合によっては、例えば定期借地権等をつけて民間に貸し出すとか、そういったものも跡地の有効な活用の手段の１つであると考えております。","id":"exchange-032"},{"speaker":"井上委員","kind":"質問","question":"それに伴う事業が廃止ということになった場合には、そこまで条例の廃止というようなことも視野に入れて検討していこうとしているんでしょうか。前回で途中で終わってしまった外部評価委員のこういうのも視野に入れて、今、検討していると理解をしていいのかどうかをお伺いします。","respondent":"久保田行財政改革担当課長","answer":"そういったもので、その事業がありませんから、条例等の廃止ということも視野に入れていかなければならないのかなと考えているところです。区が主体となって事務事業評価を実施してまいりますが、そうした中で…","id":"exchange-033"}]},{"id":"topic-03","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"もう１つだけ、ちょっとどこで言えばいいのかわからなかったので。そことの関係をどういう論議で進めて、どういうふうに論議していくのか、そこら辺の考え方がもしあればお聞かせ願えればと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問","question":"今、菊地委員がおっしゃった部分が、ここで委員長から議長あてにまとめが提出されましたよね。ですからそこが変わると、ちょっとその辺は正副委員長で調整していただいて、検討していただいたほうがいいんじゃないかと思うんですが。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"よろしくお願いしたいなと私としては思いますけれども、二次評価がいつなのかと、議論できるようにしていただきたいというのが１つ要望です。ニーズに照らしての必要数などもこの委員会で議論すべきだと思いますので、そういった議論ができるような資料の提示も含めてお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど資料の要望をしまして、主な区有施設というところで施設の有効活用に関することを検討するという内容の中で資料提供はしてほしいと求めましたので、よろしくご配慮をお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/438675?Template=document&Id=5884#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":33345,"voices":89}},{"id":"h22-20100603-15","meetingId":"h22-cm06","date":"2010年6月3日","dateIso":"2010-06-03","committee":"環境対策特別委員会","time":"午後１時０３分～午後２時２２分","status":"正式会議録","sourceType":"formal","overview":"環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"川西委員","kind":"質問","question":"１つだけ。勉強不足でちょっとお聞きしたいんですけれども、推進地区というものが２カ所書いてある、予算上は都の関係とかというのを手当しているんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"それが東京都の協議の末、許可がおりれば、そういう地域の中で規制緩和を受けられるということになります。区あるいは東京都のほうでこのことに対して予算をつけて何かをやるという事業ではございません。","id":"exchange-001"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、自発的に団体の方が申請の手続をするとして、区を経由して東京都に申請をするという手続になっているんですか。東京都に直接おやりになって、こういうところが推進地区になったよというふうに許可がおりてきてしまうのか、どっちか尋ねました。","respondent":"藤田水とみどりの課長","answer":"１年ぐらい前から協議会が立ち上がりまして、東京都が入った協議体を設けて、そこの中から発信しています。区のほうに話があって、東京都のほうに連携して働きかけた、そんなような経過になってあります。","id":"exchange-002"},{"speaker":"若林委員","kind":"質問","question":"１つだけ。里山再生なんですが、先日、早川町に崖崩れがありましたけれども、それとここの事業と関連があったのかどうか教えていただけますか。","respondent":"工藤環境課長","answer":"里山再生にかかわる崖崩れの件ですけれども、私どもも今、情報を入手しているところでございまして、詳細な部分はまだはっきりつかんでいない状況です。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"提案","question":"私は去年もこの委員会なものですから、当然これだけのものでは品川区は地域推進計画を達成できないわけですから、いろいろな計画を展開していくのか。私は何回も見ているわけですから、１度、あなたがどう提案しようがどうだと言われたこともありましたとの意見を述べました。","respondent":"工藤環境課長、太田品川区清掃事務所長","answer":"私のほうで５つ、環境経営支援事業の中でメニューをご説明したわけなんですけれども、２１ページの２番目の省エネ推進支援事業ということで。よりＣＯ２の削減に特化したような形で… これは区職員で実施をしていますけれども、平成２２年度の予算審議の中でもご説明をさせていただきましたけれども、非常勤職員を３名に増やしました。それから午後も１時から２時ということで、１時間ほど実施をさせていただいてありま…","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"そもそも品川区として地球温暖化対策やＣＯ２の削減等をそれぞれ進めている事業がどうかかわっているのか、そこの関係が、それぞれの説明の中で。ただＣＯ２を減らそうというのがどうも見えてこなかったんですけれども、その辺をご説明いただけますか。","respondent":"工藤環境課長","answer":"１つ目がすべての区民が行動する、２つ目がすべての事業者が行動する、そして取り組み方針の３つ目として、区民・事業者の取り組みを区は支援する。こちらのほうの取り組み方針の中に、事業概要で説明したそれぞれの施策といいますか…","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"ＣＯ２を減らすために、今までやっている事業、もちろん継続するものもあると思いますよ。推進計画もつくってさらに進めていこうというわけですから、どういう考え方を今、ご説明いただけますか尋ねました。","respondent":"工藤環境課長","answer":"そして、今後もこのままいけば家庭部門と業務部門に関しては上昇が見込まれるという統計値をとりました。例えば上乗せの補助をして、施策を加速するというのも１つですし、そういった部分を中心的に今後進めていくというのが区の考えです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＣＯ２をどう削減していくのか、またみどりをどう増やしていくのか、当然かかわってくる話だと思うんですね。逆にどこの部隊がチェックをするというのか、報告を求めるというのか、そういうのはどういう仕組みになっていらっしゃるんか尋ねました。","respondent":"工藤環境課長","answer":"温暖化対策に関しましては、当然庁内、オール品川で進めなければいけない事業だと考えています。区長を推進者の筆頭としまして、それぞれの事業部長がメンバーになっておりまして、そちらのほうで大きな方向性等を決めているところです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"推進会議で大きな方向性を決めているとおっしゃっているので、今、どういう報告がされているのか、どういうふうに会議が行われているのかわからないんですけれども、しっかりその報告は委員会にしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"川西委員","kind":"提案","question":"ですから、私どもがこの１年間にどうやって環境対策をより前へ進めるお手伝いができるかというのがこの委員会だと思うんです。ですから、そういうふうに積極的にいきたいと思うんですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"意見","question":"現状を明らかにした上で、大いに委員同士で意見を交わしながら一致点を探していけたらなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"阿部委員","kind":"質問","question":"委員である私たちが考えるべきことだと思うんですけれども、最初のご説明の中で本当にたくさんこの委員会の中で扱うべき項目が出てきました。ある程度重点的にやっていきながら、ほかのことも適宜ということなのか、その辺は何かお考えがありますか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問・要望","question":"区側としても適正というんでしょうかね、継承していっていただきたいなと考えますけれども、その点が１点です。このようなことに積極的にかかわっていっていただくような指導性をぜひとも持っていっていただきたいなということ、要望しておきます。","respondent":"工藤環境課長、福島ものづくり・経営支援課長","answer":"考え方としまして、ＩＳＯの１４００１を取っているということと、環境報告書の公表を実施しているというのが１つの大きな要件です。そちらのほうに該当しているということであれば、私どものほうから積極的に働きかけて… 助成を行いました今年の２社、取っていなくてもそういった形で環境問題に今後取り組んでいこうという意欲がある会社だと考えています。そういった企業に対して支援をしているというふうにご理解いただければと思います。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"この２５％の削減というのは難しいと思いますので、ぜひともそういう連携をこれから密にとっていっていただきたいなと思います。私どももしっかりと勉強しながら、少しでも環境対策に取り組めるようにしっかりやっていきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"品川区のＣＯ２の現状であるとか、これからの委員会運営の中では有効性があると思われますので、要望しておきます。これから１０回程度の中で、環境というのは非常に大きなテーマですから、議会から提案するにしたとしてもとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"阿部委員","kind":"意見","question":"この平場の中では、今さらもう１回そもそも区はどうなのだというところから始まるのではなくて。もう１点は、近隣の自治体の中でいろいろ先進的なことをされているところもあると思いますけれども、そういったところは視察をしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"意見","question":"３つの調査事項概要ということですけれども、どういう工夫が必要なのか、そんな委員会運営ができたらなと思います。それが最終的にどういう形になってリサイクルとなっているのか、収集されたごみがどうなっているのか、との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"ですから、これを少し入れていただければ理解も深まるのかなと思うので、この点はぜひともお願いしたいなと思います。重複をしているというんでしょうか、あと区のやっているものに対します整合性とか、そこら辺の答えも出してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"川西委員","kind":"質問・要望","question":"事業者の協力を、参加を求めて項目がありますね、どんな中にも。ですから、事業者をどうやってもっと拡大して、いっぱいある中で何を取り上げていくか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"大沢委員","kind":"質問","question":"そこのところで注釈というか、ここまでお願いしていいものかどうかわからないんですが、新しい分野ですよね、この環境というものは。ですから、また注釈なり箇条書きなりしていただければ、より理解も進むのではなかろうかなと思うんですが。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270609?Template=document&Id=6188#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=15&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":24097,"voices":78}},{"id":"h22-20100628-6","meetingId":"h22-cm06","date":"2010年6月28日","dateIso":"2010-06-28","committee":"区民委員会","time":"午前１０時０２分～午後０時４３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"第５７議案、品川区立区民活動交流施設条例","agenda":"第５７議案、品川区立区民活動交流施設条例","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"何点かお聞きしたいんですが、まず１点目は、駐車場はどのような形になっているか。ＮＰＯ法人であってもやっぱり法人ですから、ちょっとその辺の問題がわかったら教えていただきたいなと思いますけれども、３点。","respondent":"堀越文化スポーツ振興課長、秋山協働・国際担当課長","answer":"ちょっとグラウンドの、ちょっと説明できなかったんですが、Ａ３資料の１ページの第１多目的室の前あたりに駐輪場を設置する予定でおりますので。できるだけご利用いただきたいなと思っているんですが… セキュリティの部分について私のほうからお答えします。２階の旧スチューデントシティーのところの活動拠点室ですけれども、新しい仕事という意味で、交流スペース等も使っていただきたいと考えております。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"隣同士との交流というのはわかるんですけれども、あそこがあいていることによってのセキュリティというのは、確保はされていないわけじゃないですか。２部屋があって、これは要望で終わりますが、ぜひそういった部分でしっかりとセキュリティを確保していただければなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"山内委員","kind":"確認","question":"美術工芸室等と出ていますけれども、そういうものをどんな形で精査をして、それでここまでこぎつけたのかということを１つ伺います。これも確認なんですけれども、これは自主財源で行っているのかということ、まずこの２点をお伺いします。","respondent":"堀越文化スポーツ振興課長","answer":"パブリックコメントを実施しておりまして、この基本的な考え方、こういうのは八潮の地域外からも人を呼び込むようなという観点もあります。パブリックコメントも実施をしておりまして…","id":"exchange-003"},{"speaker":"山内委員","kind":"質問","question":"いろいろ周知活動にも努めていくと思うんですけれども、その辺の利用率についてをどのようにまず考えているのかということをお伺いさせてください。もちろんこれは行革という意味では大事なことだと思うんですけれども、そういった声をどのように今後考えていくのかということを伺いたいと思います。","respondent":"堀越文化スポーツ振興課長","answer":"これはパソコンを今２０台ぐらい設置して、お貸ししてお使いいただくという予定をしています。それぞれ地域ごとにお声を聞きながら整備を進めておりますし、区全体の考えはありますが、前向きに検討していきたいなと思っているところです。","id":"exchange-004"},{"speaker":"山内委員","kind":"確認","question":"その辺、大変重要なところなのかと思っていますので、そのバランスというところを伺いたかったというところもあって質問させていただきました。それはどうなるんか尋ねました。","respondent":"堀越文化スポーツ振興課長","answer":"地域センターはそのままです。新たな施設として今回区民活動交流センターがオープンするものです。","id":"exchange-005"},{"speaker":"山路委員","kind":"質問・要望","question":"あの狭さで１万円ではちょっと高いんじゃないかという気がしたんですけれども、その辺の整合性はどうなんでしょうか。そういう関係でこういうのもできるかどうか、その３点について。","respondent":"堀越文化スポーツ振興課長、秋山協働・国際担当課長","answer":"軽食コーナー的な部分ではなかったということで、これは改めて設備を軽食コーナーのところに設置したという形になっております。区のほうもいろいろな意味で、てこ入れというわけではありませんけれども… 他区のいろいろな施設等もありますけれども、そこと比べて比較的金額の割には広いということで、こちらのほうを考えております。教室の半分ですので、約３２m2ぐらいありますので…","id":"exchange-006"},{"speaker":"山路委員","kind":"意見","question":"ＮＰＯ団体は品川全体のいろいろ協働をやっていただく方ですよね。そうすると、あの部屋で１万円というのは高いような気がするんですけれども、その辺は妥当だという判断で今回設定されたわけですねとの意見を述べました。","respondent":"秋山協働・国際担当課長","answer":"１万円という算出につきましては、近隣の施設等を考えた上で、あの広さ等を考えて１万円というのを算出しまして、この程度が妥当であると判断したです。","id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"もう１点のパソコン講習室というのは、高齢者の方でも今までやったことがあるとか、やっているとか、こういう方を対象にしている。ですので、全くパソコンにさわったことのない人を集めて教えて、覚えたらあとは自由に、そういうのをこしらえたらどうですかという意味なんですが。","respondent":"堀越文化スポーツ振興課長","answer":"高齢者の方を中心にパソコン講習という形で講座を区のほうで実施していますので、そのような面も含めてやっていきたいと思います。１回慣れると、そういった部分での活用等も含めて、積極的に研究したいと思います。","id":"exchange-008"},{"speaker":"山路委員","kind":"質問・要望","question":"いろいろお聞きしましたけれども、高齢化率が高くて若い人が少ない。それを前提として、品川全体の方が活用できるような施設を要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問・要望","question":"２つ目が空調の関係の確認で、今日はもちろん季節柄工事中で非常にあれでしたが、ほぼ各部屋、廊下も含めて完備されるのかどうか、空調について。３つ目が、シャワー室というのが要望として多いと思うんですが、この活用を伺いたい。","respondent":"堀越文化スポーツ振興課長","answer":"ダンスにつきましては、地域交流室が１階のところにございまして、そちらのほうをダンスにもご利用いただくという想定で考えております。それから屋外トイレにつきましては、こちらの部分についてはトイレ改修の予定はございません。","id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問・要望","question":"疑問を持たれないのかなと思いますので、今現在はともかくとして、今後の可能性なんかを伺いたいと思います。アスレチック広場というのは、どういう方を想定しているのかなと思いまして、お伺いします。","respondent":"堀越文化スポーツ振興課長","answer":"９時半までやっていますので、１回入っていただいて、中のトイレのほうをご利用いただきたいと考えているところです。健康増進の部屋もございまして、介護予防を行いましたり、そういったところを使った事業についても展開していきたいと考えております。","id":"exchange-011"},{"speaker":"菊地副委員長","kind":"質問","question":"ですから、その５年という設定の考え方の基本を教えてもらいたいんです。それからもう１つ、先ほど委託で管理をしていくということだったんですけれども、指定管理という方式になるんでしょうかね。","respondent":"堀越文化スポーツ振興課長、秋山協働・国際担当課長","answer":"多機能ですので、一定程度区が関与しながら、民間のノウハウを生かしながら管理をしていく必要があると考えております。まだそこまでの組織的な対応は不可能であるという形で、そういう予定で今、準備を進めているところです。 最長５年ですけれども、基本的な考え方としましては、そういうところを審査の基準として選定をしていきたいなと。５年たった後どうなるかということですけれども、５年後はもう一度新たに…","id":"exchange-012"},{"speaker":"菊地副委員長","kind":"質問","question":"そうすると、施設規模はもちろんいろいろ違いがあるんだろうけれども、そういうのを展開していくということではないんですか。先ほどの話だと、ほかの地域には文化センターがあるのでという話だったんだけれども、ちょっとそこだけ最後に。","respondent":"宮地地域振興事業部長","answer":"八潮が１号になるかもしれませんし、これで終わるかもしれませんが、可能性としてはまだまだ２号店、３号店とできる可能性も秘めているわけですね。トータルの創業支援センターができて…","id":"exchange-013"}]},{"id":"topic-02","title":"お昼ではありますが、このまま続けます。請願・陳情審査に入ります。平成２２年度陳情第１１号、指定喫煙所に関する陳情","agenda":"お昼ではありますが、このまま続けます。請願・陳情審査に入ります。平成２２年度陳情第１１号、指定喫煙所に関する陳情","exchanges":[{"speaker":"菊地副委員長","kind":"質問","question":"今、大井町駅周辺にあそこを含めて３カ所喫煙場所がありますけれども、撤去をするということはいかがなものでしょうかね。あそこで吸っているわけですから、子どもたちの受動喫煙というのは当然あり得るわけですから、その辺の考え方をお尋ねしたいと思います。","respondent":"矢部生活安全担当課長","answer":"去年、１カ所、大井町の東口のデッキ上の喫煙所につきましては、それは歩道からちょっと離れる処置ができたので、そこは移設をしたところであります。現在３カ所の喫煙所は最低のラインと考えており、今のところは撤去はせずに、何らかの形で対応を検討していきたいと考えていま…","id":"exchange-014"},{"speaker":"菊地副委員長","kind":"質問","question":"移動もできないし、ボックスをつくることもできませんよという話ですから、何らかの形というのはあり得ないんだと思うんですよね。だから今の何らかのというのはなかなか考えづらいんだけれども、もし本当に何らかのがあるのであれば、具体的に聞かせていただけますか。","respondent":"矢部生活安全担当課長","answer":"何らかの形で検討したいというのは、移設する場所もないということで、根本的な解決には当然ならないと思っています。今年度、さまざまな形でマナーアップということを図って、なるべく歩道寄りでは吸わないようにということで指導していきたいと考えています。","id":"exchange-015"},{"speaker":"菊地副委員長","kind":"質問","question":"この方の陳情そのものが今、世界中で騒がれている健康の問題ですから、やっぱり私はしっかりとした対処をすべき場所なのではないかと思うんですね。もっと大きな非難を浴びるということになっていくわけですから、もう一度考えてみる余地がないのかどうか、そこをちょっと。","respondent":"宮地地域振興事業部長","answer":"ポイ捨て禁止という観点から考えれば、駅周辺には３から４基は置くという方針のもとでやってきましたので、なかなかいい知恵がないのも事実です。キャンペーンをしながら、マナーを守っていただくという使命を全うさせていただきたいと思いますので、よろしくお願いいたします。","id":"exchange-016"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"最後は意見・要望なんですが、陳情そのものは私は採択すべき中身だと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"渡辺委員","kind":"意見","question":"先ほどの答弁にもありますし、ごくごく最近、もう対応がなされているというふうにとれました。そういう意味で、この陳情に対しては、自民党としては、趣旨採択とということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"山路委員","kind":"意見","question":"陳情者の意見はよくわかるんですけれども、区もそれに対してもずっと長年やってこられた。そういう両面を考えると、陳情者の趣旨を生かして趣旨採択、そういう気持ちですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"菊地副委員長","kind":"意見","question":"私はポイ捨ての問題以前に、やはり副流煙の問題というのがあの場所では一番大きなものだと思います。採択と先ほど言ったんですが、趣旨採択のご意見が多いようですので、趣旨採択ということでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"吸う人も法律で許されている範囲で吸っているわけですから、その中でポイ捨てとかも問題となっている中で、ある一定のルールが必要なのかなと。つい最近も区民の要望をいただいて移動したという経緯もあるので、公共の場で喫煙というのは考えているので、趣旨採択で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"高橋委員","kind":"質問・要望","question":"趣旨採択で。マナーアップ指導を徹底してやっていただきたいということと、もう１つは、その辺のことも検討していただければありがたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/397696?Template=document&Id=2582#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":26035,"voices":81}},{"id":"h22-20100628-7","meetingId":"h22-cm06","date":"2010年6月28日","dateIso":"2010-06-28","committee":"厚生委員会","time":"午前１０時０１分～午後３時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を95件整理しています。","topics":[{"id":"topic-01","title":"第５２号議案、平成２２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第５２号議案、平成２２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"南委員","kind":"質問","question":"その辺でのご認識を伺いたい。それから、人材が厳しいという点で、短期雇用で果たしていいのかどうか、その辺の見解も、ちょっと伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"平成２１年度以降、介護報酬自体も３％上がってきたというところで、改善はされつつあると理解をしております。あわせて、介護現場での看護技術の力量をアップしていただくという趣旨で、臨時的に雇用創出事業ということで対象になっているところです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっとその辺を、品川区内に何施設かある中で、もし具体的な事実があれば教えてほしいと求めました。それが施設の側に恒常的に反映できる条件があるかどうかという、どういうふうに見ておられるのか、ちょっと伺います。","respondent":"冨岡高齢者福祉課長","answer":"介護報酬が第４期に改定になったということプラス、介護職員処遇改善交付金という制度が新たにできました、１万５,０００円と言われておりますが。今後に向けてのこういうきっかけづくりみたいなことで、いろいろな状況を加味しながら…","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"リアルな数字でなくていいんですけれども、報告がないことはないと思うので、そういうところも具体的な数字として教えていただきたい。そうなんですかと、そこの辺の確認をしたいと思いますので、具体的な数字で示してほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"手元にちょっと資料が出ておりませんけれども、特に区内の５法人については結果が出ておりますので、また調べてご報告をします。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"この審査をするにあたって、そこが大きなポイントになってくるのではないかと認識しておりますので、ぜひ、具体的な数字を教えていただきたい。ほかの方の質問の最後でもいいですので、ぜひ、そういうふうに計らってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区として主体的に、何かお考えになったものがあるのか、そこを説明ほしいと求めました。どういう状況を目指しているのか、改善値といいますか、そこをご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"次の有資格未就業者の人材活用検討経費ですが、考えておりますのは、例えば介護福祉専門学校を卒業された方も５００人以上おいでになるわけです。そういう方たちに、再びの研修を含めながら新たにもう一度就業していただくための方向をつくっていきたい…","id":"exchange-005"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区立の部分は４月からやったけれども、４月からやりたかったけれどもできなかったので、補助金があったのでやったというご説明なのでしょうか。必要であるならば、当初予算になぜ組まなかったのか、なぜ４月から実施できなかったのか、そこをご説明ほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"区立についてはもう実施が始まっておりまして、有効であるということを確認していますので、あわせて民設のほうにも広げていったという内容です。どちらにつなげていくかという形はこれからつくっていく…","id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"いろいろ施設の方のお話を伺うと、なかなか十分に教わり切れないという話もよく伺うので、区の考えを教えていただきたい。この事業がそれをどう支えていくといいますか、そういう事業として位置づいているのか、そこをご説明いただけますか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"課題はあるかなと思いますが、少なくともそういう大きな枠で進めているということで、対応していただければと思っているところです。私どももちゃんと認識しているところでありまして、こういう事業を考えているわけでございまして、十分に認識しています。","id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それから、人材確保については、認識しているというお話ですけれども、先ほど伺った、人材不足の最大の原因をどう考えているのか。３対１から２対１への改善、そしてその対応策をどう考えているのか、最後にご説明いただけますか尋ねました。","respondent":"木下健康福祉事業部長","answer":"３０％ぐらいのところもありまして、自分がここで１０年働いたらどうなるのかというような見通しが立つこととか、ここの背景にあると考えています。幅広く言えば人事管理の問題等、そういうところを、適切に仕組みをつくり運用していくことが肝要かと考えています。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問・要望","question":"それとも、１,０８０万円というのは、ある程度使用目途が特定されているのか。そこら辺、どのような使い方をされるのか、おわかりになりましたら説明ほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"見積もりの関係ですけれども、人件費は４０万円でお２人という形で考えております。事務費ということで考えておりまして、民間の特別養護老人ホームと老人保健施設が１カ所、計５カ所という形で考えているところです。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"先ほど、中塚副委員長の質問のご答弁で、私が伺いたかったことの概要が示されましたので、それはそれで承ったとしたいと思います。ちょっとしつこく質問させていただいたんですけれども、ぜひその辺のご答弁の改善を、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"三上委員","kind":"質問・要望","question":"ちょっと聞かせていただきたいのは、主に看護職ととらえていいんですか、介護も含むんですか。この人件費４０万円×２人という算出根拠になるんでしょうか、主に看護職員ということで受けとめていいのか、どうか。","respondent":"冨岡高齢者福祉課長","answer":"原則は看護師だと聞いております。","id":"exchange-011"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、部課長会でもしっかりと、そういう意見は述べていってほしいと求めました。福祉法人の事情によってやめますなんていうことにはならないようにしていただきたいと、要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"大変さが復活してしまうということですから、当委員会としても、きちんとそういう意見を伝えていくということが大事なのではないかなと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"南委員","kind":"提案","question":"提案理由は、委員長もおっしゃいましたけれども、先だっての本会議のときに申し上げました。３回目になるわけですけれども、条例提案を、していきたいということで提案いたしましたとの意見を述べました。","respondent":"鈴木委員長","answer":"議案提出者を代表して、南委員からの説明が終りました。ただいまの説明に対しまして、ご質疑等ございましたら、ご発言を願います。","id":"exchange-014"},{"speaker":"大沢委員","kind":"質問・要望","question":"それから、これも以前にも出た質問かもしれませんけれども、１万円にするということの根拠。先ほどもちょっとお話を伺いましたけれども、そこを改めて、なぜ施行日を早くさかのぼらせたのかという説明をほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"南委員","kind":"提案","question":"なかなかそこまでいっていないというの実態のようですから、そのこともあわせて、そのことをあえてご紹介したいと思います。前回の提案のときは、提案した時期によって、１日も早く実施したいという思いで１２月１日にしたんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"大沢委員","kind":"意見","question":"７５歳以上の方のすべてという形で、今、南委員は答弁をされていました。ちょっと私には納得ができない部分があるんですけれども、そこら辺のところは、どういうふうにお考えになりますかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱりそれなりにきちんとあるわけですから、財政状況がどうか、そういう意味で平等でこういう制度を活用していただきたいという思いです。私どもの公平性と、その年齢に到達した方々にすべて等しくというふうに、そういう意味の公平性ということで考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"山元委員","kind":"質問・要望","question":"公平さというんですか、そういうのはどういうふうにお考えなのか、教えていただきたいと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"南委員","kind":"提案","question":"私どもの今回の条例の提案は、介護を受けている方は対象の範囲にしておりませんので、そういう点で区分けをしたところです。当然支給をしていく対象になっていくということですから、ぜひ、そういうことでのご理解をほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"三上委員","kind":"提案","question":"一つ、先ほど、提案者が自分で答えられなかった、基金の積み増しをしているということについて、それについて、現状はどうなっているのか。１年間これだけ使ったと、提案者の言葉の中に、それはちょっと疑義が生じてくるということだと思うんですよとの意見を述べました。","respondent":"木下健康福祉事業部長","answer":"必要があって基金として設置しておりまして、政策的な必要のために準備をし、必要なときに取り崩しをしているです。","id":"exchange-021"},{"speaker":"三上委員","kind":"提案","question":"３回目だから、これでもうわかっているんでしょうみたいな提案の仕方となってくると、これはちょっとあまりにもお粗末過ぎる。ちょっと私の思いのほうが先にずっと出た質問になってあれですけれども、説明してもらえるのであれば、説明していただきたいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"南委員","kind":"提案","question":"条例が提案されれば、条例の提案をしていくということで、一つはそういうことがあります。早く健康を取り戻していただきたいという期待を示していく、そして、３回にわたって提案をしているものでありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"三上委員","kind":"意見","question":"冒頭、財源的な部分で、基金のことで、何がどうなのかさっぱりわからないので、何を言われたのか、理事者のほうでちょっと通訳できたらしてもらいたいんですけれどもとの意見を述べました。","respondent":"木下健康福祉事業部長","answer":"それぞれに目的がありまして、必要なときに取り崩すわけでありますから、それをもって財源があるということにはならないと思います。一般的なルールとしては、そういうやり方になっているということは、そのとおりかと思います。","id":"exchange-024"},{"speaker":"三上委員","kind":"質問","question":"皆さんどうでしょうかと、してあげたいんですという思いというのは、全く通じてきませんよ。そういう話の中で、自分がはじめに説明をしなかったことを指摘されて、自分が答弁したことを考えてみればいいではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それが進んでいる中で、今回、高齢者の入院時に限っての話ですけれども、あえて所得制限をつけるというのは、どういう理由なのかと思うんです。大沢委員に伺いたいんですけれども、世代間の公平性というのはどういう意味なのか、ちょっと教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"すべての対象になる７５歳以上の高齢者の方々の経済状況がどういう状況にあっても、つけるべきではないと、私どもは考えているところです。一日でも早く健康を取り戻してくださいというところの支援ですから、先ほどもそういうふうに申し上げたんですけれども、同じだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"中塚副委員長","kind":"提案","question":"今回の提案は、年度内ですから、その積み増し分を削るということなので、先ほどの健康福祉事業部長のご指摘は当たらないと思います。大沢委員に伺いたかったのは、そこをご説明ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区民の実態を聞いているだけです。議案審査に関して、区に資料、意見を求めるのは…。","respondent":"山田副区長","answer":"いわゆるこの支援金というとらえ方が、これは７５歳以上ですから、一体どういう形を設計されているのかよくわからないというのが実感です。そこにまた新たに区単独でやれるかどうかというものになりますので、これも当然、検討を要するということが実情です。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"自分の質問の思いの中で、理事者のほうに質問するということだってできるわけで、そこを制限するということにはならないのではないかと思います。私は、できるだけ答弁するつもりで臨んでおりますが、そのことだけ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"中塚副委員長","kind":"提案","question":"議員提案であるから、必要な資料について、区から説明が求められないという委員会運営はおかしいと、私は思います。伺ったのは、今の区民の実態についてお伺いしたわけで、ご説明ほしいと求めました。","respondent":"本城国保医療年金課長","answer":"後期高齢者医療制度が始まって以来、平成２０年度の集計によりますと、入院患者一人当たり３万５,５００円ほどの負担額となっているところです。年金の受給額が、区内で平均どれぐらいかということについては、私ども資料を持っておりませんので、お答えできないところです。","id":"exchange-031"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"南委員に伺いたいんですけれども、実際に入院した際に、何がどれぐらいかかってくるのか、ご説明いただきたい。要するに、入院時の区民の負担の実態、そこをご説明いただけますか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"その辺のご事情については、それぞれの委員が地元のさまざまなご相談の中で伺っている部分があると思いますので、そういう実態があるということです。入院した際の費用と、負担というところについては、そういう状況だということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"中塚副委員長","kind":"提案","question":"改めて、品川区に伺いたいんですけれども、入院にかかるときの負担が、何がどのようなものがあるのか、もう一度伺いたいと思います。これが最後ですので一括して言いますけれども、改めて、南委員から、今回の条例の提案の理由をもう一度、ご説明ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"南委員","kind":"提案","question":"提案理由ということなんですけれども、先ほど紹介したように、４０日間の入院で１４万円余、プラス紙おむつ等々の日用生活品費。元気で長生きをしていただきたいという思いの中で、かかった費用の一部でも負担できるようにという思いで、今回の条例を提案したものですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"中塚副委員長","kind":"提案","question":"提案者からありましたけれども、２３区の中でも、入院時にかかる日用品についての軽減策を打ち出しているわけです。私は、軽減策は、品川区もしっかり考えるべきではないかと思うんですけれども、いかがか尋ねました。","respondent":"本城国保医療年金課長","answer":"前段でもご説明させていただいたところでございまして、そのようなことで仕組まれておりますので、それで対応するのが基本だと考えているところです。検討の柱となっているところですので、それを踏まえながら考えていきたい、それを見守っていきたいと考えているところです。","id":"exchange-036"},{"speaker":"三上委員","kind":"確認","question":"要するに収入という形になってきたときに、これに対する税法上の扱いというのは、どういうふうに確認してきているのか。どうなんですか、それはどういう形でクリアされているのか、ちょっとお伺いしておきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"南委員","kind":"提案","question":"この制度を１日も早く実現させたい、そういう思いですから、そういうふうに理解をしてほしいと求めました。三上委員は、その辺はどういうふうに思われるのか、改めて、私のほうで伺いたいと思いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"三上委員","kind":"質問","question":"聞いているわけですから、そちらのほうが答えるべきであって、それだけでとめておけばいい話です。それはやっぱり、出す前にきちっと勉強しておく必要がある話です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"南委員","kind":"意見","question":"どの基金でどういうふうに流用するのかというのは、政治姿勢の問題だと、私は思っております。財政的には決して厳しい状況ではない、十分にやっていける状況だということを、あえて申し上げたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"三上委員","kind":"提案","question":"私どもは、今、国に対して高額医療制度の見直しということについて提案しております。国の制度としてそういうことができないかどうかということを、私どもは提案しておりますので、こういった形で考えていきたいと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"中塚副委員長","kind":"提案","question":"公平性を理由にするのであれば、どういうことをおっしゃりたいのか、ぜひ教えてほしいと求めました。日用品費の負担軽減にはつながらないわけですから、今回の提案は、ぜひご賛同ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"稲川委員","kind":"質問","question":"先ほどからさまざまな意見をお伺いしてきました。公平というのがアリバイ的に使われているような気が非常にしていまして、私としても、賛同しかねます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"}]},{"id":"topic-02","title":"平成２２年請願第９号、子宮頸がんから女性を守ることを求める請願および(2)平成２２年請願第１０号、子宮頸がん予防ワクチン接種の公費助成を求める請願","agenda":"平成２２年請願第９号、子宮頸がんから女性を守ることを求める請願および(2)平成２２年請願第１０号、子宮頸がん予防ワクチン接種の公費助成を求める請願","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"ただいま、説明いただきましたが、２２医療機関で行っているということです。今、そこの組織変更後の対応方、十分にできる態勢なのかどうか、教えてほしいと求めました。","respondent":"山岡健康課長","answer":"医療機関のほうは、私どもは医師会と契約して、医師会の中の合計で２２医療機関で受けることができるという形にさせていただいているところです。ご案内、啓発等は、現在のところは、すべて私どものほうで直接行っているところです。","id":"exchange-044"},{"speaker":"稲川委員","kind":"質問・要望","question":"１点、勉強させていただきたいんですが、子宮頸がんのワクチンを接種するまでの流れはどうなっているのか、お伺いしたいんです。どういう流れでワクチン接種までいくのか、ちょっと知りたいんです。","respondent":"吉田保健予防課長","answer":"２０歳以降ですと、ワクチンを医療機関でお打ちいただくということに、今はなっているところです。ですから、ご希望の方は、医療機関でご説明を受け、納得された上で注射を打っていただくといった流れです。","id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"品川区としては、どういうふうに考えられるのか、ちょっとその辺を伺いたいと思います。品川区がとられている対応、現状がどういうふうになっているのか、ちょっと教えてほしいと求めました。","respondent":"吉田保健予防課長","answer":"金額につきましては、やはり１万円代の後半ぐらいが、多くの医療機関でお支払いいただいている１回の金額ではないかと思われます。品川区としてもホームページ等を活用して啓発に努めてまいりたいと考えていますが、所管ではございませんので、これはお答えが難しいところです。","id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"その辺の見解についても、伺いたいと思います。その辺の認識をどういうふうに持っておられるのか伺いたかったので、あえてまた再度、その点も質問させてほしいと求めました。","respondent":"吉田保健予防課長","answer":"その２種類でカバーされる部分がやや低く、６０％弱ぐらいだと言われておりますので、これまでどおり変わらないと考えております。連携させていただいて啓発等も行っておりますので、こちらにつきましても、連携は必要だろうと考えています。","id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"まだ２４％どまりということで、これからの経緯を見守って、こういう状況をどういうふうに見るかということだと思うんです。とりわけ求められる病気への対策だと思うので、ぜひ広げていただきたいというところで、ちょっと再度伺いたいと思います。","respondent":"山岡健康課長","answer":"これは最大の啓発だと考えていますけれども、まずないがしろにしてほしくないと、私のほうからは申し上げておきたいと思います。どうぞよろしくお願いします。","id":"exchange-048"},{"speaker":"山元委員","kind":"質問・要望","question":"その辺、この質問が合うかどうかわかりませんが、医療のほうの薬品会社というんですか、一つが１万何千円もするというのは、何とか安くならないのか。ちょっと質問が合うかどうかわかりませんが、教えていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"山岡健康課長、吉田保健予防課長","answer":"それから、昨年度は、がん検診の特集記事を、１１月と２月にそれぞれ１ページほど使って掲載しています。ワクチンについては、保健予防課長から。 ただ、第１回定例会でもご答弁申し上げたように、今後は、性感染症対策としての啓発という部分は進めてまいりたいと思っています。これについては、直接、私どもが言うことはかなり難しい状況にあります。","id":"exchange-049"},{"speaker":"山元委員","kind":"質問","question":"実際に、私自身もそうなんですが、娘を２人持っています。啓発運動ができるのではないかと考えていますが、その辺は、いかがか尋ねました。","respondent":"山岡健康課長","answer":"これからの課題として研究します。","id":"exchange-050"},{"speaker":"山元委員","kind":"質問・要望","question":"男性の病院よりは女性のほうがいいなという思いがあるものですから、やはり対象年齢、もっと足が運ばれるのではないかと思います。女性の医師というのは、何カ所ぐらいあるのか、ちょっと教えていただけますか。","respondent":"山岡健康課長","answer":"さっき申し上げた、２２の医療機関ということなんですけれども、ほぼ産婦人科を標榜している医療機関です。ちょっと男の立場ですので、どこまで言えるのかわかりませんけれども、常に標榜してやっていらっしゃいますので、特に問題はないと考えております。","id":"exchange-051"},{"speaker":"山元委員","kind":"質問・要望","question":"いずれにいたしましても、やはり防げるがんということでありますので、その辺をよくよく考えてほしいと求めましたので、どうか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"思春期を迎える子どもたちですから、双方だと思いますけれども、やっぱり学校との連携をしっかりやっていく必要があると思うんです。現状についてどうなっているのか、今後の方向性についても、あわせてご説明いただけますか尋ねました。","respondent":"吉田保健予防課長","answer":"５月の検討内容についてですが、あまり詳しい情報は、国からも我々のところにおりて参っておりません。ただ、政府与党が、実際に公費助成について検討を始めるということが、情報としてはあるところです。","id":"exchange-053"},{"speaker":"中塚副委員長","kind":"質問","question":"保健の先生なのかとは思いますけれども、そこでの保健所や健康課との連携というのは欠かせないのではないかと思うんです。今後、ぜひしっかりやるべきだと思うんですけれども、方向性についてご説明いただけますか尋ねました。","respondent":"吉田保健予防課長","answer":"情報という点でも今持っていないところですし、我々としては、なかなかお答えできない部分です。今後、これまで以上に連携をしていく必要はあると考えていますので、お互いに情報交換を進めながら対応してまいりたいと考えています。","id":"exchange-054"},{"speaker":"中塚副委員長","kind":"質問","question":"保健所として連携するわけですから、どういう問題意識で連携をしていくのか、そこの方向性を伺っているんです。なぜならば、あとは保健所としての役割もあるわけですから、現状と方向性について伺いたいと思います。","respondent":"吉田保健予防課長","answer":"ワクチンの内容につきましては、我々としては、接種が可能ということで、学校だけではなく、いろいろな媒体を使って周知はしていく予定です。連携の方向性といたしましては、学校保健委員会等を通じて意見交換をしながら進めていくということを考えております。","id":"exchange-055"},{"speaker":"三上委員","kind":"質問・要望","question":"最近になってから、予算特別委員会か決算特別委員会の中でのやりとりでも伺ったら、結果的には１５年ぐらいとかいうお話もあったりした。ワクチンそのものが始まったばかりですから、どのぐらいどうなのかということは、これは努力してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"大沢委員","kind":"質問・要望","question":"今回の本会議の中でも、我が党の質問より、区側の積極的な意見、前向きな答弁をいただきました。よって、これについては採択をしていただきたいと、自民党は考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"山元委員","kind":"質問・要望","question":"公明党といたしましても、結論としては採択をお願いしたいということで、ぜひとも認めいただきたいことがたくさんありますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"大沢委員","kind":"意見","question":"その整合性を考えますと、無料ということに関しては、まだ時期尚早、制度等を考えるべきであって、無料ということはまだ順番が違うと考えます。よって、これに関しては趣旨採択ということで、お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"山元委員","kind":"質問・要望","question":"今、大沢委員がおっしゃったように、我が公明党も、やはり無料ということに対して、もう一歩踏み出すことができません。次の、国に向けて子宮頸がん予防ワクチン接種に助成を行うよう要望というのは、やはり私たちも趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"南委員","kind":"意見","question":"私は、採択をするべきだと主張しますけれども、しかし、趣旨というところで、意を酌むということでまとまるのであれば、別に否定はしませんので、賛成、採択をしていきたいと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"稲川委員","kind":"意見","question":"請願項目に無料という言葉が入っておりまして、私も、その無料を議論する前に、まずは制度をしっかり確立をして、子宮頸がんというものはどういうものなのか、しっかりと啓発をしていくのが先だと思いますので、趣旨採択ということでお願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"}]},{"id":"topic-03","title":"平成２２年請願第１２号、「後期高齢者医療制度廃止法案」を即時に提出し、老人保健制度に戻す請願","agenda":"平成２２年請願第１２号、「後期高齢者医療制度廃止法案」を即時に提出し、老人保健制度に戻す請願","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"法律をつくることは無理なわけでして、ここの表現が正しいのかどうか、ちょっと教えていただきたい。","respondent":"本城国保医療年金課長","answer":"今、委員、お話がございましたように、正式には法律ですので、国が国会で行うということでございまして、区自体が提案ということは、その意味では正確ではないと思います。","id":"exchange-063"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、医療が大幅に制限されるという、そこのところがどういうふうになってきているのか、一つ知りたいところです。今、品川区はどのような状況になっているのか、まずその辺から伺いたいと思います。","respondent":"本城国保医療年金課長","answer":"それに対する政策的対応もありまして、窓口等の対応において見る範囲では、現場では感じているところです。後期高齢者医療制度であっても、国民健康保険であっても、基本的には同じような医療内容を受給できるという仕組みになっているところです。","id":"exchange-064"},{"speaker":"南委員","kind":"質問・要望","question":"２％の方々は、３万人の２％ですから２００人ぐらいですか、そのぐらいの方々が保険料がなかなか払えない状況にあるのかなと理解するんです。そういう状況をどう見るかということも、ちょっと認識として、伺いたいと思います。","respondent":"本城国保医療年金課長","answer":"９８％強ということになっていまして、それ以外に、まだお納めいただいていない方もいらっしゃるのは事実です。ご事情に応じた分納で対応させていただいたり、窓口を通じて、きめ細かくご本人の状況を見させていただいている状況です。","id":"exchange-065"},{"speaker":"南委員","kind":"質問・要望","question":"私の理解が不正確だったら教えていただきたいんですけれども、国民健康保険と同様というのはどういうことなのか、ちょっと正確に知りたいと思います。それはそれで短期証発行とは別にして相談態勢をとるべきだと思っているんですけれども、どういうふうに考えているのか、その辺を伺いたいと思います。","respondent":"本城国保医療年金課長","answer":"９８％以上ご納付いただいているわけですので、かなり絞った上で行う予定として、考えているところです。終末期医療の関係だったり、基本的には、若い世代である国民健康保険の医療制度と同等の内容の診療報酬体系になっていると認識しております。","id":"exchange-066"},{"speaker":"南委員","kind":"質問・要望","question":"どれだけの７５歳以上の方が分かれて存在しているのかというのは、収入状況がどうなっているのか、ちょっとつかめるかと思って伺いたかったんです。それをぜひ教えていただきたいと、もう１回、質問させてほしいと求めました。","respondent":"本城国保医療年金課長","answer":"進めている状況といたしましては、郵便のところに入れまして、具体的に私たちの声が届くような形で対応させていただいているところです。国の方針の中では、区といたしましても、資格証を発行する予定はございません。","id":"exchange-067"},{"speaker":"南委員","kind":"提案","question":"国民新党が共同して廃止法案を提案しているんですけれども、この廃止を求めるという区民の願いについては、ぜひ受けとめていくべきだと思うんです。その辺のご見解はどうか尋ねました。","respondent":"本城国保医療年金課長","answer":"若干補足して説明しますと、短期証の発行で対応せざるを得ないと考えている方は、準備を進めているところです。一定程度の公平性の観点から、被保険者から運営を請け負っているものとしても、対応しなければいけないものではないかと感じているところです。","id":"exchange-068"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ちょっと意味がよくわからなかったので、どういう意味なのか、詳しくご説明ほしいと求めました。ちょっと先ほどのご説明の中身がよくわからなかったので、あわせてご説明ほしいと求めました。","respondent":"本城国保医療年金課長","answer":"今、現在、新たな高齢者医療制度検討にあたっての基本的な考え方として示された後期高齢者医療制度の年齢で区分するという問題を解消する制度とする。制度的にそういうことがある以上は、かなり絞ったうえでは、一定程度する責務が私どもにあるという認識で対応しています。","id":"exchange-069"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"先ほど、伺ったのは、現役並み所得以下の人からも取り上げるのかと。伺いたいんですけれども、なぜ今まで老人保健制度では、区はどう考えているのかご説明ください。","respondent":"本城国保医療年金課長","answer":"言葉の問題も含めて、そういうことではないということは、よくご認識いただければと思います。現行の後期高齢者医療制度の関係では、今、ご説明させていただいたとおりです。","id":"exchange-070"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"先ほどから伺っているのは、月額１万５,０００円以下の人にも短期証を発行するのかと、それを検討しているのかと聞いているんです。老人保健制度時代に、なぜ、短期証、資格証は高齢者には発行されてこなかったのか、その背景をご説明ほしいと求めました。","respondent":"木下健康福祉事業部長","answer":"制度的に適切な対応をする必要があると思っておりまして、短期証については、この範囲内で送付をしたい。むしろ老人保健制度のほうが特例的な、そういう経過的な制度の中で、そういう対応になっていたんだろうと思います。","id":"exchange-071"},{"speaker":"中塚副委員長","kind":"質問","question":"先ほどから伺っているのは、１カ月１万５,０００円を切る収入の人にも、そんなひどいことまで検討しているのかと。改めて伺いますけれども、残りの１割というのはどういう方なのか、準備しているのか。","respondent":"木下健康福祉事業部長","answer":"窓口負担１割の方もおられますけれども、いわゆる年間年金１８万円、月１万５,０００円以下の方々はおられないだろうと考えているところです。","id":"exchange-072"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"月１万５,０００円以下の人には短期証は発行しないと、そのことははっきりと言うべきだと思いますので、ご答弁ほしいと求めました。基本的に短期証は発行すべきではないと思いますけれども、とりわけ生活が苦しいところにも、そこだけはしっかりとご答弁ほしいと求めました。","respondent":"本城国保医療年金課長","answer":"健康福祉事業部長からもご説明させていただきましたが、かなり少ない額の収入しかない人とか、そういうのは含まれておりません。なおかつ、対応が難しい方ということに絞られているですので、委員からご指摘があったような方に対する短期証の発行は予定しておりません。","id":"exchange-073"},{"speaker":"大沢委員","kind":"意見","question":"自民党としては、旧老人保健制度に戻すことは根本的な問題の解決にはならないということを、会派の中で議論をさせていただきました。新たな制度の創設が必要と考えますので、本請願については不採択ということで、お願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"三上委員","kind":"意見","question":"現役世代の負担をどうするかとかいうことについて、非常に議論がされていかなければいけない問題点を抱えている。ここにうたわれている後期高齢者医療制度については推進してきた立場とすれば、それを廃止することについては、やっぱり応ずるわけにはいかないとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"南委員","kind":"提案","question":"あまりにも問題の多い差別的な内容の色濃い法律ですから、多くの国民から、廃止にしてほしいという声がずっと出て。民主党も、社民党も、国民新党もこぞって廃止法案を提案したという点では、民主党の態度が非常に注目されるわけでありますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"}]},{"id":"topic-04","title":"平成２２年請願第１３号、中小企業センター隣のＪＴ社宅跡地等に特別養護老人ホームの建設を求める請願","agenda":"平成２２年請願第１３号、中小企業センター隣のＪＴ社宅跡地等に特別養護老人ホームの建設を求める請願","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"２１年度、そして今年の３月の時点での入所状況についても、教えてほしいと求めました。そして、何人が区内の特別養護老人ホームに入所できたのか、あるいは、入所申請をされた方の内訳の数字を、まず説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"したがいまして、ちょっと説明が難しいんですが、一応、手元の資料で申し上げますと、平成２１年度の１回目が、お申し込みになった方が５２５名です。数字的には、一応それで説明とします。","id":"exchange-077"},{"speaker":"南委員","kind":"質問","question":"去年の３月に入所をされた方が何人で、平成２１年度を１年かけて、病院も含めてほかの施設に入ったのは何人か。もしそういう方がおいででしたら、その数も含めて、平成２１年度分だけで説明を求めました。","respondent":"冨岡高齢者福祉課長","answer":"入所された方が、１年分ですけれども、１９９名です。その他、今、おっしゃった、取り下げ、つまり亡くなったりした方が１４１名です。","id":"exchange-078"},{"speaker":"南委員","kind":"確認","question":"そして、取り下げは７０人、こういうことでいいんですか。９月の申請なり、再申込みは翌年の１月まで待たなければいけないのか、ちょっとその辺を確認したいんです。","respondent":"冨岡高齢者福祉課長","answer":"１回か２回ぐらいの申込みでお入りになれるということと、あとは、個々のケアマネージメントの中で対応する。大きい制度に乗った部分と個々の対応という形で、そういうご希望の方に対する私どものケアマネージメントです。","id":"exchange-079"},{"speaker":"南委員","kind":"質問・要望","question":"区のほうは、区民の熱い要望になっているという、その辺の認識については、どういうふうに考えていられるのか、一つ伺いたいと思います。その辺を、今までの答弁からもう少し突っ込んだ姿勢を示していただきたいと思っているんですけれども、いかがか尋ねました。","respondent":"冨岡高齢者福祉課長","answer":"個々のケースは、今、私どもの持っている社会資源でどう対応していくか。そういうことで、今後も取り組んでまいりたいと思っているところです。","id":"exchange-080"},{"speaker":"南委員","kind":"質問","question":"人間らしい生活も確保できないことを放置しておいていいのかという、そういう問題なんですけれども、どういうふうに思うのでしょうか。５００人の応募に対して１００人しか入れないという事態を、どういうふうに思っているのか、そこもあえて伺いたいと思います。","respondent":"冨岡高齢者福祉課長","answer":"いずれにしましても、それを放置していいとは思っておりません、対応しなければいけないと思い、絶えず、そういう形で取り組んでいるところです。要介護１ということで、部分的に介助をすれば生活ができる方が６５名、次の要介護２の方が７０名という形でお申込みをされている。","id":"exchange-081"},{"speaker":"南委員","kind":"質問","question":"そういうのをつかんでいるのか、どうかということを、改めてちょっと伺いたいと思うんです。その辺の見解というのはどうなんか尋ねました。","respondent":"木下健康福祉事業部長","answer":"身体レベルも厳しい方々のための施設であり、在宅介護をしている方の限界に対して適切に対応するための施設であります。そういう状況が改善されることもあるわけでありますから、対応し、最後はやはり施設しかないということが一つの流れだろうと思います。","id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"ほんとうに一刻も早くつくってほしいという願いのあらわれだと理解しますので、ぜひ、積極的に探す努力をしてほしいと求めました。最後に１点だけ、積極的に探す努力というのはどういうふうにしているのか、そこだけちょっと具体的に教えていただきたい。","respondent":"冨岡高齢者福祉課長","answer":"区の中でも、用地情報については、私どもでお話をして、積極的に情報を集めているということであり、あとは町会とか、区のほかの関連団体とかにもお声かけをして、用地があれば情報等を適宜お教えくださいと話をしています。","id":"exchange-083"},{"speaker":"三上委員","kind":"質問・要望","question":"ちょっと確認させていただきたいんですが、ここをまず購入しろという要望があって、持ち主のほうは難しいというお話でした。これは教育費の部分にかかわってくるものですから、おわかりだったら、ちょっと言ってほしいと求めました。","respondent":"冨岡高齢者福祉課長、山田副区長","answer":"本件地は事業財産として管理しておりまして、活用方法は社内で活用するという方針ですと、そういう回答があったところです。それから、第一日野小学校跡地につきましては、申しわけありませんが、よく把握してございません。 大きなまちづくりという観点で、ＴＯＣのほうに建て替えるという暫定の期間だけお貸ししますと、暫定でお貸しをするものです。第一日野小学校の移転に際しても、一定の便宜を図るという話で進んでいると、私は聞いております。","id":"exchange-084"},{"speaker":"三上委員","kind":"質問・要望","question":"厚生委員会としては、やはり候補用地として挙がってくる以上は、情報の共有化ということだけはきちっとしておいていただきたい。今後も同じようなことは起きてくる可能性はあるのではないかと思いますので、それはきちっと答弁できるように考えておいてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それから、数字のことは、やりとりがあったのに、結局よくわからなかったので、もう一度伺いたいんです。今年の３月末も新たな申込みが始まりましたけれども、この時点での申込者５５０人のうち、ご説明ほしいと求めました。","respondent":"冨岡高齢者福祉課長","answer":"一定規模の土地がありませんと、やはり、小さい土地では難しいという形で対応しています。売る予定がないというところを、今の段階では、どういう活用という段階ではないと考えているところです。","id":"exchange-086"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"つまり要介護４であっても、要介護５であっても、半分の人は入れていないというわけですよね。冒頭説明した具体化の計画を、緊急にふさわしい具体化を進めるべきだと思うんですけれども、いかがか尋ねました。","respondent":"木下健康福祉事業部長","answer":"そういうクラスで、グループホームも難しいぐらいの土地情報ぐらいしか、具体的な動きがないようであります。公明党のご質問の中で、小規模特別養護老人ホーム、つまり２９人にグループホーム１８人を組みあわせるようなものは検討の余地はあるかなと。","id":"exchange-087"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"５００名を超える方が申し込んでいる、高齢者の生活支援の推進を考えている、緊急だと言っているわけです。どういう事業を進めるために、テンポを具体化すべきではないかと思うんですけれども、その点を教えてほしいと求めました。","respondent":"山田副区長","answer":"区のほうは、実施計画の中で、整備検討というふうにきちんとうたっているわけです。検討とうたわせていただいておりますので、下にあります老人保健施設についても、これからも同じスタンスで臨んでまいりたいと考えています。","id":"exchange-088"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"私も聞いたんですけれども、今年の３月の審査のときに、１０２歳、要介護５の方が申し込んだけれども、入れなかったという話を伺いました。ぜひ目標値を立てて、計画に向けて具体化を進めてほしいと求めましたけれども、最後にいかがか尋ねました。","respondent":"木下健康福祉事業部長","answer":"基本的にそういう考え方でおります。そういう点では、むしろ行政としての責任だろうと考えていますので、責任を持った執行を進めていきたいという考え方です。","id":"exchange-089"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"区民の関心が高いからこそ、そのための計画を進めることこそ区民要望を受け入れるものだと、私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"大沢委員","kind":"質問・要望","question":"それからさまざまな複雑な事情が重なりながらも、積極的に取り組んでいくという基本方針を、先ほど態度のほうで伺いました。しかしながら、本請願、内容、あるいは言っていることは別にしまして、これについては不採択にしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"},{"speaker":"三上委員","kind":"質問","question":"この請願項目のうち１と３については、既に長期基本計画の中で検討するとなっているわけですから、品川区としてはきちっと推進する。この表題で中小企業センター隣のＪＴ社宅跡地ということをうたっているわけですから、それをあえて、これについては不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-092"},{"speaker":"南委員","kind":"意見","question":"したがって、これは一刻も早く２カ所目を建設するめどを、ぜひ、立てていくべきだと思います。したがって、一刻も早くそういう具体的な計画を持つべきだという意見も付して、ぜひ、賛成をしていきたいと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-093"},{"speaker":"稲川委員","kind":"確認","question":"確認をしたら、品川区が強制力を発揮して、そこまでして購入する必要性もないと思います。そういうことも考えると、僕は、不採択にしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"鈴木委員長","kind":"質問","question":"所管質問がございましたら、ご発言を願います。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/360687?Template=document&Id=3270#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":72203,"voices":233}},{"id":"h22-20100628-8","meetingId":"h22-cm06","date":"2010年6月28日","dateIso":"2010-06-28","committee":"建設委員会","time":"午前１０時０３分～午後４時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件整理しています。","topics":[{"id":"topic-01","title":"第５８号議案、品川区景観条例","agenda":"第５８号議案、品川区景観条例","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"もう少し教えていただきたいのと、ちょっと時間がかかったような気がするんですが、これは何か理由があったのかというのをあわせてお伺いします。","respondent":"藤田水とみどりの課長","answer":"東京都が今景観計画をつくって景観行政に取り組んでいるわけですが、まちづくり、景観づくりを進めるというふうに考えてあります。積極的に取り組んでいくことが必要だというふうに考えてございまして、これを目的に景観条例をつくるというものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"都は何をチェックしたのかということ、どんなチェックだったのかというのがちょっと気になってしまったので伺います。考え過ぎであればね、そうでないならいいんですけども、そこら辺はどうなんか尋ねました。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"まず区が考えている景観計画にちゃんと引き継がれているのか、区がやりたいという意識が、どんなことをやりたいんだと。都がやることに加えて何をやりたいんだと、そういった面でチェックが入っていたです。 色とかデザイン、こういったものは現行法では全く規制ができないんですね。しかし、法律がないですから、きちっとした規制ができないということで、国がやっと重い腰を上げてつくったのがこの景観法という法律です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと兼ね合いというんですかね、１１名ということなんですが、メンバー構成と内訳人数を教えてください。間違っていたらちょっと指摘していただきたいんですけど、それが今回区の条例に入っているのはなぜなのかというのをお願いします。","respondent":"藤田水とみどりの課長","answer":"その中で規制ができないのは、先ほどもお話にありました色彩あるいは形態意匠のデザインの部分、そういった部分になります。そういう中で適正なまちづくりを進めていきたいというふうに考えているものです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう協定というのと第１８条の協定というのは、どういう兼ね合いなのか教えていただきたいのと、景観計画策定までの大まかな予定やスケジュールなどがあれば説明を求めました。","respondent":"岩田都市環境事業部長、藤田水とみどりの課長","answer":"一定こういうものを地域で人がこういうことを考えているから、こういった法的に拘束力を持つような、そういうものではないということです。地域のまちづくりの景観ルールをこの景観計画の中で、例外的につくっているのが地域の景観協定… それから、今回ご提案している条例の中では、景観審議会の意見を聞きなさいというような項目も設けてあります。それから説明会、一定の周知期間をとり、来年の４月には運用開始ができるようにしていきたいというふうに考えているもので…","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"議会との関係では、どのように議会の意見を反映させるんでしょうか。そこら辺はどうなんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"景観の協定のほうでよろしいですか。","id":"exchange-005"},{"speaker":"藤原委員","kind":"確認","question":"改めて確認ですが、景観計画と景観行政団体とそれと景観条例は、連携して景観のことをしていく。そういう認識でよろしいんか尋ねました。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"連携という部分ではそのとおりです。まちづくりを進める中では景観それから都市計画に基づくまちづくりとあわせて進めるのが区の統一的なまちづくりの進め方というふうに考えてあります。 これは広告物については、３年から５年で更新手続に入りますので、大体３年から５年でまちの見た目の景観ががらっと変わってしまうんですね。まず目に見える、歩いていて目に見えるところからがらっと変える…","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"部長の答弁を伺っていると、その単体の建造物には必ず建てる方、所有者がいるわけじゃないですか。そして、最高裁等はある程度所有者の権利を認めているわけじゃないか尋ねました。","respondent":"藤田水とみどりの課長、片田防災まちづくり事業部長","answer":"皆さん行政側の意向を一定程度くんで、修正をかけて最終的に合意を得た後、確認申請を出したというふうに聞いてあります。… 建築確認との関係を改めてちょっとご説明しますと、特に地区計画等については土地の権利者とか所有者がおりますので、そういう規制をすると。… 先ほど景観と景観法の関係の中で、仮に景観法を守れないという案件が出てきたときには、行政団体としてまず変更命令を出せます。…","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"最後に一つ質問しますが、建築基準法だと高さだとかいろんなことで具体的な数字で出てくるじゃないですか。行政の常識と建てる方の常識が違うかもしれないじゃないか尋ねました。","respondent":"岩田都市環境事業部長","answer":"一般的な建築物については、まずそれぞれの自治体の景観計画に異論を発して戦ってくるようなところは考えられない。小さいものまで効いてきますので、とにかくそっちも急いで、品川の景観づくりにこれから頑張っていきたいと思います。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"私の見たところ、電線の地中化を今やっているわけですから、このほかに何があるんですか。屋外広告物規制だけなんですから。","respondent":"岩田都市環境事業部長","answer":"２年間で補助金が終わってしまいましたので、一応あれをベースに、あの地区については規制をかけていこうと。こういう考えでいます。","id":"exchange-009"},{"speaker":"市川委員","kind":"質問","question":"あえて理念の３項の中にこのことを入れたというのは、この文言が入ったことで、景観行政団体の許可がおりたというふうに考えていいんでしょうか。あえて両方に東京都、隣接区との協議という言葉が入っているのは、これがないと、許可がおりなかったということなんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"その中では、都が都市計画上の権限をまだ持っているような部分もありますので、その辺については十分に連携協議していかなければならない。連携していくということで、これが入らないと都の同意が得られなかったのかというと、特にそういうわけではございません。","id":"exchange-010"},{"speaker":"市川委員","kind":"質問","question":"もう一つお聞きしたいのは、先ほど景観計画を決定するまでのプロセスの中で、パブリックコメントとか、説明会を行っていくというようなご答弁があったんですけれども、説明会というのはどういう形で行うようなことを計画されているのか、その辺。","respondent":"藤田水とみどりの課長","answer":"地域の方々に、各地域ごとに数回の説明会を開いて、景観計画のパブリックコメントをする中身についてお知らせをしていきたいというふうに考えてあります。","id":"exchange-011"},{"speaker":"阿部副委員長","kind":"質問","question":"お伺いしますが、まず、仕組みのことで少し。以上、説明を求めました。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"現在景観計画で検討し、その中でまず旧東海道品川地区についてまず１カ所重点地区に指定をしていく。しかしながら、それからどのように進めていくべきなのか、これについては十分検討していかなければいけないというふうに考えてありま… 第２号は先行して、これを予定して地区計画まで立ててしまった小山台地区の４１号線沿線、地区計画を既に地域でつくってしまったんですね。これから行政もせっかく景観条例をつくりましたので…","id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"そもそも景観の意味合いというんでしょうか、それをどういうふうに審議会の方々、英語で言うとランドスケープなどいろんな言い方がある。それをどういうふうに皆さんにわかりやすく丁寧な切り口、スタート、これについて説明を求めました。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"そういった中で、区の中を一つの考え方で進めるというのは、その地域ごとの特色を出しながら進めていきたいというふうに考えてあります。区民、景観計画ができた暁には… じゃあ、うちの品川区で景観というのは何と言ったときに、これは極めて難しい。行政もやっぱりお手伝いをして、どんなまちになるか一緒にやっていきたい、こんなふうに考えております。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"これに基づいて自治体が景観を守るルールをつくるということ自体は、やっぱり非常に意義があるというふうに思います。そのルールづくり、ぜひ住民の思いを大切にして生かしていただきたいということで、共産党としては賛成いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"財源的なことをお伺いしたいんですけれども、まずお金の出どころといいますか、どういう形で予算が組まれるのか、あとこれの案件についての予算。単位は１ｍでも１０ｍでも結構なので、余りにも単純な質問なんですが、あの板橋の大山まで続いているということでこういう名前になっているのか。","respondent":"井浦土木管理課長、藤橋都市整備下水道課長","answer":"３点目の大山の部分ですが、この延長部分、若干何カ所か狭隘部分ということで接続が大変狭隘になっているところが３ポイントほどあります。起点から終点まで道路網として接続しています。 それの部分につきまして、平成２２年３月にどんな埋設物があるのかということを調査しました。４００ｍで約２億円ちょっと、メートル当たりにしますと約５０万円程度で…","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"黄色い部分が、下のところがあいているんですけど、ここは地中化をやらないということなんか尋ねました。","respondent":"藤橋都市整備下水道課長、岩田都市環境事業部長","answer":"今回の事業の対象範囲としましては、戸越小学校と国文学研究資料館跡地の間の道路を除いたコの字型の部分だけを対象に考えております。将来的な検討という形で、その部分は対象から外れております。 いわゆる歩行者最優先の道路に全面つくり変える予定にしております。そういうことで、そのときに大規模に全面工事をやりますので、そういうときにこの部分は地中化をしよう、こういう計画になっております。","id":"exchange-016"},{"speaker":"松澤委員","kind":"質問","question":"今回重複認定されるということは、私２０年以上議員やっていますが、再三いろんな質問をしているんですね。区道に直せばいいんじゃないかと再三質問したんですけど、何でここは重複認定されるんですか、もう一度説明を求めました。","respondent":"井浦土木管理課長","answer":"品川区の防災生活圏促進事業に基づきまして、国文学研究資料館跡地周辺道路を整備するという中で、東京都と協議をいたしまして、道路管理者である東京都との協議あるいは合意の中でこのような計画ということで提案させていただきました。","id":"exchange-017"},{"speaker":"松澤委員","kind":"質問","question":"はい、わかりました。そうすると、重複認定というと、生活一般に対する管理はすべて区が受け持つということでよろしいんか尋ねました。","respondent":"岩田都市環境事業部長","answer":"本来、法が示しておりますのは、重複認定した場合は、上位管理者が管理することという定めになっております。東京都が管理をするということになっているんですけども、今回はその逆を、特例規定を使って逆に区が都道を管理するということにしております。","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問・要望","question":"それでもそういうのにかこつけて区民の利便のためにここまで重複認定してくれたんだということでしょうか。うなずきじゃなくて。","respondent":"岩田都市環境事業部長","answer":"六年で２６号線全線開通という目鼻がつきましたので、区が責任を持って、道路公園課のほうできちっとした管理をしてまいりたいと思います。","id":"exchange-019"},{"speaker":"阿部副委員長","kind":"質問","question":"あくまで重複認定というのは、どの程度の頻度であるものなんですか。区内にいっぱいあるんか尋ねました。","respondent":"齋藤道路公園課長","answer":"区道の真ん中に区境があるようなもので、大田区と品川区の間にたしか２カ所ありまして、目黒区と品川区の間に１カ所あります。３路線か４路線あったというふうに記憶しております。","id":"exchange-020"},{"speaker":"阿部副委員長","kind":"質問","question":"今の例は、重複認定というのは、区と隣区の重複認定、都と区の重複認定というのはほかにはないんですか。あまり突っ込むと申しわけないんですけど。","respondent":"井浦土木管理課長","answer":"都と区の重複認定については、ほかにはないというふうに認識しています。","id":"exchange-021"}]},{"id":"topic-02","title":"審査の進め方","agenda":"審査の進め方","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"早期実現を求める請願ということで、何か今このタイミングで早期実現を求める請願が出てきているのは、何か大きなわけがあるのでしょうか。これをどういうふうに扱っていいのかというのがちょっとわからないんですが。","respondent":"三宅都市開発課長","answer":"近隣の皆さんへの説明だとか、あと関係権利者との調整など、当初計画に比べればそれが積み重なってきたというところだと認識しております。もくろみどおり、いろんな説明とかいろんなところに時間を要しているのは事実でして、やはり積もり積もって…","id":"exchange-022"},{"speaker":"渡部委員","kind":"質問・要望","question":"とにかく早期実現を求める請願というのは、これは予定どおり進めることが大事だと思います。別々にやるんか尋ねました。","respondent":"原委員長","answer":"平成２２年陳情第１２号、「目黒駅前再開発事業」の環境と都市計画に関する陳情の理事者説明までを続けて行い、その後、一括して質疑を行います。〔書記朗読〕","id":"exchange-023"},{"speaker":"渡部委員","kind":"質問・要望","question":"もう一回当初の確認で、この計画自体、目黒駅前地区市街地再開発の目黒駅前再開事業の進捗のおくれがあって、このように請願が出てきたのか。区長が当然申し入れをしたわけですから、このようなことが返ってきていますよというようなところがあれば、あわせて教えてほしいと求めました。","respondent":"三宅都市開発課長","answer":"ご質問の２点目ですが、区長意見６項目の対応です。円滑な事業推進に努めてまいりますという考えが示されていたり、風環境の影響については、詳細設計の中でさらなる植栽や施設の形状を検討するなど。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"区長の意見に対して答えが出ているのかどうなのか、一応内容としては、一つのポイントとしてそこが気になったので伺いました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"陳情のほうですが、理由の中に「区長が」という文言が結構出てきますが、この文章は、完璧といいますか、一つも間違いなく、言っていることは正確なんか尋ねました。","respondent":"三宅都市開発課長","answer":"陳情の中に引用している部分という意味でしょうか。","id":"exchange-026"},{"speaker":"藤原委員","kind":"意見","question":"「区長が」と、この文章を読むしかわからないわけですので、だから、この文章が正しいかということ。「区長が」こうします、「区長が」意見書を上げています、「区長が」と出てくるのは正確かということの意見を述べました。","respondent":"工藤環境課長、岩田都市環境事業部長","answer":"環境影響評価の手続の関係で、私どもの課のほうで区長意見という形で集約いたしましたのでお答えします。ビルが建つということで、全体的な考えとして、そういった部分でお含みおきをいただきたいというふうに思っております。 まちの環境が開発によって変わるわけですから、建物の形状等が大きく変わってきますので、さまざまな場面で影響が懸念されると。したがって、こういう意見書はどのような意見書に対しても同じようなトーンで意見を述べております。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"そこをはっきりどういう趣旨でつくるというのを聞かないと、区長意見に基づいて事業者を指導するようにしてくださいというのが目的じゃないですか。でいいんですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"建築物の配置や形状等について考慮してほしいと区長が言っているので、そこら辺を教えてください。意見を上げた地元自治体として、事業者がまともに答えなかったのに対して、それでいいと思っているのかどうかお伺いします。","respondent":"岩田都市環境事業部長、三宅都市開発課長","answer":"具体的な対策として、植栽・樹木の高さ、それから樹種、十分に検討してください。それに対して答えは、今後の詳細設計の中でさらなる植栽やひさし等の形状を検討するなど、計画建物による影響の軽減に努めてまいります。 配置・形状等の実際の対応ですけれども、午前中に説明しましたカラーのパンフレットで、私が２ページ目下段のところでご説明いたしましたように。今ご説明がありましたように…","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"ほかにどのようなものが挙がっているのか、同様な声などがあがっておりましたら、ちょっと区にあがっていましたら教えていただきたい。よく事業者から出てくるランク１とランク２という図があると思うんですけど、何に基づいてそういうふうに判断するのか、ちょっとお伺いします。","respondent":"三宅都市開発課長、片田防災まちづくり事業部長","answer":"説明会のほうは大きなものは合計３回開催しておりまして、３回やっておりまして、そのあたりで出ているのはやはり風のご心配というものも出ています。ランク２、ランク３という形で評価しておりまして… ボリューム、これを決めるものは都市計画の中で改めて審議をしていただきますし、あと用途地域の変更もあります。平成２１年１０月および平成２１年１２月、今回の計画になってきているものと認識しておりますので…","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"風速ランク１というのは、風速１０ｍ以上が年に３７日以下とか、これをきちっと見たことがあるのかどうか。これだけをもって判断しているんじゃないのかというふうに思うんですけれども、そこら辺はいかがなんか尋ねました。","respondent":"三宅都市開発課長","answer":"武蔵小山の件につきましては、実測調査もやっていて、ほぼ予測どおりの事後の調査結果も出ていると聞いております。風環境につきましては、決して影響が全くないというわけではなくて、許容範囲の中におさまることになるだろうという認識です。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"ランク２というのはどういうことかというと、風速１０ｍ以上の風が８０日以上あると。だから、具体的に生データを見ると、確かにそういうふうに思うんですが、その瞬間ではどうなのか尋ねました。","respondent":"片田防災まちづくり事業部長、岩田都市環境事業部長","answer":"そんなことも含めて風洞実験等を行った中で、一応評価して適正だということで私どもは考えております。植栽を置いたりとか、やはりそういうきちっとした適正な評価の中でやっているものですので… それを２まで抑えているというのが今の状況ですから、より工夫をして、頻度を少なくするように努力をしてください。住民の人をさらに不安に駆り立てるような言い方というのは、極めて我々としては気をつけなければいけない…","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"はっきりと書いているわけですから、事業者やあるいは東京都等に求めていってほしいんですが、いかがでしょうか。だてにつけているわけじゃないんでしょうから、住民の方からもやっぱり区が責任を持って指導してほしいという話が出てくるわけですよ、建った後に。","respondent":"岩田都市環境事業部長、三宅都市開発課長","answer":"いわゆる区民の方に余分な不安をさせるようなご発言というのは、私は気をつけていただきたいと思います。私どもが信用できないというのであれば、それをひっくり返すような根拠を持たない限りは、それは言えないわけです。 大崎などで集めているデータですけれども、武蔵小山でもございましたが、事前の評価と比べて基本的にずれていないということを確認すると。都市環境事業部長のほうからも説明がありましたけれども…","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"多分それは一致しているということはさまざまなところで確認されていると思うんですけど、この前、住んでいる実感としては怖いわけですよ。ぜひ住民の皆さんが住んでいる感覚で、そういう方向で研究をしていただきたいと思うんですが、ぜひお願いしたいと思います。","respondent":"片田防災まちづくり事業部長","answer":"私どもは感覚で物を申し上げるわけにいきません。私は十分だと考えていますし、今後の状況を踏まえて予想どおりかどうかということを確認していくということで進めていきたいと考えています。","id":"exchange-034"},{"speaker":"藤原委員","kind":"確認","question":"意見を言っていないのですから、それは質問するなということでしょうか。そこの確認だけはちゃんとしていただかないと、意見を言っていないのですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"安藤委員","kind":"確認","question":"ただ、議事録を確認していただければと思うんですけども、藤原委員が質問した後に答弁があって、その後に自分の意見を言っているんだと思います。だから、質問自体をやめろとか、やっちゃいけないとかという意図は全くございませんし、そういう事実もないと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"松澤委員","kind":"質問・要望","question":"更に考慮する事を事業者に求めたものです」と、ここが問題だろうということで、最初から話に出ました。質問的には何か質問しなくちゃいけないので、私は先ほど考え違いをしているというふうにお話ししましたけれども、区の見解を求めたいと思います。","respondent":"岩田都市環境事業部長","answer":"先ほどお答えしましたように、全く事実とは違います。大なり小なり変わることは事実ですので、この陳情者の方はそこら辺をちょっと誤解なさっているのかなというふうに考えております。","id":"exchange-037"},{"speaker":"市川委員","kind":"質問","question":"先ほどからいろんな委員がご質問されているんですけれども、許容範囲であるということをおっしゃっているんですけども、その辺を教えてください。許容範囲という判断をされているのか、お聞きしたいんですけども。","respondent":"三宅都市開発課長、岩田都市環境事業部長","answer":"説明会などには４月に直近ではありますが、確かに直接住民の方から、やはり風が強いというようなお話は聞いております。その結果、目標範囲におさまるというところを確認するように、そんな考えで評価書案を引用しています。 出るから弱めるような工夫はできないかということを考えていくのが、我々の知恵なんですね。公園なんかをつくって空地をつくると突風が吹くからやっぱりやめたほうがいいという考えになっちゃうというのは、私は事実だと考えております。","id":"exchange-038"},{"speaker":"市川委員","kind":"質問・要望","question":"やはり住民の方はそういう公表されているものから区へ意見・要望を言っていくんだというふうに考えると、区のご意見としてどうなんでしょうか。そういうふうに住民は受け取ってしまうんじゃないですかということを申し上げたんですけど。","respondent":"岩田都市環境事業部長","answer":"そんなことは言おうものなら、さらにすごい技術をもって反論しなければいけないわけですから、そんなことはできるはずがないわけです。我々としては、プラスアルファにさらにいろいろ配慮していただきたいという意見を都知事に申し上げたです。","id":"exchange-039"},{"speaker":"阿部副委員長","kind":"質問","question":"それは今住民の方が目にするわけですから、もう少し書き方の工夫があるんではないかと思うんですけれども、それはいかがお考えでしょうか。１点お伺いしたいのは、都以外にどのくらいいらっしゃるんですか、説明を求めました。","respondent":"三宅都市開発課長、岩田都市環境事業部長","answer":"地権者は１１人おります。その方々をカウントしますと、約１３０人です。 非常に危険だと思いますので、今後こういった評価書に対する回答の場合には誤解を与えないような表現に改めると同時に、懸念なんていう言葉は二度と使わないように配慮したいと思います。","id":"exchange-040"},{"speaker":"阿部副委員長","kind":"質問","question":"地権者の方、やはり再開発は、やはりその方々の生活の基盤になるところが揺れ続けていくという状態があまり長続きしていいものではないと思います。ですから、影響を最小化する努力だけではなくて、不安を取り除くための努力はどの程度行われているのか説明を求めました。","respondent":"三宅都市開発課長","answer":"組織に対しては、そういう組織が結成されてから少なくとも４回、それ以前もまだそういう地域の団体ができない段階でも４回ぐらいは対応しております。それぞれ個別に問い合わせがあれば、住民説明などでその都度対応したところです。","id":"exchange-041"},{"speaker":"阿部副委員長","kind":"質問","question":"ですから、結構やっているというぐらいの把握のされ方では、私はちょっと不十分ではないかと思います。その意味では、少しでもより積極的に近隣住民の方々のご理解を促すようなことを、もっと意図的に進められたいと思うのですが、ご意見をお伺いします。","respondent":"片田防災まちづくり事業部長","answer":"これまで担当課長からご説明させていただきましたように、何度か説明会をやってきております。適切に対応することと合わせて、個別的にそういうお話があればご不安を取り除くような説明をするという方向で対応させていただきたいと思います。","id":"exchange-042"},{"speaker":"松澤委員","kind":"質問・要望","question":"もうそろそろ意見が出尽くしたと思いますので、そろそろ結論を出してほしいと求めました。議事進行について諮ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は請願のほうに関して質問できなかったので、ちょっと私も早く終わっちゃったんですけども、こちらのほうの質問をしたいので、時間もまだいい時間ですので、ぜひ続けてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"渡部委員","kind":"質問・要望","question":"結構審議は尽くされたと思います。結論を出してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"阿部副委員長","kind":"質問","question":"具体的な質問をしたい方がいらしてますので、簡潔に今お示しいただければいいかなと思いますけど。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"松澤委員","kind":"質問","question":"本日結論を出す。意見表明まで言うということか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"松澤委員","kind":"意見","question":"幾度も住民の中で対話をしているという話がありましたし、地権者の中にはマンションを処分してしまって、その間、困っている方もいらっしゃいます。その方たちの生活を考えたりしまして、私どもとしては、この請願に対しては採択いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"若林委員","kind":"意見","question":"待望久しい目黒駅前の開発です。パンフレットにも認証保育所等取り組みますから、一日も早い早期実現を、この請願については採択というふうに賛成をいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"商店街の皆さんが活性化を求めるのはわかるんですが、あるいは日影の問題が、やはり幼稚園の方からも事業所に対して要望書が１月に出されました。現行計画を早期に実現してほしいという請願に賛成するというわけにはいかないので反対ということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"渡部委員","kind":"意見","question":"本日、私は採択します。これからどういう形で、今後の経済状況とかによって若干長引くかもしれませんが、何とか予定に近づけて早くやって活性化されるよう望みますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"藤原委員","kind":"意見","question":"予定どおり進んでも、ある一定程度の時間がかかるのにもかかわらず、２年おくれているという現実の問題。やっぱり一日も早く、こういう形の請願の趣旨はすごく私自身もわかりますので、この請願に賛成をしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"市川委員","kind":"質問・要望","question":"私どもは、ネットとしては不採択です。引き続き事業者のほうの意見をいっていただいて、そういった不安を取り除く、そういう努力を区側もしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"この事業の促進を求めるというこの内容については、採択します。やはり再開発ですから、この先も地道に続けていくことは、再開発として当然のことだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"松澤委員","kind":"質問","question":"先ほども質問しましたけど、陳情者の方はこの区長意見というものに対して取り違えをしているということ、他の方の質問に対して、部長の答弁で、さらに考慮するという言葉を今後考えたいぐらいだと今おっしゃいましたので、重大な、この陳情に関しては勘違いをしているので不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"十分していただきたいという意見と、高さ等の大枠を決めるものですので、特に風環境等を都市計画に反映させることはそもそもあり得ない。そういう意味では、不採択にするしかないかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"安藤委員","kind":"意見","question":"議会にも白金幼稚園からも１月に私どもの会派に、計画の見直し、日照と風環境なんかで出されております。抜本的なところから見直しを働きかけていくというのは当然正しい動きだと思いますので、私はこの陳情に関しては採択で賛成ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"渡部委員","kind":"質問・要望","question":"確かに上がっている文章を見て懸念という言葉があったりしましたものですから、懸念というものに対する意味合いも伺うことができました。再開発は先ほど採択されました早期実現を求める請願を採択しましたので、いわゆるこの陳情書については、今回不採択としたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"藤原委員","kind":"質問・要望","question":"こうやって委員会で懸念というのはどういうことだという形でいろいろ議論したからよく理解ができましたけれども、とり方ですから、感じ方ですから。ですから、ああそうですかというふうになるわけですから、区長の言葉というのはものすごく大事ですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"市川委員","kind":"質問・要望","question":"結論としては私は採択、賛成です。住民の方々が、住環境を守ってほしいという気持ちは十分理解できますので、住民の不安をなくすような形に進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"阿部副委員長","kind":"意見","question":"この陳情の要旨をどう読むかは難しいところではあるんですけど、これをそのまま採択というのは難しいなと考えています。風環境に対する不安に対して、これからまだやってくれることが、やり得ることがあるんじゃないかと、そういう意味での趣旨採択としたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"}]},{"id":"topic-03","title":"平成２２年陳情第７号、旧国文学資料館内池の周辺整備の改善に関する陳情","agenda":"平成２２年陳情第７号、旧国文学資料館内池の周辺整備の改善に関する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"仮に釣りというんですかね、安全面の配慮というのはできるのかどうなのかということと、２点お伺いします。","respondent":"藤橋都市整備下水道課長、片田防災まちづくり事業部長","answer":"いわゆる管理小屋と申しますか、管理室を設けるようなことをもし考えた場合は、そのスペースの部分だけが避難人口が減るという形になります。現在１人１.１８m2が国文学資料館跡地の１人あたりの面積ですので… ちょっと担当課長の説明の中で補足しますと、前回一度陳情が出まして、取り下げられた経過があります。その中で、区としての考え方を今課長のほうで言い漏れたところがございましたので、ちょっと補足させていただきたいと思います。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"釣りゾーン、ゾーンというのは結局可能なのかどうか、区としてはどのようにお考えなのか。釣りという要望というのは、どれだけ強いのかというのがちょっと私も把握していないところなんですが、把握されておりましたらお伺いします。","respondent":"藤橋都市整備下水道課長、片田防災まちづくり事業部長、岩田都市環境事業部長","answer":"ここの説明をしたとおり、それから管理する上でもさまざまな多くの課題がありますことから、区としては釣り堀とすることは考えておりません。… 共存というお話がございました。基本的には共存の釣り堀と池を残して親しんでいただけるという空間との共存というのはなかなか難しいことだと考えて… さまざまな面から考えて、前回住民説明会でお出ししたのは、珍しい池だと。数年来初めてというか、反対者１人もなしの… 昔戸越公園が今の形ではないときに…","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"一つの要望として釣りというのを、ただ、いろいろハードルがあるのかなと思うんです。その辺はちょっともう一度、安全面の配慮ということから区の考えをもう一度説明を求めました。","respondent":"藤橋都市整備下水道課長、岩田都市環境事業部長","answer":"釣り堀の事例が２３区の中で７区、八つほどあります。先ほど申しましたとおり、後ろ側は見えないものですから、背面側に何メートルかの安全な空間を確保しなければならないといった声を聞いております。 下げて、一番深いところで四、五十cmぐらい、そういうなだらかに来て、ふちのほうが１０cmとか１５cmぐらいで、水生植物がふちのほうに植わる。あるいはメダカやクチボソの生物を楽しむ、こういうものはどうだろうということで…","id":"exchange-064"},{"speaker":"阿部副委員長","kind":"質問","question":"一つ、高齢者の交流の場としてというときにもう一度この平面図を見たときに、ベンチは実数になるんですかね。これはどういった材質でつくられるのか、ああいったものの上を歩くと、そういった工夫などもあわせて考えていらっしゃるかどうかお伺いします。","respondent":"藤橋都市整備下水道課長","answer":"２４日の説明会でもやはり意見が出ていまして、やはり高齢者の方が来て、その点については設計作業を進めるなかで検討してまいります。散策路の材質につきましても、これから地域の方のご意見を踏まえまして、今後の設計の中で検討してまいりたいと考えています。","id":"exchange-065"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"だけど、ゆっくり過ごせる、歩き続けなくても手持ちぶさたでないような何かそういう池周辺の環境を考えていただければなと思います。これは最後の要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"松澤委員","kind":"質問","question":"今理事者のお話を伺って、釣り堀にするなんてとんでもない。四つ丸があって、二つだめなので、趣旨採択。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"若林委員","kind":"意見","question":"５、６と来たので、取り上げることはないと思います。ということで、不採択ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望ですから、こういう要望というのも出てくるのはありだと思うんですけれども、ちょっと今回は不採択します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"渡部委員","kind":"質問・要望","question":"説明を聞きまして、我々の地域にこれが親水公園というんでしょうか、すごくうれしい思いをいたします。やはりこの５番、６番に関しては、今回はこの陳情に関しては不採択を表明させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"阿部副委員長","kind":"提案","question":"５番は表現としてはあくまでも例えばということで、この方々は例えばこういうのはどうでしょうかというご提案の部分だと思うんですね。そういういろんな思いついたことを提案して、いろいろなことを考えついて提案してくださるということ自体は、趣旨採択でいきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"}]},{"id":"topic-04","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"和解自体は、４の(2)の平成２２年３月に１１万７,９００円、平成２２年４月から平成２４年２月まで１０万円ずつ。明け渡すまでの平成２１年１０月末までの未払使用料等の合計１６６万１,９００円と明渡し済みに至るまでの使用料等に相当する損害金の支払いを求め。","respondent":"柏原住宅担当課長","answer":"訴訟の金額であるとか、訴訟費用ですね、そのもとになる数字になっているものです。それから明渡し済み後の金額ということで、こちらは家賃相当分ということになっておりまして、別のものというふうに考えていただければと思います。","id":"exchange-072"},{"speaker":"渡部委員","kind":"質問","question":"既に専決処分事項を見ますと、平成２２年３月に１１万７,９００円、平成２２年４月からですから、今６月ですよね。４月、５月、１０万円ずつ間違いなく入ってきているんか尋ねました。","respondent":"柏原住宅担当課長","answer":"こちらの分につきましては、保証人の方から、月々こちらのほうから納付書を出していますけれども、現在のところは滞りなくお支払いいただいております。","id":"exchange-073"},{"speaker":"安藤委員","kind":"質問","question":"区民住宅の使用料を払えない方、滞納されている方というのは、結構この間増えているのかどうか。その状況をちょっとお伺いします。","respondent":"柏原住宅担当課長","answer":"家賃が上がるという制度がありますので、その関係で退去される方がいらっしゃいまして、その方の分については若干お支払いが滞っているというものが出ております。","id":"exchange-074"}]},{"id":"topic-05","title":"涼のみち整備事業","agenda":"涼のみち整備事業","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"気温への影響というんですかね、道路が１０度下がることで、体感としてはどれぐらい涼しくなるのか教えてください。打ち水のタイミングの話がありましたけども、どこら辺で行うのが最も効果的なのかお伺いします。","respondent":"齋藤道路公園課長","answer":"保水性舗装は１万４,０００円、遮熱性塗装は平米当たり１万７,０００円が大体の実施金額です。宮前商店街２期分は、反射で暑いと感じられる方もいらっしゃるので、これもないような工夫はしております。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。これから何かこれもやってほしいとか、どういう基準でどこに広げるのかという何か基準があるのか、そういう考えがあればお伺いします。","respondent":"齋藤道路公園課長","answer":"可能な限り区内の業者の方を活用し遮熱性塗装を施工してまいります。保水性につきましては、これもできれば荏原のほうを中心に商店街に幾つかお声がけをして今後進めたいと考えています。","id":"exchange-076"},{"speaker":"松澤委員","kind":"質問","question":"ところが、平成２６年に２６号線が完成しますと、あそこが抜け道になって、相当車の量が増えると思っているんですよ。その辺の調査はしてあるんか尋ねました。","respondent":"齋藤道路公園課長","answer":"交通量調査はどうなるか、５年後、６年後の交通量を踏まえた調査はしておりません。","id":"exchange-077"},{"speaker":"松澤委員","kind":"質問","question":"今、平成２２年ですから、平成３２年までもつ、平成２８年で終わるか、楽しみにしています。それまで議員をやっていたら、そのときに。","respondent":"岩田都市環境事業部長","answer":"確かに２６号線が全線開通して、これは実際そうなってみないとわからないんですけども、戸越銀座通りへの抜け道として考えられないことはないです。おそらく寿命も保水性舗装から比べればぐんと長いものですから、こちらに今注目して区は見ているです。","id":"exchange-078"},{"speaker":"阿部副委員長","kind":"質問","question":"遮熱性塗装についてお伺いしたいんですけれども、反射ということで、例えばまぶしさみたいなものというのは特に関係ないんでしょうか。そこを説明を求めました。","respondent":"岩田都市環境事業部長","answer":"一般の道路に使う場合は、白線との認識ができないものですから、警視庁からは厳しく指導されています。こちらのほうが将来的にはずっと先が見えるということですね。","id":"exchange-079"},{"speaker":"阿部副委員長","kind":"質問","question":"先ほど体感ではというお話の説明がありましたけれども、去年の分の実測、データとしては何かとっていらっしゃるんですか。結果をもとに多分今年もさらにということになっていると思いますけれど、どうでしょう。","respondent":"工藤環境課長","answer":"気温のほうもはかっておりまして、やはり水をまいた後なんですけれど、大体１.３度ぐらいおちているというのがデータとして出ているところです。効果は出ているです。","id":"exchange-080"},{"speaker":"阿部副委員長","kind":"質問","question":"ごめんなさい、最後に１個だけ。冬に保水したりして、例えば凍結したり、膨張して道が傷んだり、そういうことはないんか尋ねました。","respondent":"齋藤道路公園課長","answer":"今委員からご指摘いただいたような事案はございません。雨は降りますけれども、凍結というような事例がないような製品をということで、各事業者の方が工夫をされて商品化されたものです。","id":"exchange-081"}]},{"id":"topic-06","title":"の自転車走行レーン整備の事業効果","agenda":"の自転車走行レーン整備の事業効果","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"あえて交通安全担当課長にお伺いしますが、これも前の委員会でも伺ったんですけど、改めて基本的なことをどういうふうに教わったかということを説明を求めました。","respondent":"藤木交通安全担当課長","answer":"大体歩きましても５分ないし１０分ぐらいでどこかの、不要不急の場合を除きまして可能な限り自転車のご利用はご自粛いただくようなことで、区のほうでやっております。","id":"exchange-082"},{"speaker":"藤原委員","kind":"質問","question":"道路公園課長にお伺いしますが、自転車は乗らないというふうに教わっているわけですよね。しかし自転車の走行レーンをつくるとか、自転車に対してこれだけの投資をするということは、何か基本的な考えというのは変わったんか尋ねました。","respondent":"齋藤道路公園課長","answer":"去年も１２０件の人身事故の３８％は自転車が関連しており、亡くなった方はいませんが、去年はお二人が重傷となっています。そういうことを考えると、ルールというのを私のほうとしては徹底して、立会道路を拠点に幾つかルールを守っていきたいというふうに考えております。","id":"exchange-083"},{"speaker":"藤原委員","kind":"質問・要望","question":"１回齋藤課長、本当に現実自転車に対してそういう考えでいいのかということを１回よく、自転車はあまり乗るなと。こうやって施策をしているわけですから、個人的で結構ですから、ちょっと言っていただきたい。","respondent":"岩田都市環境事業部長、中山防災課長","answer":"だから、総合的にきちっと対応していかないといけない。ご理解をお願いします。 ひなたぼっこをしながら毎日４時間ぐらい、私思ったんですけど、非常にマナーがよくなりました。それから走り出すというようなことで、きれいですし、大変マナーがよくなったことを一言言いたくて発言しました。","id":"exchange-084"},{"speaker":"安藤委員","kind":"質問・要望","question":"利用しやすい整備というものに力を入れていただきたいなというふうに思うんですけれども、そういう大きな一つなのかなと思っているのですけど。平日で１６％という数字を区はどのように見ているのかというのをお伺いしたいのと、どうしてもかえって危ないなと思うときもあったりするんですが。","respondent":"齋藤道路公園課長","answer":"私の説明が悪かったかもしれませんけども、整備が終わって１カ月もたたないうちに交通量調査を行い、なるべく歩道は自転車が走らないように。仕事のためのものではなくて、ずっととまっているようなものについては…","id":"exchange-085"},{"speaker":"安藤委員","kind":"質問","question":"例えば、例えば現在１車両路線をちょっと減らして自転車レーンに当てるとか、そういう可能性というのはないんでしょうか。今の条件だけでいうんじゃなくて、そういう可能性があるということというのは考えられないかなと思うんですが、いかがか尋ねました。","respondent":"岩田都市環境事業部長","answer":"２車線要るだろうと見込んでつくってありますけれども、交通量が２車線、現実的には可能性があるところというのはほとんどない。今会いに行きますと、あいさつもしてくれますし、非常に理解を得ているところです。","id":"exchange-086"},{"speaker":"渡部委員","kind":"質問","question":"近いですからあそこを通りますけど、逆に自転車は危ないですね、ああなると。何か東急バスから今回のあそこのカラー舗装をやったことによっての、よかった、悪かったという話はなかったか尋ねました。","respondent":"齋藤道路公園課長","answer":"今後また引き続き警察と連携しながら取り締まりに努めていきたいと思います。自転車走行レーンの整備には、若干課題はあるんですけれども、区としては効果はあったんだろうなと現時点では考えております。","id":"exchange-087"},{"speaker":"市川委員","kind":"質問","question":"今回検証したということで、効果と今後の課題ということをだせてとてもいいことだというふうに思っています。２件の歩道上での事故、区としては今後どのように感じているのか、その辺をお伺いします。","respondent":"齋藤道路公園課長","answer":"結局歩道をつぶしてまで自転車走行帯をつくれる候補地の選定が難しい。こういう話もあるようで、なかなか歩道を分けて自動車走行レーンをつくるというのは、いろんな意味で影響があって大変なようです。","id":"exchange-088"},{"speaker":"市川委員","kind":"質問","question":"品川区としても、桜新道で実験したような、分けるということは今後も考えていないということか尋ねました。","respondent":"岩田都市環境事業部長","answer":"歩道があっても１.５ｍとか、そんな恩恵を与えられているものではないんですね、自転車レーンは。見通しをよくするということだけでも大きいかもしれませんし、何かそういうのをこれからも考えて、自転車対策はちゃんと一方でやっていきます。","id":"exchange-089"},{"speaker":"阿部副委員長","kind":"質問・要望","question":"正解を教えていただきたいんですけど、自転車レーンを走っていて、さっきから出てくる駐車車両がありますね。駐車車両があったときは、自転車はセンターライン側に出るのが正しいんですか、それとも歩道側に逃げるのが正しいのか、区としてどうなんか尋ねました。","respondent":"藤木交通安全担当課長","answer":"原則は特にありませんけど、自転車は原則として車道通行という道路交通法上の規定があります。歩道を走るのであれば、スピードを落としてゆっくり走っていく、そういうルールがあります。","id":"exchange-090"}]},{"id":"topic-07","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、建設委員会に係わる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、建設委員会に係わる項目","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"初日の宮崎克俊議員の莫大な税金投入で進める大規模開発より区営住宅こそという質問の中で、そういうような住宅ストックを活用していくんだという考えだったので、そこら辺をもう少し知りたいのでお願いしたいと思います。","respondent":"片田防災まちづくり事業部長、原委員長","answer":"明日、ちょっと資料、調査を行ったところもありますので、そういう資料を含めてご説明させていただきたいと思います。 資料をそろえていただいて、申し出委員以外の方にも議論に加わっていただくという形で進めさせていただければと思います。〔「なし」と呼ぶ者あり〕","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/483234?Template=document&Id=3980#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":82953,"voices":265}},{"id":"h22-20100628-9","meetingId":"h22-cm06","date":"2010年6月28日","dateIso":"2010-06-28","committee":"文教委員会","time":"午前１０時０２分～午後０時２８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"の第５９号議案、品川区立学校設置条例の一部を改正する条例","agenda":"の第５９号議案、品川区立学校設置条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"改めて小中一貫教育についてお伺いしたいんですけれども、小中一貫校は子どもや親の願いにこたえるものなのかということをまずお伺いします。専門家の評価、２００６年に日野学園ができて以来、現在までの評価のまとめがどうなっているのかお伺いしたいと思います。","respondent":"和氣小中一貫教育担当課長","answer":"専門家からも高い評価を受けながら、これからの新しい義務教育のあり方の１つとして大変注目を集め、さらにそれに取り組む自治体が大変多くあります。その中で効果や課題についてさまざまな議論がされておりますが…","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"この間ずっと議会で同じような答弁を多々伺っているのですけれども、データ的なこととか客観的な検証はあるのでしょうか。それをお伺いしたいと思います。","respondent":"和氣小中一貫教育担当課長","answer":"私どもが今つかんでいるだけで１８８の自治体がやっておりますが、実際はそれ以上にやっていると言われております。これをごらんいただいたらと考えています。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教員の方々にお伺いしても、実際には教員の中でも有効性はどうなんだろうかと、実感的において。例えば私立をやめて小中一貫校を選ぶといった傾向とかが出ているのかどうか、その点をお伺いします。","respondent":"和氣小中一貫教育担当課長","answer":"そういう意味で、特になかなか実感していただけなかった中学校も、今どんどん実感をしてさらに進めていこうというようになっているところです。逆に保護者、名誉毀損で訴訟を起こせないかというようなことを私に言われているぐらいですので…","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"事実を見てって、今のお話を伺っていると保護者に向けてのアンケートの結果で満足度が高いというだけで、私はさっき専門家の検証はどうかと。アンケート結果の数字は出ているかもしれませんが、それをもって満足度が高い、効果があるんだという、それだけか尋ねました。","respondent":"和氣小中一貫教育担当課長","answer":"すべての論法が木を見て森を見ないような論法になってしまったら、実際に進めるべき正しい道を進めないと私どもは考えております。さまざまな意見を聞きますけれども、そうした中で実際を踏まえた、本当に子どもたちのためになると考えられることを、十分検討して進めていくです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"是非が問われているからこそ、基本的なことを再度お伺いしているのであって。２００７年に小中一貫校に持っていく前に、選んだ学校で卒業させてほしいと、もう怒りが本当に爆発したという意見が出たわけですね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"共産党は、教育内容の検証、専門家とか現場の教職員にも、地域の住民の方も参加をした検証を求めていますが、いまだ実現をしていない状況です。よって、今日の議案には反対をいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"そういう議論が区民にわからないということで、検証していますということを今まで再三答弁されてきたかと思います。検討というより公開すべきということで、区民の方にお知らせいただきたいということを望みまして、賛成します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"の第６０号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"の第６０号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"公務災害というお話ですが、これは最近あるのかどうかという実情を教えていただきたい。なぜ５年未満から２５年以上ということで金額が変わってくるのか非常に疑問で、むしろ一律でもいいのではないかと思うんですけれど説明を求めました。","respondent":"富田学務課長","answer":"２点目ですが、学校医等につきましては、教育委員会で任命をしているものです。この東京都条例と２３区の条例はいずれも同一とさせていただいておりまして、給与条例を参考にして、こういった年数の基準を考慮しております。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"それとも医師はたくさんいらっしゃいますので、その人たちが輪番でやっていくのか、仕組みとしてはどうなっているのかなという部分を教えてください。これは素朴な疑問として、こういう経験があるから年数によって金額も当然変わってくるんですよというところを教えてほしいと求めました。","respondent":"富田学務課長","answer":"輪番というよりも、学校医等を継続できない事情がない場合においては、継続されている場合が多いです。経験年数による補償基礎額を定めていると考えられ、都条例や本区の条例も、政令の基準にならって経験年数別に補償基礎額を定めているところです。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"今のことに関連して、給与条例に沿ってということですけれども、これは区として同額にするという裁量はあるんでしょうか。不都合がない限り継続して学校医をお願いしているかと思うんですが、同一の方が最長どのぐらいされているものなんか尋ねました。","respondent":"富田学務課長","answer":"考え方としては区独自に、政令のフレームがありますので、そういったものも含めてちょっと難しいかなと考えているところです。申しわけございませんが現在手元にそういった資料を持ってきておりませんので、お答えは控えします。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"最後の質問ですけれども、経験年数ということではなくて、同じ学校でどのぐらいの期間、学校医として同じ先生が、１０年なのか２０年なのか地元の先生なので３０年以上されているのか、そういうところでどのぐらいになっているのかということを質問させていただいたんですが。","respondent":"富田学務課長","answer":"申しわけございません、それぞれの先生方が通算で何年経験があるのかといったことについては、資料を持ち合わせておりません。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"資料を持ち合わせていないというのは、今ないということですか、それとも教育委員会としてそういうことを把握されていないということか尋ねました。","respondent":"富田学務課長","answer":"ただいまこちらに持ち合わせておりません。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"(2)の新設のところで伺いますけれども、例えば制限の内容というところで、３歳未満の子を養育する職員の方たちの超過勤務の実態とか、年間１５０時間を超える超勤といった実態はどうなっていたんか尋ねました。","respondent":"冠木指導課長","answer":"文教委員会で説明をさせていただいているのは、災害のときの対応であるとか、教員に対する超過勤務というのは限定されてあります。担任の任命であるとかそういうレベルから非常に丁寧に対応をしてきておりますので、それぞれの先生方のご事情等を酌む中で学校は対応しているです。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"本当は休暇を取得するほうがいいのに、こういった場合の基準づくりというのは、これから検討事由も含めて進めていかれるのかどうなのかということと。幼稚園、学校教諭に対してそういう方向性でのお考えがもしあれば、お伺いしたいと思います。","respondent":"冠木指導課長、田村庶務課長","answer":"この法律が制定された考え方の中に、実際の勤務の状況を十分に、民間で言えば雇う側が調整をするというようなところはあります。教員ですので現場の校長がそれぞれの勤務状況を把握する中で… 冒頭の説明の中で指導課長が申し上げましたように。あれは制度があってもやはりとりづらいという実態がある程度先行して、逆に今回はそういう制度的な面が区の教員も区の職員もできたです。","id":"exchange-014"},{"speaker":"井上委員","kind":"質問","question":"そこをどう区として率先して、その体制づくりを品川区はどういうふうに、この文教委員会の所管の部分でしていこうとされているのかお伺いします。","respondent":"冠木指導課長","answer":"この件に限らず、校長、教員、職員の代表も含めて集まっていただいて、学校の労働安全について協議する場を既に持っておりますので、この件についてもいろいろな学校の実態等あろうかと思いますので、そのような協議の場で私どもも把握してまいりたいと思ってあります。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"第６２号議案のほうですが、対象は区固有の教職員という理解でいいのか、そのことを教えてください。そういった面で除外のところを読むと、今までと変わらないんじゃないかなという受けとめ方を実際にはしてしまうんですがいかがか尋ねました。","respondent":"冠木指導課長","answer":"その中でこれはどうしても子どもたちの安全にかかわるようなことが出てきた場合には、当然勤務していただくことも出てくることは考えられます。ですので、「職務に支障がある場合」と書いてあるのはそういう意味合いでご理解いただければと思います。","id":"exchange-016"},{"speaker":"金野委員","kind":"質問・要望","question":"先ほどのほかの委員の質問とちょっと関連しますけれども、どのようにしようとされているのか、もし内容がわかるのであれば少し教えていただきたい。それから、この就学前の子どもを持っている教員の方は把握できるわけですから、どのように今の時点ではお考えか尋ねました。","respondent":"冠木指導課長","answer":"そういうところは校長が判断をしながら、母体の保護という視点も当然あろうかと思ってあります。ですので、また校長連絡会等を通して周知はしてまいりますけれども、そういった委員会の中でも話題にしていく必要はあろうかと思っているところです。","id":"exchange-017"},{"speaker":"金野委員","kind":"質問","question":"その労働安全衛生委員会というのは、参考までに年に何回か定期的に行われるものなんか尋ねました。","respondent":"田村庶務課長","answer":"先ほども説明したように、例えば産業医の面談ですとかカウンセラーにつなげるとか、そういう労働安全衛生上の検討をするのが労働安全衛生委員会です。やはりそれぞれの調査事項だとか検討事項が下命され、専門部会で具体的に検討していくということで…","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"それについてはどういうふうに考えるのでしょうか。条例で決めなければいけないことでありますけれど、そういう先生方も配慮していただきたいと思うんですが、その点はいかがか尋ねました。","respondent":"冠木指導課長","answer":"そういう先生方を私どもも大切にしていかなければいけないと考えています。なお、この条例については申請主義ですので、諸般の事情が解決した上で勤務していただくということになろうかと思います。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ配慮していただきながら運営していただきたいと思うんですが、そこは大切にしていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"伊藤副委員長","kind":"質問","question":"ですから法改正がいつあって、そういうことに対して時間がない気がするんですけれど、その対処はどうされるのかということ。それから、それを該当すると思われる方々に対しての周知説明、管理者に対する周知説明等について、まとめてお伺いいたします。","respondent":"冠木指導課長","answer":"なお詳細につきましては、私どもにはちょっとそこまでの情報がないものですから、お答えできないことはご了承いただきたいと考えています。周知につきましては、校長連絡会を通して、十分に趣旨の周知、それから制度の徹底等を周知してまいるというように思ってあります。","id":"exchange-021"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"確かに詳細は総務委員会の所管でしょうから、あえて答弁は求めませんが、今の時期に議案が出てくるのがどうも不思議でならない気がするんです。こういう大きな改正ですから、調整が必要でしょうから、感想だけを述べします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問・要望","question":"賛成ですが、意見を。今に関連して、そういったところを検討していただきながら進めていただきたいということを要望して、賛成です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]},{"id":"topic-03","title":"平成２２年請願第１１号、詰め込みではなく認可保育園増設で待機児解消を求める請願","agenda":"平成２２年請願第１１号、詰め込みではなく認可保育園増設で待機児解消を求める請願","exchanges":[{"speaker":"金野委員","kind":"質問","question":"請願項目の２番目に「５歳児だけを保育園から切り離し」云々とありますけれども、その実態をもうちょっと詳しく教えてください。どんなことでお子さんが生き生きされているのかという分園の状況、親御さんの声、また学校との連携の成果というか状況を詳しく説明を求めました。","respondent":"伊崎待機児童対策担当課長","answer":"例えば校庭で５年生、３年生のお子さんたちとドッジボールをするなど、子供同士の交流もしております。学校に行く時間になりますと、先生のかけ声にパッと支度をして、みんな喜んで出かけていくと聞いております。","id":"exchange-024"},{"speaker":"金野委員","kind":"質問","question":"待機児の解消に向けての一つであるとともに、いわゆる幼・保・小連携もされているという、一つの位置づけだと理解しております。５月、６月で３カ月ですからこの先の見解も含めて、今の保育の内容に対してどんなことが感じられていますか尋ねました。","respondent":"伊崎待機児童対策担当課長","answer":"幼・保・小連携のお尋ねですが、現在のところ小学校のほうで交流プログラムをいろいろ計画してくださっておりまして、今後１年間の成果を見ながら、今後についてもよりよい分園での保育が受けられるように、やっていきたいと考えております。","id":"exchange-025"},{"speaker":"井桁委員","kind":"質問・要望","question":"ちょっと確認で、誤解のないようにしていきたいと思って幾つか質問します。このあたりで詰め込みではないということと人数の確認、それから品川区における分園のあり方というものをもう一度確認させてください。","respondent":"伊崎待機児童対策担当課長","answer":"この中には前回でもご説明申し上げておりますように、品川区といたしましては待機児童となっているのは６６人と考えております。交流というのは当然進められておりまして、特徴をもって進めておりますので、今後もそれぞれの園の特性に合った形で進めていくものと考えております。","id":"exchange-026"},{"speaker":"井桁委員","kind":"質問・要望","question":"いろいろな政策を通じて１人でも多くの待機児童を解消するために日々頑張られているなと、本当にご努力いただいているなというのは感じております。今後１０年、２０年を考えたとき、品川区はやっていっていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここでは認可保育園の増設を求めているんですけれども、国と自治体の責任をどう考えていらっしゃるのかというところをお伺いしたい。１カ月、長い目で見たときにどうなのかという疑問を非常に抱くわけですけれども、その辺をお伺いしたいと思います。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"区はそれに対してどう考えているかですが、待機児童の解消に向けて努力をしていくのが責務と認識しております。場所が変わりましても、園のほうできちっとお子さんの状況に対応しておりますので… ０・１歳児の面積の話ですけれども、今、担当課長からご答弁申し上げましたように、保育所の最低基準であります３.３m2を基準としてやっているものです。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平米数を教えてほしいと再三求めて定員増をしたところの保育室の面積を出されたんですけれども、ちょっと違うな」と思ったんです。そこまで思いをはせていただきたいと思うんですが、いかがか尋ねました。","respondent":"古川子ども未来事業部長、伊崎待機児童対策担当課長","answer":"あらゆる資源を活用して、そして４４％の受け皿をつくる、これが国の考え方だと思いますがよろしいですか。しかし私どもは、見解の相違についてはこれ以上の考え方は申し上げられないと、このように考えております。 私から、５歳児の保育園での居場所というご質問についてお答えいたします。当然、保育園の中にも５歳児の部屋、居場所というものは確保していますので、園の中に居場所がなく落ち着かないというようなことは一切ございません。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"はどういう手を打つんですかというその辺をお伺いして、改善せずしてほかの方法をとっても、この点が一点です。両方きちんとゆとりのあるスペースであってほしいと思うので、やはりこれは子どもにとってマイナスであると思います。","respondent":"古川子ども未来事業部長","answer":"児童福祉法第２４条でいうところの認可保育園を中心にした保育の実施、柔軟な運営でありますとかさまざまな利点も認証では得られると考えています。それと５歳児の居場所という問題、これは非常に難しい要素が出てきます。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"その５歳児が小学校に来てのびのびと生活をして、この教育に関してどういうふうにとらえているのかということをお聞きしたいと思います。それから請願項目の３番目の「大幅増額を国に求めてください」というのは、この間の国の動向を考えていくと、予算は大幅に増えていると思うんですね。","respondent":"伊崎待機児童対策担当課長、吉岡保育課長","answer":"私からは、入所基準と６６人の方の状況について説明いたします。認可外保育園に預けている方、育児休業を延長している方、求職中が続いている方などがいらっしゃいます。 この間ずっと保・幼・小連携を進める中で、連携のさらなる転機というようにも考えて、進めていきたいと考えています。それから、国のほうで子ども園ですとかいろいろ新たな考え方を検討しているということで聞いてありますけれども…","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"それから５歳児のところですけれども、どういう生活をしているのかというところは。この情報開示についてだけお答えほしいと求めました。","respondent":"吉岡保育課長","answer":"５歳児の分園での保育に関して情報の開示等々という話ですけれども、またご要望があれば保護者以外の方も見学いただくことは可能です。運営していく中で支障があれば、隠すものではございませんので、開示ができるように考えていきたいと考えています。","id":"exchange-032"},{"speaker":"井上委員","kind":"提案","question":"私たちも議会質問などを通じてお話ししたことは、何か工夫をされていたり以前と違う取り組みがあるかどうかということを教えてください。このことについてどういう取り組みを進めていこうと考えられているのか、お聞きしたいと思いますとの意見を述べました。","respondent":"吉岡保育課長","answer":"それから外部の検討をというお話でございましたけれども、現在実施をしているものについては、順調に推移していると思ってあります。今後いろいろ問題が出てくれば検討は当然いたしますけれども、今の時点で外部の検討委員会みたいなものを立ち上げる予定はございません。","id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"そうではなくて子育てがつらくて助けを求めたいのかというところをしっかりと、１回実態調査をしたらいいと思うんですね。こういう請願についてももう少しきめの細かな対応策を、区民も求めているところに対応できると思うんですけれど、その辺はいかがか尋ねました。","respondent":"吉岡保育課長","answer":"幼稚園の預かり保育等々、まさにニーズの多様化に対応した多様な対策、多様な施策で対応していくところです。１人３０分、今ただちに実施するという考えはございませんけれども、将来的には検討していくこともあるのかなというようには考えてあります。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"就労のときにも「子どもができたらどうするんですか」みたいなことを女性は問われながら働かなきゃいけないという現実を見れば、実際にもっと広く。そういうところでぜひ、女性も男性もできなきゃいけないというつもりでいるところを品川区でぜひ実現してほしいと思うので、これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"意見","question":"最低基準を守っているということについて１点聞きたいのは、保育室の面積基準はあくまでも保育室のみで基準をクリアしているのか。計算の仕方なんですけれども、保育室を人数で割り返して、すべてクリアしているのかどうかだけしっかりお尋ねしたいと思いますとの意見を述べました。","respondent":"吉岡保育課長","answer":"３月の委員会でお話ししたときに、マイナス、不足が出ているところが２カ所あったと思います。当然その考え方は区が独自で勝手に判断しているということではございません。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"はっきりさせていただきたいのは、保育室を割り返したのではなく、保育室の基準をクリアしているのではないという点は明らかですね。確認させてください。","respondent":"吉岡保育課長","answer":"割っているのは明らかというか、面積基準を考えるときに、その年齢児の保育室、例えば２歳児なら２歳児の保育室の面積が、人数が増えて不足が生じた場合については、施設内の他の面積を有効に活用して保育を実施して差し支えないという考え方が示されているです。","id":"exchange-037"},{"speaker":"金野委員","kind":"質問・要望","question":"公明党も結論を出してほしいと求めました。結果としては不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"女性が働くのが当たり前の時代に、保育園が足りなくて働けないという自体は一刻も早く改善を求められると思います。ぜひ国に求めるところは財政面でもしっかりと求めていただいて、５歳児問題では、実験的なやり方はやめるべきだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"本間委員","kind":"質問・要望","question":"現在審議中とか要望というこれまでの経緯がありますので、１歩足を前に踏み出したものと評価し、この部分はちょっと品川区の方針とは違うです。全体を通して結論をいいますと、この点については不採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"あくまでも教育の質から始まるものだと思っていますので、そこからどういう環境が必要なのかという議論をぜひしていただきたいと考えています。国の方針を決めるにはやはり有権者の皆さんも大きな役割を担っているわけですから、そういうところからの見直しもできないかと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"それから５歳児だけの保育園というのは、やはり昨年１０月に待機児対策として唐突に出されたものであるということと、ここは思いとしてはわかります。待機児解消を求めるということでは、今どういうふうにというところを求めている思いには賛同しますので、趣旨採択です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/746735?Template=document&Id=4702#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2010-01-01&TermEnd=2010-12-31"}],"sourceMeta":{"pages":0,"characters":40012,"voices":130}}]);
